const EVE_RELAY_FETCH_TIMEOUT_MS=15000;
async function eveFetch(url,options={},timeoutMs=EVE_RELAY_FETCH_TIMEOUT_MS){
  const controller=new AbortController(),external=options?.signal;
  let timedOut=false;
  const abortFromExternal=()=>controller.abort(external?.reason);
  if(external){
    if(external.aborted)abortFromExternal();
    else external.addEventListener('abort',abortFromExternal,{once:true});
  }
  const timer=setTimeout(()=>{timedOut=true;controller.abort()},Math.max(1000,Number(timeoutMs)||EVE_RELAY_FETCH_TIMEOUT_MS));
  try{
    return await fetch(url,{...options,signal:controller.signal});
  }catch(err){
    if(timedOut){
      const timeoutError=new Error('Eve request timed out');
      timeoutError.name='TimeoutError';
      timeoutError.code='EVE_TIMEOUT';
      timeoutError.cause=err;
      throw timeoutError;
    }
    throw err;
  }finally{
    clearTimeout(timer);
    external?.removeEventListener?.('abort',abortFromExternal);
  }
}
const encoder=new TextEncoder();
const decoder=new TextDecoder();

function bytesToB64Url(bytes){return btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function b64UrlToBytes(raw){const s=String(raw||'').replace(/-/g,'+').replace(/_/g,'/');const padded=s+'='.repeat((4-s.length%4)%4);return Uint8Array.from(atob(padded),c=>c.charCodeAt(0))}
function secureSlug(){return bytesToB64Url(crypto.getRandomValues(new Uint8Array(18)))}
function newRelayKey(){return bytesToB64Url(crypto.getRandomValues(new Uint8Array(32)))}
async function capabilityProof(value){const digest=await crypto.subtle.digest('SHA-256',encoder.encode(String(value||'')));return bytesToB64Url(new Uint8Array(digest))}
async function importRawAesKey(raw){return crypto.subtle.importKey('raw',b64UrlToBytes(raw),{name:'AES-GCM'},false,['encrypt','decrypt'])}
async function encryptWithKey(data,raw){const key=await importRawAesKey(raw);const iv=crypto.getRandomValues(new Uint8Array(12));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,encoder.encode(JSON.stringify(data)));return {v:1,iv:bytesToB64Url(iv),data:bytesToB64Url(new Uint8Array(cipher))}}
async function decryptWithKey(payload,raw){const key=await importRawAesKey(raw);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64UrlToBytes(payload.iv)},key,b64UrlToBytes(payload.data));return JSON.parse(decoder.decode(plain))}

function bytesToB64UrlLarge(bytes){let binary='';const chunk=0x8000;for(let i=0;i<bytes.length;i+=chunk)binary+=String.fromCharCode(...bytes.subarray(i,Math.min(i+chunk,bytes.length)));return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
async function encryptRecordingBlobWithKey(blob,raw){const key=await importRawAesKey(raw),iv=crypto.getRandomValues(new Uint8Array(12)),plain=await blob.arrayBuffer(),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain);return {v:1,iv:bytesToB64Url(iv),data:bytesToB64UrlLarge(new Uint8Array(cipher)),mimeType:blob.type||'application/octet-stream',size:blob.size}}
async function decryptRecordingBlobWithKey(payload,raw){const key=await importRawAesKey(raw),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64UrlToBytes(payload.iv)},key,b64UrlToBytes(payload.data));return new Blob([plain],{type:payload.mimeType||'application/octet-stream'})}
async function saveLocalRecording(recordingId,blob){const key=await getKey(true),iv=crypto.getRandomValues(new Uint8Array(12)),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,await blob.arrayBuffer()),payload={v:1,iv:bytesToB64Url(iv),data:bytesToB64UrlLarge(new Uint8Array(cipher)),mimeType:blob.type||'application/octet-stream',size:blob.size};await idbSet(RECORDING_PREFIX+recordingId,JSON.stringify(payload));return {recordingId,storage:'local',mimeType:payload.mimeType,size:blob.size}}
async function loadLocalRecording(recordingId){const raw=await idbGet(RECORDING_PREFIX+recordingId);if(!raw)throw new Error('Recording is not available in this browser.');const payload=JSON.parse(raw),key=await getKey(false),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64UrlToBytes(payload.iv)},key,b64UrlToBytes(payload.data));return new Blob([plain],{type:payload.mimeType||'application/octet-stream'})}



