function historyBucket(){const s=currentStudy();if(!s)return null;return builderHistory[s.id]||(builderHistory[s.id]={undo:[],redo:[],lastKey:null,lastAt:0})}
function recordStudyHistory(key='edit',coalesce=true){if(state.view!=='builder')return;const s=currentStudy(),h=historyBucket();if(!s||!h)return;const now=Date.now();if(coalesce&&h.lastKey===key&&now-h.lastAt<900){h.lastAt=now;return}const snapshot=JSON.stringify(s);if(h.undo[h.undo.length-1]!==snapshot){h.undo.push(snapshot);if(h.undo.length>50)h.undo.shift()}h.redo=[];h.lastKey=key;h.lastAt=now}
function canUndoBuilder(){return !!historyBucket()?.undo.length}
function canRedoBuilder(){return !!historyBucket()?.redo.length}
function restoreStudySnapshot(snapshot){const restored=JSON.parse(snapshot);const i=state.studies.findIndex(x=>x.id===restored.id);if(i<0)return;state.studies[i]=restored;ensureStudyPages(restored);if(!restored.pages.some(p=>p.id===state.activePageId))state.activePageId=restored.pages[0]?.id||null;if(!restored.blocks.some(b=>b.id===state.activeBlockId&&b.pageId===state.activePageId))state.activeBlockId=pageBlocks(restored,state.activePageId)[0]?.id||null;state.saveState='Unsaved changes';scheduleSave();render()}
function undoBuilder(){const s=currentStudy(),h=historyBucket();if(!s||!h?.undo.length)return;h.redo.push(JSON.stringify(s));h.lastKey=null;restoreStudySnapshot(h.undo.pop())}
function redoBuilder(){const s=currentStudy(),h=historyBucket();if(!s||!h?.redo.length)return;h.undo.push(JSON.stringify(s));h.lastKey=null;restoreStudySnapshot(h.redo.pop())}



async function init(){
  let legacySetup=false;
  try{
    const loaded=await loadEncryptedStrict(STORE);
    legacySetup=!!loaded.exists&&!loaded.data?.setup;
    if(loaded.exists&&loaded.data)state={...state,...loaded.data,modal:null,preview:false,responses:[]};
    state.workspaceRevision=Number(await idbGet(WORKSPACE_REV_KEY)||state.workspaceRevision||0);
    await migrateLegacyResponses();
    state.responses=await loadAllResponseRecords();
  }catch(err){
    console.error('Workspace recovery error',err);
    state.recoveryError=err?.code==='MISSING_KEY'?'Encrypted Eve data exists, but its local decryption key is missing. Restore a portable backup or recover the original browser key before continuing.':'Eve found encrypted local data that could not be decrypted. It has not been overwritten.';
  }
  state.findings=(Array.isArray(state.findings)?state.findings:[]).map(f=>({...f,kind:f.kind||'saved',updatedAt:Number(f.updatedAt||f.createdAt||Date.now()),tags:normaliseInsightTags(f.tags||[]),sourceExcerpt:f.sourceExcerpt??f.evidence??'',sourceSection:f.sourceSection||''}));
  state.participantSegments=Array.isArray(state.participantSegments)?state.participantSegments:[];
  state.reviewFilters=state.reviewFilters&&typeof state.reviewFilters==='object'?state.reviewFilters:{};state.reviewSections=state.reviewSections&&typeof state.reviewSections==='object'?state.reviewSections:{};state.consentOverrides=state.consentOverrides&&typeof state.consentOverrides==='object'?state.consentOverrides:{};
  state.participantSource=state.participantSource||'all';state.participantRouteSource='direct';state.participantSegmentId=null;state.participantCampaignId=null;state.participantRouteVersion=null;state.segmentModal=false;
  state.storage={provider:'SharePoint',connected:false,location:'Customer Research / Eve',permission:'App folder only',lastSync:null,connectors:{google:null,microsoft:null},cloudSyncState:'idle',cloudSyncError:'',...(state.storage||{})};
  state.storage.connectors={google:null,microsoft:null,...(state.storage.connectors||{})};
  state.globalSettings={defaultAnonymous:true,defaultAi:'anonymous',defaultCompletionMessage:'Thank you for taking part.',defaultResponseTarget:50,defaultStorageProvider:'organisation',...(state.globalSettings||{})};
  if(!['off','anonymous','full'].includes(state.globalSettings.defaultAi))state.globalSettings.defaultAi='anonymous';
  if(!['organisation','SharePoint','Google Drive'].includes(state.globalSettings.defaultStorageProvider))state.globalSettings.defaultStorageProvider='organisation';
  state.globalSettings.defaultResponseTarget=Math.max(1,Math.min(100000,Math.round(Number(state.globalSettings.defaultResponseTarget)||50)));
  await EveDeployment.prepareLocation?.();
  state.setup=EveSetup.normalise(state.setup,{legacy:legacySetup});
  EveCapabilities.applyDefaults(state);
  await EveDeployment.initialiseAppState?.(state);
  state.previewScope=state.previewScope||'study';state.collapsedPages=state.collapsedPages||{};state.sectionSettingsId=null;state.sendShareMode=state.sendShareMode==='qr'?'qr':'link';state.sendShareSegmentId=state.sendShareSegmentId||'all';state.sendExpandedSegmentId=state.sendExpandedSegmentId||'all';
  state.studies=(state.studies||[]).map(migrateStudy);
  if(!state.studies.length&&!state.recoveryError)state.studies=[defaultStudy()];
  await purgeExpiredArchivedStudies();
  routeFromHash();
  if(state.view!=='participant'&&EveSetup.needsOnboarding(state.setup))state.view='setup';
  if(state.view==='participant')await hydrateParticipantFromRelay();
  state.relayOnline=await relayHealth();
  setupCrossTabSync();
  setupEveNavigationExtensionBridge();
  render();
  if(state.view==='review'&&currentStudy())syncRelayResponsesForStudy(currentStudy(),true).catch(err=>console.warn('Review response sync failed',err)).finally(()=>render());
  window.addEventListener('hashchange',async()=>{
    routeFromHash();
    if(state.view==='participant'){
      try{await hydrateParticipantFromRelay()}catch(err){console.warn('Participant study refresh failed',err)}
      render();
      return;
    }
    render();
    if(['send','review'].includes(state.view)){
      try{state.relayOnline=await relayHealth()}catch(err){state.relayOnline=false;console.warn('Participant collection health check failed',err)}
      if(state.view==='review'&&currentStudy()){
        try{await syncRelayResponsesForStudy(currentStudy(),true)}catch(err){console.warn('Review response sync failed',err)}
      }
      render();
    }
  });
  window.addEventListener('keydown',handleBuilderShortcuts);
  window.addEventListener('pagehide',()=>{flushParticipantDraft();flushAutosave()});
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){flushParticipantDraft();flushAutosave()}});
}

function migrateStudy(s){
  s.settings={anonymous:true,ai:'anonymous',collectEmail:false,recontact:false,startAtUtc:'',closeAt:'',closeAtUtc:'',completionMessage:'Thank you for taking part.',storageProvider:'organisation',storageLocation:'',...(s.settings||{})};
  if(!s.slug||String(s.slug).length<12)s.slug=secureSlug();
  if(!s.publishedVersions||typeof s.publishedVersions!=='object')s.publishedVersions={};
  if(s.publishedSnapshot?.data&&!s.publishedVersions[String(s.publishedSnapshot.version||s.version||1)])s.publishedVersions[String(s.publishedSnapshot.version||s.version||1)]=JSON.parse(JSON.stringify(s.publishedSnapshot));
  const latestVersion=latestPublishedVersion(s);
  if(latestVersion&&!s.publishedSnapshot)s.publishedSnapshot=s.publishedVersions[String(latestVersion)];
  if(s.hasUnpublishedChanges===undefined)s.hasUnpublishedChanges=false;
  if(s.publishedAt===undefined)s.publishedAt=null;
  s.archivedAt=Number(s.archivedAt)||null;
  s.archivePurgeAt=Number(s.archivePurgeAt)||(s.archivedAt?s.archivedAt+30*24*60*60*1000:null);
  s.archivedFromStatus=s.archivedFromStatus||null;
  s.archivePurgeErrorAt=Number(s.archivePurgeErrorAt)||null;
  if(!Array.isArray(s.sendCampaigns))s.sendCampaigns=[];
  s.sendCampaigns=s.sendCampaigns.map(c=>({...c,archived:!!c.archived}));
  if(!Array.isArray(s.sendSegments))s.sendSegments=[];
  if(!Number.isFinite(Number(s.sendDefaultTarget))||Number(s.sendDefaultTarget)<1)s.sendDefaultTarget=Math.max(1,Number(s.settings?.target)||50);
  s.sendDefaultTarget=Math.max(1,Math.round(Number(s.sendDefaultTarget)||50));
  s.sendSegments=s.sendSegments.map(seg=>({...seg,target:Math.max(1,Math.round(Number(seg.target)||50)),archived:!!seg.archived}));
  if(s.relayKey===undefined)s.relayKey=null;if(!s.relayVersionKeys||typeof s.relayVersionKeys!=='object')s.relayVersionKeys={};if(s.relayKey&&latestVersion&&!s.relayVersionKeys[String(latestVersion)])s.relayVersionKeys[String(latestVersion)]=s.relayKey;if(latestVersion&&s.relayVersionKeys[String(latestVersion)])s.relayKey=s.relayVersionKeys[String(latestVersion)];if(s.relayAdminToken===undefined)s.relayAdminToken=null;if(s.relayPublished===undefined)s.relayPublished=false;if(!s.settings.closeAtUtc&&s.settings.closeAt){const d=new Date(`${s.settings.closeAt}T23:59:59.999`);if(Number.isFinite(d.getTime()))s.settings.closeAtUtc=d.toISOString()}if(s.status==='live'&&!latestPublishedVersion(s))s.status='draft';
  ensureStudyPages(s);
  for(const b of s.blocks||[]){
    if(b.type==='consent'&&!Array.isArray(b.confirmations))b.confirmations=[{id:uid(),text:'I agree to take part in this research.'}];
    if(b.type==='recording'){if(!['audio','video'].includes(b.recordingMode))b.recordingMode='audio';if(!Number.isFinite(Number(b.recordingTimeLimitMinutes))||Number(b.recordingTimeLimitMinutes)<=0)b.recordingTimeLimitMinutes=2;if(b.prompt===undefined)b.prompt='Tell us what you are thinking.'}
    if(b.type==='navigationTask'){const legacy=['audio','video','screen'].includes(b.navigationRecordingMode)?b.navigationRecordingMode:'none';if(typeof b.navigationRecordAudio!=='boolean'&&typeof b.navigationRecordVideo!=='boolean'&&typeof b.navigationRecordScreen!=='boolean'){b.navigationRecordAudio=legacy==='audio';b.navigationRecordVideo=legacy==='video';b.navigationRecordScreen=legacy==='screen'}else{b.navigationRecordAudio=!!b.navigationRecordAudio;b.navigationRecordVideo=!!b.navigationRecordVideo;b.navigationRecordScreen=!!b.navigationRecordScreen}b.navigationRecordingMode='none'}
    if(b.type==='panelSignup'){if(b.panelIntro===undefined)b.panelIntro='Join our participant panel to hear about future research opportunities.';if(typeof b.panelTermsEnabled!=='boolean')b.panelTermsEnabled=true;if(b.panelTerms===undefined)b.panelTerms='By joining the panel, you agree that the research team can contact you about future research opportunities.';if(!String(b.panelConsentLabel||'').trim())b.panelConsentLabel='I agree to join the research participant panel.';if(b.panelWelcomeSubject==='Welcome to our research panel')b.panelWelcomeSubject='';if(b.panelWelcomeMessage==='Thank you for joining our research panel. We may contact you about future research opportunities.')b.panelWelcomeMessage='';b.panelWelcomeSubject=String(b.panelWelcomeSubject||'');b.panelWelcomeMessage=String(b.panelWelcomeMessage||'');b.required=false}
  }
  refreshDirty(s);return s;
}

function openLocalDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(DB_STORE))db.createObjectStore(DB_STORE)};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function idbGet(key){const db=await openLocalDb();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readonly');const req=tx.objectStore(DB_STORE).get(key);req.onsuccess=()=>resolve(req.result??null);req.onerror=()=>reject(req.error);tx.oncomplete=()=>db.close()})}
async function idbSet(key,value){const db=await openLocalDb();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).put(value,key);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function idbDelete(key){const db=await openLocalDb();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).delete(key);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function idbKeys(){const db=await openLocalDb();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readonly');const req=tx.objectStore(DB_STORE).getAllKeys();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error);tx.oncomplete=()=>db.close()})}
function localKeyRaw(create=true){let raw=localStorage.getItem(KEY_STORE);if(!raw&&create){const bytes=crypto.getRandomValues(new Uint8Array(32));raw=btoa(String.fromCharCode(...bytes));localStorage.setItem(KEY_STORE,raw)}return raw}
async function getKey(create=true){const raw=localKeyRaw(create);if(!raw){const e=new Error('Local encryption key missing');e.code='MISSING_KEY';throw e}const bytes=Uint8Array.from(atob(raw),c=>c.charCodeAt(0));return crypto.subtle.importKey('raw',bytes,{name:'AES-GCM'},false,['encrypt','decrypt'])}
async function encrypt(data){const key=await getKey(true);const iv=crypto.getRandomValues(new Uint8Array(12));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,encoder.encode(JSON.stringify(data)));return {v:1,iv:Array.from(iv),data:Array.from(new Uint8Array(cipher))}}
async function decrypt(payload){const key=await getKey(false);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:new Uint8Array(payload.iv)},key,new Uint8Array(payload.data));return JSON.parse(decoder.decode(plain))}
async function loadEncryptedStrict(k){const raw=await idbGet(k)||localStorage.getItem(k);if(!raw)return {exists:false,data:null};if(!localKeyRaw(false)){const e=new Error('Encrypted data exists without a local key');e.code='MISSING_KEY';throw e}try{const data=await decrypt(JSON.parse(raw));if(localStorage.getItem(k)){await idbSet(k,raw);localStorage.removeItem(k)}return {exists:true,data}}catch(err){if(!err.code)err.code='DECRYPT_FAILED';throw err}}
async function loadEncrypted(k){try{return (await loadEncryptedStrict(k)).data}catch(e){console.warn('Could not decrypt local data',e);return null}}
function workspacePayload(){const safe={...state,modal:null,preview:false,sectionSettingsId:null,responses:undefined,remoteParticipantStudy:null,remoteParticipantBase:null,recoveryError:null,relayOnline:false,externalWorkspaceChange:false,navExtensionAvailable:false,navExtensionVersion:null,navExtensionResults:{}};safe.saveState='Saved locally ✓';return safe}
async function persistWorkspace(throwOnError=false,{force=false,skipCloud=false}={}){
  state.saveState='Saving…';renderSaveState();
  try{
    const durableRev=Number(await idbGet(WORKSPACE_REV_KEY)||0);
    if(!force&&durableRev!==Number(state.workspaceRevision||0)){state.externalWorkspaceChange=true;const e=new Error('Workspace changed in another tab');e.code='WORKSPACE_CONFLICT';throw e}
    const nextRev=durableRev+1;const safe=workspacePayload();safe.workspaceRevision=nextRev;
    await idbSet(STORE,JSON.stringify(await encrypt(safe)));await idbSet(WORKSPACE_REV_KEY,String(nextRev));
    state.workspaceRevision=nextRev;state.externalWorkspaceChange=false;state.saveState='Saved locally ✓';renderSaveState();
    syncChannel?.postMessage({type:'workspace',revision:nextRev});if(!skipCloud)globalThis.EveCloud?.scheduleAll?.();return true;
  }catch(err){state.saveState=err?.code==='WORKSPACE_CONFLICT'?'Save conflict ⚠':'Save failed ⚠';renderSaveState();console.error('Workspace save failed',err);if(throwOnError)throw err;return false}
}
async function saveResponseRecord(response){const key=RESPONSE_PREFIX+response.id;await idbSet(key,JSON.stringify(await encrypt(response)));const i=state.responses.findIndex(r=>r.id===response.id);if(i>=0)state.responses[i]=response;else state.responses.push(response);syncChannel?.postMessage({type:'response',id:response.id});globalThis.EveCloud?.scheduleForStudy?.(response.studyId);return response}
async function loadResponseRecord(id){const raw=await idbGet(RESPONSE_PREFIX+id);return raw?decrypt(JSON.parse(raw)):null}
async function loadAllResponseRecords(){const keys=(await idbKeys()).filter(k=>String(k).startsWith(RESPONSE_PREFIX));const out=[];for(const k of keys){try{const raw=await idbGet(k);if(raw)out.push(await decrypt(JSON.parse(raw)))}catch(e){console.warn('Unreadable response record',k,e)}}return out.sort((a,b)=>(a.submittedAt||0)-(b.submittedAt||0))}
async function migrateLegacyResponses(){const legacy=await loadEncrypted(RESPONSE_STORE);if(Array.isArray(legacy)&&legacy.length){for(const r of legacy)if(r?.id)await saveResponseRecord(r);await idbDelete(RESPONSE_STORE)}}
function scheduleSave(){clearTimeout(autosaveTimer);const s=currentStudy();if(['builder','settings'].includes(state.view)&&s){s.updatedAt=Date.now();refreshDirty(s)}state.saveState='Unsaved changes';renderSaveState();autosaveTimer=setTimeout(()=>persistWorkspace(false),120)}
function flushAutosave(){if(!autosaveTimer&&state.saveState!=='Unsaved changes')return;clearTimeout(autosaveTimer);autosaveTimer=null;persistWorkspace(false).catch(()=>{})}
function renderSaveState(){const el=document.querySelector('[data-save]');if(el)el.textContent=state.saveState}
let syncChannel=null;
function setupCrossTabSync(){if(!('BroadcastChannel'in window))return;syncChannel=new BroadcastChannel('researchos-sync-v1');syncChannel.onmessage=async e=>{if(e.data?.type==='response'&&e.data.id){const r=await loadResponseRecord(e.data.id);if(r&&!state.responses.some(x=>x.id===r.id)){state.responses.push(r);if(['review','participants','home'].includes(state.view))render()}}if(e.data?.type==='workspace'&&Number(e.data.revision)>Number(state.workspaceRevision)){state.externalWorkspaceChange=true;if(state.saveState==='Saved locally ✓')state.saveState='External changes ⚠';renderSaveState()}}}

function handleBuilderShortcuts(e){
  if(state.view!=='builder')return;
  const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||document.activeElement?.isContentEditable;
  if(e.key==='Escape'){if(state.sectionSettingsId){e.preventDefault();state.sectionSettingsId=null;render();return}if(state.modal||state.preview){e.preventDefault();state.modal=null;state.preview=false;render()}return}
  if(typing)return;
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();if(e.shiftKey)redoBuilder();else undoBuilder();return}
  if(e.key==='/'){e.preventDefault();state.modal='add';render();return}
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'&&state.activeBlockId){e.preventDefault();duplicateBlock(state.activeBlockId);return}
  if(e.altKey&&e.key==='ArrowUp'&&state.activeBlockId){e.preventDefault();moveBlock(state.activeBlockId,-1);return}
  if(e.altKey&&e.key==='ArrowDown'&&state.activeBlockId){e.preventDefault();moveBlock(state.activeBlockId,1);return}
}


function routeFromHash(){
  const h=EveDeployment.currentHash?.()||location.hash.slice(1);
  if(h.startsWith('/s/')){state.view='participant';const raw=h.split('/')[2]||'';const [slug,q='']=raw.split('?');const qp=new URLSearchParams(q);state.participantSlug=slug;state.participantRouteSource=qp.get('src')||'direct';state.participantSegmentId=qp.get('seg')||null;state.participantCampaignId=qp.get('cmp')||null;state.participantRouteVersion=Number(qp.get('v')||0)||null;state.participantRelayKey=qp.get('k')||null;state.participantInviteToken=qp.get('inv')||null;return}
  if(h==='/setup'){state.view='setup';return}
  if(h.startsWith('/study/')){const [, ,id,tab]=h.split('/');state.activeStudyId=id;const target=state.studies.find(x=>x.id===id);if(target&&isStudyArchived(target)){state.activeStudyId=null;state.sidebarStudyId=null;state.sidebarCollapsed=false;state.view='archive';return}state.view=(tab==='review'||tab==='results')?'review':tab==='send'?'send':tab==='settings'?'settings':'builder';if(state.view!=='builder')state.sectionSettingsId=null;if(state.sidebarStudyId!==id){state.sidebarStudyId=id;state.sidebarCollapsed=true}const s=currentStudy();if(s){ensureStudyPages(s);ensureValidReviewFilter(s);if(!state.activePageId||!s.pages.some(p=>p.id===state.activePageId))state.activePageId=s.pages[0]?.id||null;const visible=pageBlocks(s,state.activePageId);if(!state.activeBlockId||!visible.some(b=>b.id===state.activeBlockId))state.activeBlockId=visible[0]?.id||null}return}
  state.sidebarStudyId=null;state.sidebarCollapsed=false;state.sectionSettingsId=null;
  if(h==='/studies')state.view='studies';else if(h==='/archive')state.view='archive';else if(h==='/storage')state.view='storage';else if(h==='/settings')state.view='globalSettings';else if(h==='/participants'){state.view='participants';panelDirectory.loaded=false;}else if(h==='/repository')state.view='repository';else if(h==='/templates')state.view='templates';else state.view='home';
}
async function navigate(path){
  if(state.externalWorkspaceChange&&['builder','settings','send'].includes(state.view)){const leave=await miniConfirm('Newer workspace changes exist','Another Eve tab saved a newer workspace version. Reload before continuing if you want to avoid working from stale data.','Continue anyway');if(!leave)return}
  if(['Save failed ⚠','Save conflict ⚠'].includes(state.saveState)&&['builder','settings'].includes(state.view)){const leave=await miniConfirm('Leave with unsaved changes?','Eve could not safely save your latest edits locally. Leaving this screen may lose those changes.','Leave anyway');if(!leave)return}
  location.hash=path;
}
async function reloadLatestWorkspace(){
  const risky=!['Saved locally ✓','Saved ✓','External changes ⚠'].includes(state.saveState);
  if(risky){const ok=await miniConfirm('Reload latest workspace?',"This tab has local edits that may not have been saved safely. Reloading will discard this tab's in-memory copy and use the newest durable workspace.",'Reload latest');if(!ok)return}
  location.reload();
}
const ARCHIVE_RETENTION_MS=30*24*60*60*1000;
function isStudyArchived(s){return !!Number(s?.archivedAt)}
function activeStudies(){return (state.studies||[]).filter(s=>!isStudyArchived(s))}
function archivedStudies(){return (state.studies||[]).filter(isStudyArchived)}
function archiveDaysRemaining(s,now=Date.now()){const purge=Number(s?.archivePurgeAt)||(Number(s?.archivedAt)||now)+ARCHIVE_RETENTION_MS;return Math.max(0,Math.ceil((purge-now)/(24*60*60*1000)))}
function formatArchiveDate(value){const n=Number(value);return Number.isFinite(n)&&n>0?new Date(n).toLocaleDateString([], {day:'numeric',month:'short',year:'numeric'}):'—'}
function currentStudy(){return state.studies.find(s=>s.id===state.activeStudyId)}
function ensureStudyPages(s){if(!s)return s;if(!Array.isArray(s.pages)||!s.pages.length){const pageId=uid();s.pages=[{id:pageId,title:'Page 1'}];(s.blocks||[]).forEach(b=>b.pageId=pageId)}else{const fallback=s.pages[0].id;(s.blocks||[]).forEach(b=>{if(!b.pageId||!s.pages.some(p=>p.id===b.pageId))b.pageId=fallback})}return s}
function studyPages(s){ensureStudyPages(s);return s?.pages||[]}
function currentPage(){const s=currentStudy();if(!s)return null;ensureStudyPages(s);return s.pages.find(p=>p.id===state.activePageId)||s.pages[0]||null}
function pageBlocks(s,pageId){if(!s)return[];ensureStudyPages(s);return (s.blocks||[]).filter(b=>b.pageId===pageId)}
function orderedBlocks(s){if(!s)return[];ensureStudyPages(s);return s.pages.flatMap(p=>pageBlocks(s,p.id))}
function responseActiveBlocks(s,getValue){const sequence=orderedBlocks(s),screenIndex=sequence.findIndex(b=>b.type==='screener'&&b.screenOut&&getValue(b.id)===b.screenOut);return {blocks:screenIndex>=0?sequence.slice(0,screenIndex+1):sequence,screenedOut:screenIndex>=0,screenIndex}}
function latestPublishedVersion(s){const versions=Object.keys(s?.publishedVersions||{}).map(Number).filter(Number.isFinite);return versions.length?Math.max(...versions):s?.publishedSnapshot?.version||0}
function snapshotForVersion(s,version){const v=Number(version||latestPublishedVersion(s));return s?.publishedVersions?.[String(v)]||((s?.publishedSnapshot?.version||0)===v?s.publishedSnapshot:null)}
function publishedStudy(s,version){const snap=snapshotForVersion(s,version);const out=snap?.data||null;if(out)ensureStudyPages(out);return out}
function versionedStudyData(s){return {id:s.id,slug:s.slug,title:s.title,method:s.method,panelStudyToken:s.panelStudyToken||'',settings:JSON.parse(JSON.stringify(s.settings||{})),pages:JSON.parse(JSON.stringify(s.pages||[])),blocks:JSON.parse(JSON.stringify(s.blocks||[]))}}
function refreshDirty(s){if(!s)return false;const latest=snapshotForVersion(s,latestPublishedVersion(s));if(!latest){s.hasUnpublishedChanges=false;return false}try{s.hasUnpublishedChanges=JSON.stringify(versionedStudyData(s))!==JSON.stringify(versionedStudyData(latest.data));}catch{s.hasUnpublishedChanges=true}return s.hasUnpublishedChanges}
function startingInstant(s){const raw=s?.settings?.startAtUtc;if(!raw)return null;const t=Date.parse(raw);return Number.isFinite(t)?t:null}
function closingInstant(s){const raw=s?.settings?.closeAtUtc;if(raw){const t=Date.parse(raw);return Number.isFinite(t)?t:null}const legacy=s?.settings?.closeAt;if(!legacy)return null;const local=new Date(`${legacy}T23:59:59.999`);return Number.isFinite(local.getTime())?local.getTime():null}
function formatScheduleInstant(value){const t=typeof value==='number'?value:Date.parse(value||'');if(!Number.isFinite(t))return'';return new Date(t).toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}
function studyAvailability(base){
  if(!base)return {available:false,reason:'This study could not be found.'};
  if(base.status!=='live')return {available:false,reason:base.status==='closed'?'This study is now closed.':'This study is not currently accepting responses.'};
  const s=publishedStudy(base,base.version);if(!s)return {available:false,reason:'This study does not have a valid live version.'};
  const start=startingInstant(s),close=closingInstant(s),now=Date.now();
  if(start&&now<start)return {available:false,reason:`This study opens ${formatScheduleInstant(start)}.`};
  if(close&&now>=close)return {available:false,reason:`This study closed ${formatScheduleInstant(close)}.`};
  return {available:true,reason:''};
}
function currentBlock(){const s=currentStudy();if(!s)return null;const page=currentPage();return s.blocks.find(b=>b.id===state.activeBlockId&&(!page||b.pageId===page.id))||pageBlocks(s,page?.id)[0]||null}
function studyResponses(id,version=null){return state.responses.filter(r=>r.studyId===id&&(version===null||Number(r.studyVersion)===Number(version)))}
function researchResponses(responses=state.responses){return responses.filter(r=>r.environment!=='demo')}
function reviewStateFor(s){const latest=latestPublishedVersion(s)||s.version||1;const entry=state.reviewFilters[s.id]||(state.reviewFilters[s.id]={version:latest,segment:'all'});if(!snapshotForVersion(s,entry.version))entry.version=latest;if(!entry.segment)entry.segment='all';return entry}
function ensureValidReviewFilter(s){if(!s)return;const r=reviewStateFor(s);const validSegments=new Set(['all']);for(const x of studyResponses(s.id,r.version)){if(x.recruitmentSegmentId)validSegments.add(`recruit::${x.recruitmentSegmentId}`);if(x.attributedSegmentId)validSegments.add(`segment::${x.attributedSegmentId}`);if(x.source)validSegments.add(`source::${x.source}`);if(x.campaignId)validSegments.add(`campaign::${x.campaignId}`)}const schema=publishedStudy(s,r.version);for(const b of schema?.blocks||[])if(['question','screener','multiChoice','preference'].includes(b.type))for(const o of b.options||[])validSegments.add(`answer::${b.id}::${o}`);if(!validSegments.has(r.segment))r.segment='all'}
function setReviewSegment(s,value){const r=reviewStateFor(s);r.segment=value||'all';render()}
function setReviewVersion(studyId,version){const s=state.studies.find(x=>x.id===studyId);if(!s)return;const r=reviewStateFor(s);r.version=Number(version);r.segment='all';syncRelayResponsesForStudy(s,true).then(()=>render())}
function validateStudySettings(s){const issues=[];const store=resolvedStudyStorage(s),start=startingInstant(s),close=closingInstant(s);if(!store.provider||!store.location)issues.push('Choose a valid storage destination.');if(s.settings?.startAtUtc&&!start)issues.push('Choose a valid study start date and time.');if(s.settings?.closeAtUtc&&!close)issues.push('Choose a valid study end date and time.');if(start&&close&&close<=start)issues.push('Study end time must be after the start time.');if(close&&close<=Date.now())issues.push('Study end time must be in the future when going live.');if(s.settings?.recontact&&!s.settings?.collectEmail)issues.push('Recontact requires participant email collection.');issues.push(...EveCapabilities.studyIssues(s));return [...new Set(issues)]}
function esc(v=''){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function richTextSize(b,key){const size=String(b?.richTextSizes?.[key]||'normal');return ['small','normal','large'].includes(size)?size:'normal'}
function sanitizeRichHtml(raw=''){if(typeof document==='undefined')return esc(String(raw||''));const template=document.createElement('template');template.innerHTML=String(raw||'');const allowed=new Set(['B','STRONG','I','EM','UL','LI','BR','DIV','P']);const clean=node=>{for(const child of [...node.childNodes]){if(child.nodeType===Node.TEXT_NODE)continue;if(child.nodeType!==Node.ELEMENT_NODE){child.remove();continue}if(!allowed.has(child.tagName)){const frag=document.createDocumentFragment();while(child.firstChild)frag.appendChild(child.firstChild);child.replaceWith(frag);clean(node);continue}for(const attr of [...child.attributes])child.removeAttribute(attr.name);clean(child)}};clean(template.content);return template.innerHTML}
function richPlainText(raw=''){if(typeof document==='undefined')return String(raw||'').replace(/<[^>]+>/g,' ');const el=document.createElement('div');el.innerHTML=sanitizeRichHtml(raw);return String(el.innerText||el.textContent||'').replace(/\u00a0/g,' ').replace(/\n{3,}/g,'\n\n').trim()}
function richHtmlFor(b,key,fallback=''){const stored=b?.richText?.[key];return stored?sanitizeRichHtml(stored):esc(fallback??'').replace(/\r?\n/g,'<br>')}
function richTextEditor(b,key,label,options={}){const size=richTextSize(b,key),placeholder=options.placeholder||'',compact=options.compact?' compact':'';return `<div class="field rich-text-field"><label>${label}</label><div class="rich-editor-shell"><div class="rich-editor-toolbar" role="toolbar" aria-label="Format ${esc(label)}"><label class="rich-size-control"><span class="sr-only">Text size</span><select aria-label="Text size" onchange="setRichTextSize('${b.id}','${key}',this.value)"><option value="small" ${size==='small'?'selected':''}>Small</option><option value="normal" ${size==='normal'?'selected':''}>Normal</option><option value="large" ${size==='large'?'selected':''}>Large</option></select></label><span class="rich-toolbar-divider"></span><button type="button" class="rich-format-btn" aria-label="Bold" title="Bold" onmousedown="event.preventDefault()" onclick="applyRichTextCommand(event,'${b.id}','${key}','bold')"><b>B</b></button><button type="button" class="rich-format-btn" aria-label="Italic" title="Italic" onmousedown="event.preventDefault()" onclick="applyRichTextCommand(event,'${b.id}','${key}','italic')"><i>I</i></button><button type="button" class="rich-format-btn" aria-label="Bulleted list" title="Bulleted list" onmousedown="event.preventDefault()" onclick="applyRichTextCommand(event,'${b.id}','${key}','insertUnorderedList')">•≡</button></div><div id="rich-${b.id}-${key}" class="rich-editor rich-size-${size}${compact}" contenteditable="true" role="textbox" aria-multiline="true" spellcheck="true" data-placeholder="${esc(placeholder)}" oninput="syncRichText('${b.id}','${key}',this)" onblur="normaliseRichText('${b.id}','${key}',this)">${richHtmlFor(b,key,b?.[key]||'')}</div></div></div>`}
function syncRichText(id,key,editor){const b=currentStudy()?.blocks.find(x=>x.id===id);if(!b||!editor)return;recordStudyHistory(`rich:${id}:${key}`);const html=sanitizeRichHtml(editor.innerHTML);b.richText=b.richText||{};b.richText[key]=html;b[key]=richPlainText(html);currentStudy().updatedAt=Date.now();scheduleSave()}
function normaliseRichText(id,key,editor){if(!editor)return;const clean=sanitizeRichHtml(editor.innerHTML);if(clean!==editor.innerHTML)editor.innerHTML=clean;syncRichText(id,key,editor)}
function applyRichTextCommand(event,id,key,command){event?.preventDefault?.();const editor=document.getElementById(`rich-${id}-${key}`);if(!editor)return;editor.focus();try{document.execCommand(command,false,null)}catch{}syncRichText(id,key,editor)}
function setRichTextSize(id,key,size){const b=currentStudy()?.blocks.find(x=>x.id===id);if(!b)return;const next=['small','normal','large'].includes(size)?size:'normal';recordStudyHistory(`rich-size:${id}:${key}`,false);b.richTextSizes=b.richTextSizes||{};b.richTextSizes[key]=next;const editor=document.getElementById(`rich-${id}-${key}`);if(editor){editor.classList.remove('rich-size-small','rich-size-normal','rich-size-large');editor.classList.add(`rich-size-${next}`)}currentStudy().updatedAt=Date.now();scheduleSave()}
