// Custom mini-modal system. Never fall back to browser alert/confirm/prompt UI.
let activeMiniDialog=null;
function closeMiniDialog(value){
  const active=activeMiniDialog;if(!active)return;
  activeMiniDialog=null;
  active.cleanup?.();
  active.element?.remove();
  active.resolve(value);
}
function miniDialog({title='Eve',message='',confirmLabel='Done',cancelLabel='',tone='default',input=false,multiline=false,value='',placeholder='',readonly=false,inputType='text'}={}){
  if(activeMiniDialog)closeMiniDialog(null);
  return new Promise(resolve=>{
    const previousFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;
    const overlay=document.createElement('div');overlay.className='mini-modal-backdrop';
    const descId=message?'mini-modal-description':'';
    const inputMarkup=input?(multiline?`<textarea class="mini-modal-input" data-mini-input ${readonly?'readonly':''} placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input class="mini-modal-input" data-mini-input type="${esc(inputType)}" ${readonly?'readonly':''} value="${esc(value)}" placeholder="${esc(placeholder)}" autocomplete="${inputType==='password'?'current-password':'off'}">`):'';
    overlay.innerHTML=`<div class="mini-modal ${tone==='danger'?'danger':''}" role="dialog" aria-modal="true" aria-labelledby="mini-modal-title" ${descId?`aria-describedby="${descId}"`:''}><div class="mini-modal-icon" aria-hidden="true">${tone==='danger'?'!':'R'}</div><div class="mini-modal-copy"><h3 id="mini-modal-title">${esc(title)}</h3>${message?`<p id="${descId}">${esc(message)}</p>`:''}</div>${inputMarkup}<div class="mini-modal-actions">${cancelLabel?`<button type="button" class="btn" data-mini-cancel>${esc(cancelLabel)}</button>`:''}<button type="button" class="btn ${tone==='danger'?'danger':'primary'}" data-mini-confirm>${esc(confirmLabel)}</button></div></div>`;
    document.body.appendChild(overlay);document.body.classList.add('modal-open');
    const dialog=overlay.querySelector('.mini-modal'),field=overlay.querySelector('[data-mini-input]');
    const focusables=()=>[...dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),[tabindex]:not([tabindex="-1"])')];
    const onKey=e=>{
      if(e.key==='Escape'){e.preventDefault();closeMiniDialog(cancelLabel?null:(input?null:true));return}
      if(e.key==='Tab'){const items=focusables();if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}return}
      if(e.key==='Enter'&&input&&!multiline){e.preventDefault();closeMiniDialog(field?.value??'')}
      if(e.key==='Enter'&&input&&multiline&&(e.ctrlKey||e.metaKey)){e.preventDefault();closeMiniDialog(field?.value??'')}
    };
    document.addEventListener('keydown',onKey,true);
    const cleanup=()=>{document.removeEventListener('keydown',onKey,true);document.body.classList.remove('modal-open');requestAnimationFrame(()=>previousFocus?.isConnected&&previousFocus.focus?.())};
    activeMiniDialog={element:overlay,resolve,cleanup};
    overlay.querySelector('[data-mini-confirm]')?.addEventListener('click',()=>closeMiniDialog(input?(field?.value??''):true));
    overlay.querySelector('[data-mini-cancel]')?.addEventListener('click',()=>closeMiniDialog(null));
    overlay.addEventListener('click',e=>{if(e.target===overlay&&cancelLabel)closeMiniDialog(null)});
    requestAnimationFrame(()=>{if(field){field.focus();if(readonly||value)field.select?.()}else overlay.querySelector('[data-mini-confirm]')?.focus()});
  });
}
function miniConfirm(title,message,confirmLabel='Confirm'){return miniDialog({title,message,confirmLabel,cancelLabel:'Cancel',tone:'danger'})}
function miniPrompt(title,message,{value='',placeholder='',multiline=true,confirmLabel='Apply',inputType='text'}={}){return miniDialog({title,message,confirmLabel,cancelLabel:'Cancel',input:true,multiline,value,placeholder,inputType})}
function miniNotice(title,message,confirmLabel='Got it'){return miniDialog({title,message,confirmLabel})}
function miniCopy(title,value){return miniDialog({title,message:'Clipboard access was not available. Copy the value below manually.',confirmLabel:'Done',input:true,multiline:false,value,readonly:true})}
function clamp(n,a,b){return Math.min(Math.max(n,a),b)}
function fmtDuration(seconds){
  if(seconds===null||seconds===undefined||seconds==='')return '—';
  const total=Math.round(Number(seconds));
  if(!Number.isFinite(total)||total<0)return '—';
  if(total<60)return `${total}s`;
  if(total<3600){const m=Math.floor(total/60),s=total%60;return s?`${m}m ${s}s`:`${m}m`}
  const h=Math.floor(total/3600),m=Math.floor((total%3600)/60);return m?`${h}h ${m}m`:`${h}h`;
}
function sourceLabel(source='direct'){return ({'customer-list':'Customer list / CRM','external-panel':'External panel','social':'Social / community','direct':'Direct'}[source]||source)}



