function newStudy(){const s=defaultStudy(),g=state.globalSettings||{};s.title='Untitled research study';s.settings.anonymous=g.defaultAnonymous!==false;s.settings.collectEmail=!s.settings.anonymous;s.settings.recontact=false;s.settings.ai=EveCapabilities.supports('ai')&&['off','anonymous','full'].includes(g.defaultAi)?g.defaultAi:'off';s.settings.completionMessage=String(g.defaultCompletionMessage||'Thank you for taking part.');s.settings.storageProvider=['organisation','SharePoint','Google Drive'].includes(g.defaultStorageProvider)?g.defaultStorageProvider:'organisation';s.sendDefaultTarget=Math.max(1,Math.round(Number(g.defaultResponseTarget)||50));const page=s.pages[0];page.title='Page 1';s.blocks=[{id:uid(),pageId:page.id,type:'intro',title:'Welcome',body:'Thanks for taking part in this research.'}];state.studies.unshift(s);state.activeStudyId=s.id;state.activePageId=page.id;state.activeBlockId=s.blocks[0].id;state.sidebarStudyId=s.id;state.sidebarCollapsed=true;state.previewVersion='draft';scheduleSave();navigate(`/study/${s.id}/build`)}
function openStudy(id){const s=state.studies.find(x=>x.id===id);if(!s)return;if(isStudyArchived(s)){navigate('/archive');return}ensureStudyPages(s);state.activeStudyId=id;state.activePageId=s.pages[0]?.id||null;state.activeBlockId=pageBlocks(s,state.activePageId)[0]?.id||null;state.sidebarStudyId=id;state.sidebarCollapsed=true;state.previewVersion='draft';navigate(`/study/${id}/build`)}
function duplicateStudy(id){const original=state.studies.find(s=>s.id===id);if(!original)return;ensureStudyPages(original);const copy=JSON.parse(JSON.stringify(original));copy.id=uid();copy.slug=secureSlug();copy.title=`${copy.title} copy`;copy.status='draft';copy.panelStudyToken='';copy.archivedAt=null;copy.archivePurgeAt=null;copy.archivedFromStatus=null;copy.archivePurgeErrorAt=null;copy.version=1;copy.publishedSnapshot=null;copy.publishedVersions={};copy.relayKey=null;copy.relayVersionKeys={};copy.relayAdminToken=null;copy.relayPublished=false;copy.hasUnpublishedChanges=false;copy.publishedAt=null;copy.sendCampaigns=[];copy.sendSegments=[];copy.createdAt=copy.updatedAt=Date.now();const pageMap={};copy.pages.forEach(p=>{const old=p.id;p.id=uid();pageMap[old]=p.id});copy.blocks.forEach(b=>{b.id=uid();b.pageId=pageMap[b.pageId]||copy.pages[0]?.id});state.studies.unshift(copy);scheduleSave();toast('Study duplicated')}



function studyStagePath(studyId,stage){const safe=['build','settings','send','review'].includes(stage)?stage:'build';return `/study/${studyId}/${safe}`}
function goToStudyStage(studyId,stage){return navigate(studyStagePath(studyId,stage))}
function studyFlow(s,active){const buildReady=!studyBuildIssues(s).length;const settingsReady=!validateStudySettings(s).length;const published=latestPublishedVersion(s)>0,sendReady=published&&s.status==='live';const liveResponses=researchResponses(studyResponses(s.id));const hasResponses=liveResponses.length>0;const step=(key,num,title,sub,done)=>`<button type="button" class="flow-step ${active===key?'active':''} ${done?'complete':''}" data-stage="${key}" onclick="goToStudyStage('${s.id}','${key}')"><span class="flow-num">${done&&active!==key?'✓':num}</span><span><b>${title}</b><small>${sub}</small></span></button>`;const sendSub=sendReady?'Live now':published?'Participant access is off':'Go live & share';return `<div class="study-flow">${step('build',1,'Build',buildReady?'Study ready':'Create the study',buildReady)}<div class="flow-line ${buildReady?'complete':''}"></div>${step('settings',2,'Study settings',settingsReady?'Ready':'Data, privacy & storage',settingsReady)}<div class="flow-line ${settingsReady?'complete':''}"></div>${step('send',3,'Send',sendSub,sendReady)}<div class="flow-line ${hasResponses?'complete':''}"></div>${step('review',4,'Review',hasResponses?`${liveResponses.length} response${liveResponses.length===1?'':'s'}`:'Analyse results',hasResponses)}</div>`}


let draggedBlockId=null;
let draggedPageId=null;
let dragOverviewState=null;
const DRAG_OVERVIEW_ZOOM=.72;
function enterSectionDragOverview(){
 const canvas=document.querySelector('.builder .canvas');
 if(!canvas||document.body.classList.contains('section-drag-overview'))return;
 dragOverviewState={canvas,scrollTop:canvas.scrollTop,scrollLeft:canvas.scrollLeft};
 document.body.classList.add('section-drag-overview');
 requestAnimationFrame(()=>{
  if(!dragOverviewState?.canvas?.isConnected)return;
  dragOverviewState.canvas.scrollTop=Math.max(0,dragOverviewState.scrollTop*DRAG_OVERVIEW_ZOOM);
  dragOverviewState.canvas.scrollLeft=Math.max(0,dragOverviewState.scrollLeft*DRAG_OVERVIEW_ZOOM);
 });
}
function exitSectionDragOverview(){
 const snapshot=dragOverviewState;
 if(!snapshot?.canvas?.isConnected){document.body.classList.remove('section-drag-overview');dragOverviewState=null;return}
 const overviewTop=snapshot.canvas.scrollTop;
 const overviewLeft=snapshot.canvas.scrollLeft;
 document.body.classList.remove('section-drag-overview');
 dragOverviewState=null;
 // Restore normal-scale scroll synchronously so a following render captures the right position.
 void snapshot.canvas.offsetHeight;
 snapshot.canvas.scrollTop=Math.max(0,overviewTop/DRAG_OVERVIEW_ZOOM);
 snapshot.canvas.scrollLeft=Math.max(0,overviewLeft/DRAG_OVERVIEW_ZOOM);
}
function autoScrollStructureDrag(event){
 const canvas=document.querySelector('.builder .canvas');
 if(!canvas)return;
 const r=canvas.getBoundingClientRect();
 const edge=Math.min(110,Math.max(64,r.height*.15));
 let delta=0;
 if(event.clientY<r.top+edge)delta=-Math.ceil((r.top+edge-event.clientY)/edge*34);
 else if(event.clientY>r.bottom-edge)delta=Math.ceil((event.clientY-(r.bottom-edge))/edge*34);
 if(delta)canvas.scrollTop+=delta;
}
function startPageDrag(event,id){draggedPageId=id;draggedBlockId=null;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/page',id);event.dataTransfer.setData('text/plain',`page:${id}`);event.currentTarget.closest('.outline-page,.page-row')?.classList.add('dragging')}
function pageDragOver(event,id){if(!draggedPageId&&!draggedBlockId)return;if(draggedPageId===id)return;event.preventDefault();event.dataTransfer.dropEffect='move';if(draggedBlockId)autoScrollStructureDrag(event);document.querySelectorAll('.outline-page.page-over-before,.outline-page.page-over-after,.outline-page.block-over,.page-row.page-over-before,.page-row.page-over-after,.page-row.block-over').forEach(el=>el.classList.remove('page-over-before','page-over-after','block-over'));if(draggedBlockId){event.currentTarget.classList.add('block-over');return}const r=event.currentTarget.getBoundingClientRect();event.currentTarget.classList.add(event.clientY<r.top+r.height/2?'page-over-before':'page-over-after')}
function dropPageOrBlock(event,targetPageId){event.preventDefault();const s=currentStudy();if(!s)return;if(draggedBlockId){recordStudyHistory('drag-block-page',false);const from=s.blocks.findIndex(b=>b.id===draggedBlockId);if(from>=0){const [moved]=s.blocks.splice(from,1);moved.pageId=targetPageId;const pageIds=new Set(pageBlocks(s,targetPageId).map(b=>b.id));let insert=s.blocks.length;for(let i=s.blocks.length-1;i>=0;i--){if(pageIds.has(s.blocks[i].id)){insert=i+1;break}}s.blocks.splice(insert,0,moved);state.activePageId=targetPageId;state.activeBlockId=moved.id;s.updatedAt=Date.now();scheduleSave()}endStructureDrag();render();return}if(!draggedPageId||draggedPageId===targetPageId)return endStructureDrag();recordStudyHistory('drag-page',false);const from=s.pages.findIndex(p=>p.id===draggedPageId);if(from<0)return endStructureDrag();const r=event.currentTarget.getBoundingClientRect();const after=event.clientY>=r.top+r.height/2;const [moved]=s.pages.splice(from,1);let targetIndex=s.pages.findIndex(p=>p.id===targetPageId);if(after)targetIndex+=1;s.pages.splice(targetIndex,0,moved);s.updatedAt=Date.now();scheduleSave();endStructureDrag();render()}
function startBlockDrag(event,id){
 draggedBlockId=id;draggedPageId=null;
 event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',id);
 const source=event.currentTarget.closest('.block-row,.block-card,.outline-step-wrap');
 source?.classList.add('dragging');
 if(source){
  const ghost=source.cloneNode(true);
  ghost.classList.add('section-drag-ghost');
  ghost.style.width=`${Math.min(source.getBoundingClientRect().width,420)}px`;
  document.body.appendChild(ghost);
  event.dataTransfer.setDragImage(ghost,26,22);
  requestAnimationFrame(()=>ghost.remove());
 }
 requestAnimationFrame(enterSectionDragOverview);
}
function blockDragOver(event,id){if(!draggedBlockId||draggedBlockId===id)return;event.preventDefault();event.stopPropagation();event.dataTransfer.dropEffect='move';autoScrollStructureDrag(event);document.querySelectorAll('.block-row.drag-over-before,.block-row.drag-over-after,.block-card.drag-over-before,.block-card.drag-over-after,.outline-step-wrap.drag-over-before,.outline-step-wrap.drag-over-after').forEach(el=>el.classList.remove('drag-over-before','drag-over-after'));const r=event.currentTarget.getBoundingClientRect();event.currentTarget.classList.add(event.clientY<r.top+r.height/2?'drag-over-before':'drag-over-after')}
function dropBlock(event,targetId){event.preventDefault();event.stopPropagation();const s=currentStudy();const sourceId=draggedBlockId||event.dataTransfer.getData('text/plain');if(!s||!sourceId||sourceId===targetId)return endStructureDrag();const from=s.blocks.findIndex(b=>b.id===sourceId);const target=s.blocks.find(b=>b.id===targetId);if(from<0||!target)return endStructureDrag();recordStudyHistory('drag-block',false);const r=event.currentTarget.getBoundingClientRect();const after=event.clientY>=r.top+r.height/2;const [moved]=s.blocks.splice(from,1);moved.pageId=target.pageId;let targetIndex=s.blocks.findIndex(b=>b.id===targetId);if(targetIndex<0)return endStructureDrag();if(after)targetIndex+=1;s.blocks.splice(targetIndex,0,moved);state.activePageId=moved.pageId;state.activeBlockId=moved.id;s.updatedAt=Date.now();endStructureDrag();scheduleSave();render()}
function endStructureDrag(){draggedBlockId=null;draggedPageId=null;exitSectionDragOverview();document.querySelectorAll('.block-row.dragging,.block-row.drag-over-before,.block-row.drag-over-after,.block-card.dragging,.block-card.drag-over-before,.block-card.drag-over-after,.outline-step-wrap.dragging,.outline-step-wrap.drag-over-before,.outline-step-wrap.drag-over-after,.outline-page.dragging,.outline-page.page-over-before,.outline-page.page-over-after,.outline-page.block-over,.page-row.dragging,.page-row.page-over-before,.page-row.page-over-after,.page-row.block-over').forEach(el=>el.classList.remove('dragging','drag-over-before','drag-over-after','page-over-before','page-over-after','block-over'))}

let draggedSubItem=null;
function startSubItemDrag(event,kind,blockId,index){draggedSubItem={kind,blockId,index:+index};event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/subitem',`${kind}:${blockId}:${index}`);event.dataTransfer.setData('text/plain',`${kind}:${blockId}:${index}`);const row=event.currentTarget.closest('[data-subitem]');row?.classList.add('subitem-dragging');if(row){const ghost=row.cloneNode(true);ghost.classList.add('subitem-drag-ghost');ghost.style.width=`${row.getBoundingClientRect().width}px`;document.body.appendChild(ghost);event.dataTransfer.setDragImage(ghost,24,18);requestAnimationFrame(()=>ghost.remove())}}
function subItemDragOver(event){if(!draggedSubItem)return;event.preventDefault();event.dataTransfer.dropEffect='move';document.querySelectorAll('[data-subitem].subitem-over-before,[data-subitem].subitem-over-after').forEach(el=>el.classList.remove('subitem-over-before','subitem-over-after'));const r=event.currentTarget.getBoundingClientRect();event.currentTarget.classList.add(event.clientY<r.top+r.height/2?'subitem-over-before':'subitem-over-after')}
function dropSubItem(event,kind,blockId,targetIndex){event.preventDefault();let source=draggedSubItem;if(!source){const raw=event.dataTransfer.getData('text/subitem')||event.dataTransfer.getData('text/plain');const [k,b,i]=String(raw||'').split(':');if(k&&b&&Number.isFinite(+i))source={kind:k,blockId:b,index:+i}}if(!source||source.kind!==kind||source.blockId!==blockId)return endSubItemDrag();const b=currentStudy()?.blocks.find(x=>x.id===blockId);const key={option:'options',card:'cards',category:'categories'}[kind];const list=b?.[key];if(!Array.isArray(list))return endSubItemDrag();const from=source.index;let to=+targetIndex;if(from===to)return endSubItemDrag();recordStudyHistory(`reorder-${kind}:${blockId}`,false);const r=event.currentTarget.getBoundingClientRect();const after=event.clientY>=r.top+r.height/2;const [moved]=list.splice(from,1);if(from<to)to-=1;if(after)to+=1;list.splice(Math.max(0,Math.min(to,list.length)),0,moved);if(b.type==='screener'&&b.screenOut&&!b.options.includes(b.screenOut))b.screenOut='';currentStudy().updatedAt=Date.now();scheduleSave();endSubItemDrag();render()}
function moveSubItem(kind,blockId,index,delta){const b=currentStudy()?.blocks.find(x=>x.id===blockId);const key={option:'options',card:'cards',category:'categories'}[kind],list=b?.[key];if(!Array.isArray(list))return;const to=Math.max(0,Math.min(list.length-1,index+delta));if(to===index)return;recordStudyHistory(`reorder-${kind}:${blockId}`,false);const [item]=list.splice(index,1);list.splice(to,0,item);if(b.type==='screener'&&b.screenOut&&!b.options.includes(b.screenOut))b.screenOut='';currentStudy().updatedAt=Date.now();scheduleSave();render()}

function endSubItemDrag(){draggedSubItem=null;document.querySelectorAll('[data-subitem].subitem-dragging,[data-subitem].subitem-over-before,[data-subitem].subitem-over-after').forEach(el=>el.classList.remove('subitem-dragging','subitem-over-before','subitem-over-after'))}

function treeDestinationPaths(text=''){const stack=[],paths=[];for(const n of parseTree(text)){stack[n.depth]=n.label;stack.length=n.depth+1;paths.push(stack.join(' > '))}return paths}
function duplicateValues(list=[]){const seen=new Set(),dupes=new Set();for(const raw of list){const v=String(raw||'').trim().toLowerCase();if(!v)continue;if(seen.has(v))dupes.add(v);seen.add(v)}return [...dupes]}
function consentConfirmations(b,{legacyFallback=true}={}){
 if(!b||b.type!=='consent')return[];
 if(Array.isArray(b.confirmations))return b.confirmations.map((item,i)=>typeof item==='string'?{id:`legacy-${b.id}-${i}`,text:item}:{id:item?.id||`confirmation-${i}`,text:String(item?.text||'')});
 return legacyFallback?[{id:`legacy-${b.id}`,text:'I agree to take part in this research.'}]:[]
}
function addConsentConfirmation(blockId){const b=currentStudy()?.blocks.find(x=>x.id===blockId);if(!b||b.type!=='consent')return;recordStudyHistory(`consent-add:${blockId}`,false);if(!Array.isArray(b.confirmations))b.confirmations=consentConfirmations(b);b.confirmations.push({id:uid(),text:'I confirm that I understand and agree.'});currentStudy().updatedAt=Date.now();scheduleSave();render();setTimeout(()=>document.querySelector(`[data-consent-confirmation="${b.confirmations.at(-1)?.id}"] input`)?.focus(),20)}
function updateConsentConfirmation(blockId,confirmationId,value){const b=currentStudy()?.blocks.find(x=>x.id===blockId);if(!b||!Array.isArray(b.confirmations))return;const item=b.confirmations.find(x=>x.id===confirmationId);if(!item)return;recordStudyHistory(`consent-text:${blockId}:${confirmationId}`);item.text=value;currentStudy().updatedAt=Date.now();scheduleSave()}
function removeConsentConfirmation(blockId,confirmationId){const b=currentStudy()?.blocks.find(x=>x.id===blockId);if(!b||!Array.isArray(b.confirmations))return;recordStudyHistory(`consent-remove:${blockId}`,false);b.confirmations=b.confirmations.filter(x=>x.id!==confirmationId);currentStudy().updatedAt=Date.now();scheduleSave();render();toast('Confirmation removed')}
function moveConsentConfirmation(blockId,confirmationId,delta){const b=currentStudy()?.blocks.find(x=>x.id===blockId);if(!b||!Array.isArray(b.confirmations))return;const i=b.confirmations.findIndex(x=>x.id===confirmationId),j=i+delta;if(i<0||j<0||j>=b.confirmations.length)return;recordStudyHistory(`consent-move:${blockId}`,false);[b.confirmations[i],b.confirmations[j]]=[b.confirmations[j],b.confirmations[i]];currentStudy().updatedAt=Date.now();scheduleSave();render()}


const HIGHLIGHTER_DEFAULT_COLOR='#e3a008';
const HIGHLIGHTER_PALETTE=['#d14343','#e87817','#e3a008','#2f9e62','#168aad','#4263eb','#7950f2','#c2255c'];
function highlighterSafeColor(value,fallback=HIGHLIGHTER_DEFAULT_COLOR){const raw=String(value||'').trim();return /^#[0-9a-f]{6}$/i.test(raw)?raw.toLowerCase():fallback}
function highlighterAlpha(color,alpha='32'){return `${highlighterSafeColor(color)}${alpha}`}
function highlighterMeanings(b){const rows=Array.isArray(b?.highlighterMeanings)?b.highlighterMeanings:[];const clean=rows.map((row,i)=>({id:String(row?.id||`legacy-${i+1}`),label:String(row?.label||'').trim()||`Meaning ${i+1}`,color:highlighterSafeColor(row?.color,HIGHLIGHTER_PALETTE[i%HIGHLIGHTER_PALETTE.length])})).filter(x=>x.id);return clean.length?clean:[{id:'default',label:'Highlight',color:HIGHLIGHTER_DEFAULT_COLOR}]}
function updateHighlighterMeaning(blockId,meaningId,key,value){const b=currentStudy()?.blocks.find(x=>x.id===blockId);if(!b)return;recordStudyHistory(`highlighter-meaning:${blockId}:${meaningId}:${key}`);b.highlighterMeanings=highlighterMeanings(b).map(row=>row.id===meaningId?{...row,[key]:key==='color'?highlighterSafeColor(value,row.color):String(value||'').slice(0,80)}:row);currentStudy().updatedAt=Date.now();scheduleSave();if(key==='color')render()}
function addHighlighterMeaning(blockId){const b=currentStudy()?.blocks.find(x=>x.id===blockId);if(!b)return;recordStudyHistory(`highlighter-meaning-add:${blockId}`,false);const current=highlighterMeanings(b),used=new Set(current.map(x=>x.color));const color=HIGHLIGHTER_PALETTE.find(x=>!used.has(x))||HIGHLIGHTER_PALETTE[current.length%HIGHLIGHTER_PALETTE.length];b.highlighterMeanings=[...current,{id:uid(),label:`Meaning ${current.length+1}`,color}];currentStudy().updatedAt=Date.now();scheduleSave();render()}
function removeHighlighterMeaning(blockId,meaningId){const b=currentStudy()?.blocks.find(x=>x.id===blockId);if(!b)return;const current=highlighterMeanings(b);if(current.length<=1){toast('Keep at least one highlight meaning',2200,'error');return}recordStudyHistory(`highlighter-meaning-remove:${blockId}`,false);b.highlighterMeanings=current.filter(x=>x.id!==meaningId);currentStudy().updatedAt=Date.now();scheduleSave();render()}

function navigationRecordingModes(b){const out=[];if(b?.navigationRecordAudio)out.push('audio');if(b?.navigationRecordVideo)out.push('video');if(b?.navigationRecordScreen)out.push('screen');if(!out.length&&typeof b?.navigationRecordAudio!=='boolean'&&typeof b?.navigationRecordVideo!=='boolean'&&typeof b?.navigationRecordScreen!=='boolean'&&['audio','video','screen'].includes(b?.navigationRecordingMode))out.push(b.navigationRecordingMode);return out}
function navigationRecordingMode(b){return navigationRecordingModes(b)[0]||'none'}
function navigationRecordingLabel(mode){return ({audio:'Audio',video:'Video',screen:'Screen recording'})[mode]||'No recording'}
function navigationRecordingLimitSeconds(b){const taskLimit=b?.timeoutEnabled?Math.max(15,Number(b.timeoutMinutes||0)*60):15*60;return Math.min(15*60,taskLimit||15*60)}
function navigationRecordingPermissionLabel(mode){return mode==='video'?'Camera':mode==='screen'?'Screen/window':'Microphone'}
function navigationRecordingPermissionsLabel(modes){return (modes||[]).map(navigationRecordingPermissionLabel).join(', ')}
function navigationRecordingTempSessions(meta){if(!meta)return[];if(Array.isArray(meta.sessions))return meta.sessions.filter(Boolean);return meta.sessionId?[meta]:[]}
function navigationRecordingValues(answer){const rec=answer?.recording;if(!rec)return[];if(Array.isArray(rec.sessions))return rec.sessions.filter(x=>x?.recordingId);return rec.recordingId?[rec]:[]}
function blockIssues(b){const issues=[];if(!b)return issues;const blank=v=>!String(v||'').trim();if(['intro','consent'].includes(b.type)&&blank(b.body))issues.push('Add participant-facing copy.');if(b.type==='consent'){const confirmations=consentConfirmations(b);if(confirmations.some(x=>blank(x.text)))issues.push('Add wording to each consent confirmation or remove the empty one.');const texts=confirmations.map(x=>String(x.text||'').trim()).filter(Boolean);if(duplicateValues(texts).length)issues.push('Consent confirmations should be unique.')}if(['question','multiChoice','screener','scale','openText','shortText','number','date','matrix','ranking','preference'].includes(b.type)&&blank(b.question))issues.push('Add the question or task text.');if(['question','multiChoice','screener','ranking','preference'].includes(b.type)){const opts=(b.options||[]).map(x=>String(x||'').trim()).filter(Boolean);if(opts.length<2)issues.push(b.type==='ranking'?'Add at least two items to rank.':'Add at least two answer options.');if(duplicateValues(opts).length)issues.push(b.type==='ranking'?'Ranking items should be unique.':'Answer options should be unique.');if(b.type==='screener'&&b.screenOut&&!opts.includes(b.screenOut))issues.push('Choose a valid screen-out answer.')}if(b.type==='shortText'&&Number(b.maxLength||0)<0)issues.push('Character limit cannot be negative.');if(b.type==='number'){const min=String(b.min??'').trim(),max=String(b.max??'').trim();if(min!==''&&!Number.isFinite(Number(min)))issues.push('Minimum must be a number.');if(max!==''&&!Number.isFinite(Number(max)))issues.push('Maximum must be a number.');if(min!==''&&max!==''&&Number(min)>Number(max))issues.push('Minimum cannot be greater than maximum.')}if(b.type==='matrix'){const rows=(b.rows||[]).map(x=>String(x||'').trim()).filter(Boolean);if(rows.length<2)issues.push('Add at least two matrix statements.');if(duplicateValues(rows).length)issues.push('Matrix statements should be unique.')}if(b.type==='cardSort'){const cards=(b.cards||[]).map(x=>String(x||'').trim()).filter(Boolean);if(cards.length<3)issues.push('Add at least three cards.');if(duplicateValues(cards).length)issues.push('Card names should be unique.');if(['closed','hybrid'].includes(b.mode)){const cats=(b.categories||[]).map(x=>String(x||'').trim()).filter(Boolean);if(cats.length<2)issues.push('Add at least two categories.');if(duplicateValues(cats).length)issues.push('Category names should be unique.')}}if(b.type==='treeTest'){if(blank(b.task))issues.push('Add the participant task.');const structural=treeStructureIssues(b.tree||'');issues.push(...structural);const paths=structural.length?[]:treeDestinationPaths(b.tree||'');if(paths.length<2)issues.push('Add a usable tree structure.');if(blank(b.target))issues.push('Choose the correct destination.');else if(paths.length&&!paths.includes(String(b.target).trim()))issues.push('Correct destination does not match a reachable tree path.')}if(b.type==='highlighter'){if(blank(b.instructions))issues.push('Add task instructions.');if(blank(b.imageData))issues.push('Upload an image for participants to highlight.');const meanings=Array.isArray(b.highlighterMeanings)?b.highlighterMeanings:[];if(meanings.some(x=>blank(x?.label)))issues.push('Give every highlight colour a meaning.');const labels=meanings.map(x=>String(x?.label||'').trim()).filter(Boolean);if(duplicateValues(labels).length)issues.push('Highlight meanings should be unique.')}if(b.type==='recording'){if(blank(b.prompt))issues.push('Add a recording prompt.');if(!['audio','video'].includes(b.recordingMode))issues.push('Choose audio or audio and video.');const mins=Number(b.recordingTimeLimitMinutes);if(!Number.isFinite(mins)||mins<0.25||mins>15)issues.push('Set a recording time limit between 15 seconds and 15 minutes.')}if(b.type==='panelSignup'){if(blank(b.panelIntro))issues.push('Add a panel sign-up message.');if(blank(b.panelConsentLabel))issues.push('Add the panel consent checkbox wording.');if(b.panelTermsEnabled&&blank(richPlainText(b.panelTerms||'')))issues.push('Add panel terms and conditions or turn them off.');if(blank(b.panelWelcomeMessage))issues.push('Add the panel welcome email message.')}if(b.type==='navigationTask'){if(blank(b.instructions))issues.push('Add task instructions.');for(const [key,label] of [['startPage','start page'],['successPage','success page']]){const raw=String(b[key]||'').trim();if(blank(raw))issues.push(`Add the ${label} URL.`);else{try{const u=new URL(raw);if(!['http:','https:'].includes(u.protocol))throw new Error()}catch{issues.push(`Use a valid http(s) URL for the ${label}.`)}}}if(b.timeoutEnabled&&(!Number.isFinite(Number(b.timeoutMinutes))||Number(b.timeoutMinutes)<=0))issues.push('Set a timeout greater than 0 minutes.')}return [...new Set(issues)]}
function pageIssues(s,pageId){const blocks=pageBlocks(s,pageId);if(!blocks.length)return [{blockId:null,title:s.pages?.find(p=>p.id===pageId)?.title||'Page',issue:'Add at least one step to this page.'}];return blocks.flatMap(b=>blockIssues(b).map(issue=>({blockId:b.id,title:b.title||label(b.type),issue})))}
function studyBuildIssues(s){if(!s)return[{area:'study',pageId:null,blockId:null,issue:'Study unavailable.'}];ensureStudyPages(s);if(!s.pages.length)return[{area:'study',pageId:null,blockId:null,issue:'Add at least one page.'}];return s.pages.flatMap(p=>pageIssues(s,p.id).map(x=>({...x,area:'build',pageId:p.id,pageTitle:p.title||'Page'})))}
function responseTargetStats(s,count=0){const target=Math.max(1,Number(s?.sendDefaultTarget??s?.settings?.target)||1),responses=Math.max(0,Number(count)||0),percent=Math.min(100,Math.round(responses/target*100));return {target,responses,percent,reached:responses>=target,remaining:Math.max(0,target-responses)}}
function targetProgressMarkup(s,count,{compact=false}={}){const t=responseTargetStats(s,count);return `<div class="target-progress ${t.reached?'reached':''} ${compact?'compact':''}"><div class="target-progress-copy"><span>${t.reached?'Response target reached':'Response target'}</span><b>${t.responses} / ${t.target}</b>${compact?'':`<small>${t.reached?'You have reached the configured response target.':`${t.remaining} response${t.remaining===1?'':'s'} remaining`}</small>`}</div><div class="target-progress-track" role="progressbar" aria-label="Response target" aria-valuemin="0" aria-valuemax="${t.target}" aria-valuenow="${Math.min(t.responses,t.target)}"><span style="width:${t.percent}%"></span></div></div>`}
function blockStatusMarkup(b){const n=blockIssues(b).length;return n?`<span class="builder-status needs" title="${n} item${n===1?'':'s'} need attention">!</span>`:`<span class="builder-status ready" title="Ready">✓</span>`}
function focusBuilderIssue(pageId='',blockId=''){const s=currentStudy();if(!s)return;if(pageId&&s.pages.some(p=>p.id===pageId))state.activePageId=pageId;state.activeBlockId=blockId||null;render();if(blockId)setTimeout(()=>document.querySelector(`[data-block="${blockId}"]`)?.scrollIntoView({behavior:'smooth',block:'center'}),10);else if(pageId)setTimeout(()=>scrollToBuilderPage(pageId),10)}
function jumpToNextIssue(){const s=currentStudy();if(!s)return;const issues=studyBuildIssues(s);if(!issues.length)return toast('Everything is ready');const currentIndex=issues.findIndex(x=>x.blockId===state.activeBlockId||(!x.blockId&&x.pageId===state.activePageId));const next=issues[(currentIndex+1+issues.length)%issues.length];focusBuilderIssue(next.pageId,next.blockId)}
function builderIssuePanel(s){const issues=studyBuildIssues(s);if(!issues.length)return `<section class="outline-quality ready"><div class="outline-quality-head"><span class="status-mark">✓</span><div><b>Study ready</b><small>No Build issues found</small></div></div><button class="text-btn" onclick="state.previewScope='study';state.preview=true;render()">Preview study →</button></section>`;const visible=issues.slice(0,4);return `<section class="outline-quality needs"><div class="outline-quality-head"><span class="status-mark">${issues.length}</span><div><b>${issues.length} thing${issues.length===1?'':'s'} to fix</b><small>Resolve these before going live</small></div></div><div class="outline-quality-list">${visible.map((item,i)=>`<button type="button" onclick="focusBuilderIssue('${esc(item.pageId||'')}','${esc(item.blockId||'')}')"><span>${i+1}</span><div><b>${esc(item.pageTitle||'Study')}</b><small>${esc(item.issue||'Needs attention')}</small></div></button>`).join('')}${issues.length>visible.length?`<button type="button" class="outline-more-issues" onclick="jumpToNextIssue()"><span>+</span><div><b>${issues.length-visible.length} more</b><small>Jump to the next issue</small></div></button>`:''}</div></section>`}
function pathsToTreeText(raw=''){const root={children:new Map()};for(const line of String(raw).split(/\n/).map(x=>x.trim()).filter(Boolean)){const parts=line.split(/\s*>\s*/).map(x=>x.trim()).filter(Boolean);let node=root;for(const part of parts){if(!node.children.has(part))node.children.set(part,{children:new Map()});node=node.children.get(part)}}const out=[];function walk(node,depth){for(const [label,child] of node.children){out.push(`${'  '.repeat(depth)}${label}`);walk(child,depth+1)}}walk(root,0);return out.join('\n')}
async function importTreePaths(id){const raw=await miniPrompt('Import tree paths','Paste one full path per line. Eve will build the hierarchy for you.',{placeholder:'Home > Account > Statements\nHome > Account > Profile',confirmLabel:'Import paths'});if(!raw)return;const tree=pathsToTreeText(raw);if(!tree)return toast('No valid paths found');const b=currentStudy()?.blocks.find(x=>x.id===id);if(!b)return;recordStudyHistory(`tree-import:${id}`,false);b.tree=tree;const paths=treeDestinationPaths(tree);if(b.target&&!paths.includes(b.target))b.target='';scheduleSave();render();toast(`${paths.length} tree destinations created`)}
function filterAddSteps(value){const q=String(value||'').trim().toLowerCase(),options=[...document.querySelectorAll('.add-option[data-search]')];options.forEach(el=>{el.hidden=!!q&&!el.dataset.search.includes(q)});document.querySelectorAll('.add-section').forEach(section=>{const any=[...section.querySelectorAll('.add-option')].some(el=>!el.hidden);section.hidden=!any});const visible=options.filter(el=>!el.hidden).length,count=document.querySelector('[data-add-search-count]'),empty=document.querySelector('[data-add-search-empty]'),clear=document.querySelector('[data-add-search-clear]');if(count)count.textContent=q?`${visible} matching type${visible===1?'':'s'}`:`${options.length} step types`;if(empty)empty.hidden=visible>0;if(clear)clear.hidden=!q}function clearAddStepSearch(){const input=document.getElementById('add-step-search');if(!input)return;input.value='';filterAddSteps('');input.focus()}


function builderPreviewVersionControl(s){const versions=Object.keys(s?.publishedVersions||{}).map(Number).filter(Number.isFinite).sort((a,b)=>b-a);const current=String(state.previewVersion??'draft');return `<label class="builder-version-control"><span>Version</span><select class="select" onchange="setPreviewVersion(this.value)"><option value="draft" ${current==='draft'?'selected':''}>Current draft</option>${versions.map(v=>`<option value="${v}" ${current===String(v)?'selected':''}>Version ${v}</option>`).join('')}</select></label>`}
function setPreviewVersion(value){state.previewVersion=value==='draft'?'draft':Number(value);render()}
function previewStudySource(s){if(state.previewVersion==='draft'||!Number.isFinite(Number(state.previewVersion)))return s;return publishedStudy(s,Number(state.previewVersion))||s}
function builderPageCanvas(s,p,i){const blocks=pageBlocks(s,p.id),issues=pageIssues(s,p.id),active=p.id===state.activePageId;return `<section class="builder-page-section ${active?'active':''}" data-page-canvas="${p.id}"><div class="page-canvas-heading" onclick="activateBuilderPage('${p.id}')"><div><div class="page-index">PAGE ${i+1} OF ${s.pages.length}</div><input class="inline-title page-title-input" aria-label="Page title — editable" value="${esc(p.title||'Untitled page')}" oninput="updatePage('${p.id}','title',this.value)" onfocus="state.activePageId='${p.id}'"/><div class="page-check-line ${issues.length?'needs':'ready'}">${issues.length?`${issues.length} check${issues.length===1?'':'s'} need attention`:`${blocks.length} step${blocks.length===1?'':'s'} · ready to preview`}</div></div><div class="page-heading-actions"><button class="btn subtle" onclick="event.stopPropagation();state.activePageId='${p.id}';state.previewScope='page';state.preview=true;render()">Preview page</button><button class="btn subtle" onclick="event.stopPropagation();duplicatePage('${p.id}')">Duplicate page</button><button class="btn page-delete-button" ${s.pages.length>1?`onclick="event.stopPropagation();removePage('${p.id}')"`:'disabled title="A study needs at least one page"'}>Delete page</button><button class="btn primary-soft" onclick="event.stopPropagation();state.activePageId='${p.id}';state.activeBlockId=pageBlocks(currentStudy(),'${p.id}').at(-1)?.id||null;state.modal='add';render()">+ Add step</button></div></div>${blocks.length?blocks.map(b=>blockEditor(b)).join(''):`<div class="card empty-page" ondragover="emptyPageDragOver(event)" ondragleave="event.currentTarget.classList.remove('block-over')" ondrop="dropBlockOnEmptyPage(event,'${p.id}')"><div class="empty-icon">＋</div><h3>This page is empty</h3><p>Add a question, card sort, tree test or information step.</p><button class="btn primary" onclick="state.activePageId='${p.id}';state.activeBlockId=null;state.modal='add';render()">Add first step</button></div>`}</section>`}
function builder(){const s=currentStudy();if(!s)return home();ensureStudyPages(s);if(!state.activePageId||!s.pages.some(p=>p.id===state.activePageId))state.activePageId=s.pages[0]?.id||null;const studyIssues=studyBuildIssues(s);return shell(`${studyFlow(s,'build')}<div class="builder vertical-pages builder-two-column"><aside class="pane structure outline-rail"><div class="outline-header"><div><div class="pane-title">Study outline</div><div class="pane-hint">Jump to sections or drag them between pages</div></div></div><div class="outline-summary">${s.pages.length} page${s.pages.length===1?'':'s'} · ${s.blocks.length} section${s.blocks.length===1?'':'s'}</div>${builderIssuePanel(s)}<nav class="outline-list" aria-label="Study outline">${s.pages.map((p,i)=>pageStructureMarkup(s,p,i,currentBlock())).join('')}</nav></aside><section class="canvas"><div class="canvas-inner"><div class="study-heading"><div class="eyebrow">BUILD</div><input class="inline-title study-title" aria-label="Study title — editable" value="${esc(s.title)}" oninput="updateStudy('title',this.value)"/><div class="muted">Build the study as one continuous document. Use the outline to jump between pages and sections.</div></div><div class="builder-page-stack">${s.pages.map((p,i)=>builderPageCanvas(s,p,i)).join('')}</div><div class="new-page-canvas"><div><span class="section-label">ADD PAGE</span><b>Add another page to this study</b><small>New pages are added to the end and can be reordered from the outline.</small></div><button class="btn new-page-button" onclick="addPage()">+ New page</button></div></div></section></div>${state.sectionSettingsId?sectionSettingsDrawer(s):''}${state.modal==='add'?addModal():''}${state.preview?previewModal(s):''}`,'Build study',`<span class="save-state" data-save>${state.saveState}</span><button class="icon-btn history-btn" onclick="undoBuilder()" ${canUndoBuilder()?'':'disabled'} title="Undo (Ctrl/⌘ Z)">${eveIcon('undo',18)}</button><button class="icon-btn history-btn" onclick="redoBuilder()" ${canRedoBuilder()?'':'disabled'} title="Redo (Ctrl/⌘ Shift Z)">${eveIcon('redo',18)}</button>${builderPreviewVersionControl(s)}<button class="btn" onclick="state.previewScope='study';state.preview=true;render()">Preview</button><button class="btn primary" onclick="navigate('/study/${s.id}/settings')">Settings →</button>`) }
function movePageBy(id,delta){const s=currentStudy();if(!s)return;const i=s.pages.findIndex(p=>p.id===id),j=i+delta;if(i<0||j<0||j>=s.pages.length)return;recordStudyHistory(`move-page:${id}`,false);[s.pages[i],s.pages[j]]=[s.pages[j],s.pages[i]];state.activePageId=id;s.updatedAt=Date.now();scheduleSave();render();scrollToBuilderPage(id)}
function pageStructureMarkup(s,p,i,activeBlock){const blocks=pageBlocks(s,p.id);const active=p.id===state.activePageId;const issues=pageIssues(s,p.id);return `<section class="outline-page ${active?'active':''}" data-structure-page="${p.id}" ondragover="pageDragOver(event,'${p.id}')" ondragleave="event.currentTarget.classList.remove('page-over-before','page-over-after','block-over')" ondrop="dropPageOrBlock(event,'${p.id}')"><div class="outline-page-head"><span class="outline-page-drag" draggable="true" ondragstart="startPageDrag(event,'${p.id}')" ondragend="endStructureDrag()" title="Drag page to reorder">${eveIcon('grip',14)}</span><button class="outline-page-link" onclick="selectPage('${p.id}')"><span class="outline-page-number">${String(i+1).padStart(2,'0')}</span><span class="outline-page-copy"><b>${esc(p.title||`Page ${i+1}`)}</b><small>${blocks.length} section${blocks.length===1?'':'s'}</small></span>${issues.length?`<span class="outline-issue-dot" title="${issues.length} issue${issues.length===1?'':'s'}">${issues.length}</span>`:''}</button></div><div class="outline-steps">${blocks.length?blocks.map((b,j)=>`<div class="outline-step-wrap ${b.id===activeBlock?.id?'active':''}" ondragover="blockDragOver(event,'${b.id}')" ondragleave="event.currentTarget.classList.remove('drag-over-before','drag-over-after')" ondrop="dropBlock(event,'${b.id}')"><span class="outline-step-drag" draggable="true" ondragstart="startBlockDrag(event,'${b.id}')" ondragend="endStructureDrag()" title="Drag section to reorder or move page" aria-label="Drag ${esc(b.title||label(b.type))}">${eveIcon('grip',14)}</span><button class="outline-step ${b.id===activeBlock?.id?'active':''}" onclick="selectBlock('${b.id}')"><span class="outline-step-index">${j+1}</span><span class="outline-step-copy"><b>${esc(b.title||label(b.type))}</b><small>${label(b.type)}</small></span>${blockIssues(b).length?'<span class="outline-step-issue">!</span>':''}</button></div>`).join(''):`<button class="outline-empty" onclick="selectPage('${p.id}')">Empty page · drop a section here</button>`}</div></section>`}

function label(t){return ({intro:'Information',question:'Single choice',multiChoice:'Multiple choice',scale:'Rating scale',screener:'Screener',openText:'Open text',shortText:'Short text',number:'Number',date:'Date',matrix:'Matrix',ranking:'Ranking task',preference:'Preference test',cardSort:'Card sort',treeTest:'Tree test',navigationTask:'Navigation task',highlighter:'Highlighter task',recording:'Recording',consent:'Consent',panelSignup:'Panel sign-up'}[t]||t)}
function scrollToBuilderPage(id,behavior='smooth'){setTimeout(()=>document.querySelector(`[data-page-canvas="${id}"]`)?.scrollIntoView({behavior,block:'start'}),20)}
function selectPage(id){const s=currentStudy();if(!s||!s.pages.some(p=>p.id===id))return;state.activePageId=id;const current=currentBlock();if(!current||current.pageId!==id)state.activeBlockId=pageBlocks(s,id)[0]?.id||null;render();scrollToBuilderPage(id)}
function activateBuilderPage(id){const s=currentStudy();if(!s||!s.pages.some(p=>p.id===id)||state.activePageId===id)return;state.activePageId=id;syncBuilderPageActiveState(id)}
function syncBuilderPageActiveState(id){document.querySelectorAll('.builder-page-section').forEach(el=>el.classList.toggle('active',el.dataset.pageCanvas===id));document.querySelectorAll('.outline-page').forEach(el=>el.classList.toggle('active',el.dataset.structurePage===id))}
function bindBuilderVerticalPages(){const canvas=document.querySelector('.canvas');if(!canvas||canvas.dataset.verticalPagesBound)return;canvas.dataset.verticalPagesBound='true';let ticking=false;const update=()=>{ticking=false;const sections=[...canvas.querySelectorAll('.builder-page-section')];if(!sections.length)return;const top=canvas.getBoundingClientRect().top+110;let best=sections[0],distance=Infinity;for(const section of sections){const r=section.getBoundingClientRect();const d=r.top<=top?Math.abs(top-r.top):Math.abs(r.top-top)+120;if(d<distance){distance=d;best=section}}const id=best?.dataset.pageCanvas;if(id&&id!==state.activePageId){state.activePageId=id;syncBuilderPageActiveState(id)}};canvas.addEventListener('scroll',()=>{if(ticking)return;ticking=true;requestAnimationFrame(update)},{passive:true});update()}
function emptyPageDragOver(event){if(!draggedBlockId)return;event.preventDefault();event.dataTransfer.dropEffect='move';autoScrollStructureDrag(event);event.currentTarget.classList.add('block-over')}
function dropBlockOnEmptyPage(event,pageId){event.preventDefault();event.stopPropagation();const s=currentStudy(),sourceId=draggedBlockId||event.dataTransfer.getData('text/plain');if(!s||!sourceId)return endStructureDrag();const from=s.blocks.findIndex(b=>b.id===sourceId);if(from<0)return endStructureDrag();recordStudyHistory('drag-block-empty-page',false);const [moved]=s.blocks.splice(from,1);moved.pageId=pageId;let insert=s.blocks.length;for(let i=s.blocks.length-1;i>=0;i--){if(s.blocks[i].pageId===pageId){insert=i+1;break}}s.blocks.splice(insert,0,moved);state.activePageId=pageId;state.activeBlockId=moved.id;s.updatedAt=Date.now();scheduleSave();endStructureDrag();render();setTimeout(()=>document.querySelector(`[data-block="${moved.id}"]`)?.scrollIntoView({behavior:'smooth',block:'center'}),20)}
function togglePageCollapse(id,event){event?.stopPropagation?.();state.collapsedPages=state.collapsedPages||{};state.collapsedPages[id]=!state.collapsedPages[id];render()}
function moveBlockToPage(blockId,pageId){const s=currentStudy();const from=s?.blocks.findIndex(x=>x.id===blockId);const b=from>=0?s.blocks[from]:null;if(!s||!b||!s.pages.some(p=>p.id===pageId)||b.pageId===pageId)return;recordStudyHistory(`move:${blockId}`,false);const [moved]=s.blocks.splice(from,1);moved.pageId=pageId;const targetIds=new Set(pageBlocks(s,pageId).map(x=>x.id));let insert=s.blocks.length;for(let i=s.blocks.length-1;i>=0;i--){if(targetIds.has(s.blocks[i].id)){insert=i+1;break}}s.blocks.splice(insert,0,moved);state.activePageId=pageId;state.activeBlockId=blockId;s.updatedAt=Date.now();scheduleSave();render();setTimeout(()=>document.querySelector(`[data-block="${blockId}"]`)?.scrollIntoView({behavior:'smooth',block:'center'}),10);toast('Section moved')}
function selectBlock(id){const s=currentStudy();const b=s?.blocks.find(x=>x.id===id);if(!b)return;state.activePageId=b.pageId;state.activeBlockId=id;render();setTimeout(()=>document.querySelector(`[data-block="${id}"]`)?.scrollIntoView({behavior:'smooth',block:'center'}),10)}
function updatePage(id,k,v){const s=currentStudy();const page=s?.pages.find(p=>p.id===id);if(!page)return;recordStudyHistory(`page:${id}:${k}`);page[k]=v;s.updatedAt=Date.now();scheduleSave()}
function updateStudy(k,v){const s=currentStudy();recordStudyHistory(`study:${k}`);s[k]=v;s.updatedAt=Date.now();scheduleSave()}
function updateBlock(id,k,v){const b=currentStudy().blocks.find(x=>x.id===id);if(!b)return;recordStudyHistory(`block:${id}:${k}`);b[k]=v;currentStudy().updatedAt=Date.now();scheduleSave()}
function updateScaleBuilderPreview(id){const b=currentStudy()?.blocks.find(x=>x.id===id),card=document.querySelector(`[data-block="${CSS.escape(id)}"]`);if(!b||!card)return;const low=card.querySelector('[data-scale-preview-low]'),high=card.querySelector('[data-scale-preview-high]');if(low)low.textContent=b.lowLabel||'Not at all';if(high)high.textContent=b.highLabel||'Extremely'}
function updateOption(id,i,v){const b=currentStudy().blocks.find(x=>x.id===id);recordStudyHistory(`option:${id}:${i}`);b.options[i]=v;scheduleSave()}
function updateBlockLines(id,key,raw){const b=currentStudy()?.blocks.find(x=>x.id===id);if(!b)return;recordStudyHistory(`block-lines:${id}:${key}`);b[key]=String(raw||'').split(/\n/).map(x=>x.trim()).filter(Boolean);currentStudy().updatedAt=Date.now();scheduleSave()}
function closeOtherBlockMenus(current){
 document.querySelectorAll('.block-overflow-menu[open]').forEach(menu=>{if(menu!==current)menu.open=false})
}
function blockOverflowMenuMarkup(b){
 const id=String(b?.id||'');
 return `<details class="block-overflow-menu" ontoggle="if(this.open)closeOtherBlockMenus(this)"><summary class="icon-btn block-overflow-trigger" aria-label="More actions for ${esc(b?.title||label(b?.type))}" title="More actions">•••</summary><div class="block-overflow-popover" role="menu"><button type="button" role="menuitem" onclick="this.closest('details').open=false;openSectionSettings('${id}')"><span class="block-menu-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 8.4a3.6 3.6 0 1 0 0 7.2 3.6 3.6 0 0 0 0-7.2Zm8.1 3.6c0-.5-.04-.98-.12-1.45l2.02-1.57-2-3.46-2.48 1a8.2 8.2 0 0 0-2.5-1.45L14.64 2h-4l-.38 3.07a8.2 8.2 0 0 0-2.5 1.45l-2.48-1-2 3.46 2.02 1.57A8.8 8.8 0 0 0 5.18 12c0 .5.04.98.12 1.45l-2.02 1.57 2 3.46 2.48-1a8.2 8.2 0 0 0 2.5 1.45l.38 3.07h4l.38-3.07a8.2 8.2 0 0 0 2.5-1.45l2.48 1 2-3.46-2.02-1.57c.08-.47.12-.95.12-1.45Z"/></svg></span><span><b>Settings</b><small>Required, page and checks</small></span></button><button type="button" role="menuitem" onclick="this.closest('details').open=false;duplicateBlock('${id}')"><span class="block-menu-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8 8h11v11H8V8Zm-3 8H3V3h13v2H5v11Z"/></svg></span><span><b>Duplicate</b><small>Create a copy after this block</small></span></button><div class="block-menu-divider"></div><button type="button" role="menuitem" class="block-menu-delete" onclick="this.closest('details').open=false;removeBlock('${id}')"><span class="block-menu-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8 3h8l1 2h4v2H3V5h4l1-2Zm1 6v9h2V9H9Zm4 0v9h2V9h-2ZM6 9h2v10h8V9h2v12H6V9Z"/></svg></span><span><b>Delete</b><small>Remove this block</small></span></button></div></details>`
}
function blockEditor(b){let inner='';const issues=blockIssues(b);const study=currentStudy();const siblings=study?pageBlocks(study,b.pageId):[];const position=siblings.findIndex(x=>x.id===b.id);const canMoveUp=position>0;const canMoveDown=position>=0&&position<siblings.length-1;const blockFamily=['cardSort','treeTest','navigationTask','highlighter','recording','ranking','preference'].includes(b.type)?'task':['intro','consent','screener','panelSignup'].includes(b.type)?'study':'question';const consentCount=b.type==='consent'?consentConfirmations(b).length:0;const requirementChip=b.type==='intro'?'':b.type==='consent'?`<span class="block-required-chip ${consentCount?'required':'optional'}">${consentCount?`${consentCount} required confirmation${consentCount===1?'':'s'}`:'No confirmations'}</span>`:b.type==='panelSignup'?`<span class="block-required-chip optional">Optional opt-in</span>`:`<span class="block-required-chip ${b.required?'required':'optional'}">${b.required?'Required':'Optional'}</span>`;
 if(b.type==='intro')inner=richTextEditor(b,'body','Participant message',{placeholder:'Add participant-facing information…'});
 if(b.type==='consent'){const confirmations=consentConfirmations(b);inner=`${richTextEditor(b,'body','Participant message',{placeholder:'Explain what participants are consenting to…'})}<section class="consent-builder-panel"><div class="consent-builder-head"><div><div class="section-label">REQUIRED CONFIRMATIONS</div><h4>Checkboxes participants must confirm</h4><p>Add only the confirmations you need. Every checkbox listed here is required before the participant can continue.</p></div><span class="consent-count-badge">${confirmations.length}</span></div><div class="consent-confirmation-builder-list">${confirmations.length?confirmations.map((item,i)=>`<div class="consent-confirmation-builder-row" data-consent-confirmation="${item.id}"><span class="consent-checkbox-preview" aria-hidden="true">✓</span><div class="consent-confirmation-copy"><label for="consent-${b.id}-${item.id}">Confirmation ${i+1}</label><input id="consent-${b.id}-${item.id}" class="input" value="${esc(item.text)}" placeholder="e.g. I agree to take part in this research." oninput="updateConsentConfirmation('${b.id}','${item.id}',this.value)"/></div><span class="mini-reorder-controls"><button type="button" class="mini-reorder-btn" onclick="moveConsentConfirmation('${b.id}','${item.id}',-1)" aria-label="Move confirmation up" ${i===0?'disabled':''}>↑</button><button type="button" class="mini-reorder-btn" onclick="moveConsentConfirmation('${b.id}','${item.id}',1)" aria-label="Move confirmation down" ${i===confirmations.length-1?'disabled':''}>↓</button></span><button type="button" class="icon-btn consent-remove-confirmation" onclick="removeConsentConfirmation('${b.id}','${item.id}')" aria-label="Remove confirmation" title="Remove confirmation">×</button></div>`).join(''):`<div class="consent-confirmations-empty"><span>☐</span><div><b>No required confirmations</b><small>This block currently shows information only. Add a confirmation when explicit agreement is needed.</small></div></div>`}</div><button type="button" class="btn subtle consent-add-confirmation" onclick="addConsentConfirmation('${b.id}')">+ Add confirmation checkbox</button></section>`}
 if(b.type==='panelSignup')inner=`${richTextEditor(b,'panelIntro','Participant message',{placeholder:'Explain why participants might want to join the panel…'})}<section class="panel-signup-builder"><div class="panel-signup-builder-head"><div><div class="section-label">PANEL CONSENT</div><h4>Panel sign-up</h4><p>Participants can complete the study without joining. If they opt in, Eve adds them only after the study response has been safely submitted.</p></div><span class="pill">Optional</span></div><div class="field"><label>Consent checkbox</label><input class="input" value="${esc(b.panelConsentLabel||'')}" oninput="updateBlock('${b.id}','panelConsentLabel',this.value)" placeholder="I agree to join the research participant panel."></div><div class="toggle settings-toggle"><span><b>Add terms and conditions</b><small>Show panel-specific terms immediately above the opt-in checkbox.</small></span><button type="button" class="switch ${b.panelTermsEnabled?'on':''}" role="switch" aria-checked="${b.panelTermsEnabled?'true':'false'}" onclick="updateBlock('${b.id}','panelTermsEnabled',!currentStudy().blocks.find(x=>x.id==='${b.id}').panelTermsEnabled);render()"></button></div>${b.panelTermsEnabled?richTextEditor(b,'panelTerms','Panel terms and conditions',{placeholder:'Explain how panel membership and future contact will work…'}):''}<div class="panel-email-builder"><div class="section-label">WELCOME EMAIL</div><div class="field"><label>Subject override <span class="optional-label">Optional</span></label><input class="input" value="${esc(b.panelWelcomeSubject||'')}" oninput="updateBlock('${b.id}','panelWelcomeSubject',this.value)" placeholder="Use Global Settings default"></div><div class="field"><label>Email message override <span class="optional-label">Optional</span></label><textarea class="textarea" oninput="updateBlock('${b.id}','panelWelcomeMessage',this.value)" placeholder="Leave blank to use the Global Settings panel welcome email.">${esc(b.panelWelcomeMessage||'')}</textarea></div><div class="builder-type-note">Blank fields use the global Panel welcome template. Eve automatically adds a secure <b>Remove me from the research panel</b> link.</div></div></section>`;
 if(['question','multiChoice','screener','preference','ranking'].includes(b.type)){const optionLabel=b.type==='ranking'?'Items to rank':b.type==='preference'?'Choices':'Answer options';inner=`${richTextEditor(b,'question',b.type==='ranking'?'Task':b.type==='preference'?'Preference question':'Question',{compact:true,placeholder:'Enter participant-facing text…'})}<div class="field"><label>${optionLabel}</label>${(b.options||[]).map((o,i)=>`<div class="list-item sortable-subitem" data-subitem="option-${b.id}-${i}" ondragover="subItemDragOver(event)" ondragleave="event.currentTarget.classList.remove('subitem-over-before','subitem-over-after')" ondrop="dropSubItem(event,'option','${b.id}',${i})"><span class="drag" draggable="true" ondragstart="startSubItemDrag(event,'option','${b.id}',${i})" ondragend="endSubItemDrag()" title="Drag to reorder">⋮⋮</span><span class="mini-reorder-controls"><button type="button" class="mini-reorder-btn" onclick="moveSubItem('option','${b.id}',${i},-1)" aria-label="Move item up" ${i===0?'disabled':''}>↑</button><button type="button" class="mini-reorder-btn" onclick="moveSubItem('option','${b.id}',${i},1)" aria-label="Move item down" ${i===(b.options||[]).length-1?'disabled':''}>↓</button></span><input class="input" value="${esc(o)}" oninput="updateOption('${b.id}',${i},this.value)"/><button class="icon-btn" onclick="removeOption('${b.id}',${i})">×</button></div>`).join('')}<div class="toolbar"><button class="btn subtle" onclick="addOption('${b.id}')">+ Add ${b.type==='ranking'?'item':'option'}</button><button class="btn subtle" onclick="bulkOptions('${b.id}')">Bulk paste</button></div>${b.type==='screener'?`<div class="field" style="margin-top:14px"><label>Screen out when participant selects</label><select class="select" onchange="updateBlock('${b.id}','screenOut',this.value);render()"><option value="">No automatic screen-out</option>${(b.options||[]).map(o=>`<option value="${esc(o)}" ${b.screenOut===o?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`:''}${b.type==='ranking'?'<div class="builder-type-note">Participants drag these into order, then confirm their ranking.</div>':''}${b.type==='preference'?'<div class="builder-type-note">Presented as larger comparison cards rather than a standard radio list.</div>':''}</div>`}
 if(b.type==='shortText')inner=`${richTextEditor(b,'question','Question',{compact:true,placeholder:'Enter your question…'})}<div class="cards-grid"><div class="field"><label>Placeholder</label><input class="input" value="${esc(b.placeholder||'')}" oninput="updateBlock('${b.id}','placeholder',this.value)"/></div><div class="field"><label>Character limit</label><input class="input" type="number" min="0" max="1000" value="${Number(b.maxLength)||0}" oninput="updateBlock('${b.id}','maxLength',+this.value)"/><small>0 = no limit</small></div></div><div class="response-placeholder short">Participant one-line response…</div>`;
 if(b.type==='number')inner=`${richTextEditor(b,'question','Question',{compact:true,placeholder:'Enter your question…'})}<div class="cards-grid"><div class="field"><label>Minimum <small>optional</small></label><input class="input" type="number" value="${esc(b.min??'')}" oninput="updateBlock('${b.id}','min',this.value)"/></div><div class="field"><label>Maximum <small>optional</small></label><input class="input" type="number" value="${esc(b.max??'')}" oninput="updateBlock('${b.id}','max',this.value)"/></div></div><div class="field"><label>Unit or suffix <small>optional</small></label><input class="input" placeholder="e.g. years, £, times" value="${esc(b.unit||'')}" oninput="updateBlock('${b.id}','unit',this.value)"/></div>`;
 if(b.type==='date')inner=`${richTextEditor(b,'question','Question',{compact:true,placeholder:'Enter your question…'})}<div class="response-placeholder short">Participant date picker</div>`;
 if(b.type==='matrix')inner=`${richTextEditor(b,'question','Question',{compact:true,placeholder:'Enter your question…'})}<div class="field"><label>Statements <small>one per line</small></label><textarea class="textarea matrix-row-editor" oninput="updateBlockLines('${b.id}','rows',this.value)">${esc((b.rows||[]).join('\n'))}</textarea></div><div class="cards-grid"><div class="field"><label>Low label</label><input class="input" value="${esc(b.lowLabel||'Strongly disagree')}" oninput="updateBlock('${b.id}','lowLabel',this.value)"/></div><div class="field"><label>High label</label><input class="input" value="${esc(b.highLabel||'Strongly agree')}" oninput="updateBlock('${b.id}','highLabel',this.value)"/></div></div><div class="field"><label>Scale points</label><select class="select" onchange="updateBlock('${b.id}','points',+this.value);render()">${[3,5,7].map(n=>`<option value="${n}" ${Number(b.points||5)===n?'selected':''}>${n} points</option>`).join('')}</select></div>`;
 if(b.type==='scale')inner=`${richTextEditor(b,'question','Question',{compact:true,placeholder:'Enter your question…'})}<div class="scale-builder-preview" aria-hidden="true"><div class="scale-builder-points">${Array.from({length:b.points||5},(_,i)=>`<span>${i+1}</span>`).join('')}</div><div class="scale-labels"><span data-scale-preview-low>${esc(b.lowLabel||'Not at all')}</span><span data-scale-preview-high>${esc(b.highLabel||'Extremely')}</span></div></div><div class="cards-grid"><div class="field"><label>Low label</label><input class="input" value="${esc(b.lowLabel||'Not at all')}" oninput="updateBlock('${b.id}','lowLabel',this.value);updateScaleBuilderPreview('${b.id}')"/></div><div class="field"><label>High label</label><input class="input" value="${esc(b.highLabel||'Extremely')}" oninput="updateBlock('${b.id}','highLabel',this.value);updateScaleBuilderPreview('${b.id}')"/></div></div><div class="field"><label>Scale points</label><select class="select" onchange="updateBlock('${b.id}','points',+this.value);render()">${[5,7,10].map(n=>`<option value="${n}" ${b.points===n?'selected':''}>${n} points</option>`).join('')}</select></div>`;
 if(b.type==='openText')inner=`${richTextEditor(b,'question','Question',{compact:true,placeholder:'Enter your question…'})}<div class="response-placeholder">Participant long-text response…</div>`;
 if(b.type==='highlighter'){const meanings=highlighterMeanings(b);inner=`${richTextEditor(b,'instructions','Instructions',{placeholder:'Tell participants what you want them to highlight…'})}<div class="field"><label>Image</label>${b.imageData?`<div class="highlighter-builder-image"><img src="${esc(b.imageData)}" alt="${esc(b.imageAlt||'Highlighter task image preview')}"><div class="highlighter-builder-image-actions"><span>${esc(b.imageName||'Uploaded image')}</span><button class="btn subtle" type="button" onclick="document.getElementById('highlighter-upload-${b.id}').click()">Replace</button><button class="btn danger-outline" type="button" onclick="removeHighlighterImage('${b.id}')">Remove</button></div></div>`:`<button type="button" class="highlighter-upload-empty" onclick="document.getElementById('highlighter-upload-${b.id}').click()"><span>＋</span><b>Upload image</b><small>PNG, JPG or WebP · Eve optimises large images locally</small></button>`}<input id="highlighter-upload-${b.id}" class="sr-only" type="file" accept="image/png,image/jpeg,image/webp" onchange="loadHighlighterImage(event,'${b.id}')"></div><div class="field"><label>Image description <span class="muted">(accessibility)</span></label><input class="input" value="${esc(b.imageAlt||'')}" placeholder="Describe the image without revealing what to highlight" oninput="updateBlock('${b.id}','imageAlt',this.value)"/><small class="muted">Used by assistive technology. Keep it neutral so it does not bias the task.</small></div><section class="highlighter-meaning-builder"><div class="highlighter-meaning-builder-head"><div><div class="section-label">HIGHLIGHT MEANINGS</div><h4>What should each colour mean?</h4><p>Participants choose one of these meanings before drawing. Keep the labels short and clear.</p></div><button type="button" class="btn subtle" onclick="addHighlighterMeaning('${b.id}')">+ Add meaning</button></div><div class="highlighter-meaning-list">${meanings.map((m,i)=>`<div class="highlighter-meaning-row"><label class="highlighter-colour-input" title="Choose colour"><input type="color" value="${esc(m.color)}" aria-label="Colour for ${esc(m.label)}" oninput="updateHighlighterMeaning('${b.id}','${m.id}','color',this.value)"><span style="background:${m.color}"></span></label><div class="field compact-field"><label>Meaning ${i+1}</label><input class="input" value="${esc(m.label)}" maxlength="80" placeholder="e.g. Good, Bad, Confusing" oninput="updateHighlighterMeaning('${b.id}','${m.id}','label',this.value)"></div><div class="highlighter-palette" aria-label="Quick colours">${HIGHLIGHTER_PALETTE.slice(0,6).map(c=>`<button type="button" class="${c===m.color?'active':''}" style="--swatch:${c}" aria-label="Use colour ${c}" title="${c}" onclick="updateHighlighterMeaning('${b.id}','${m.id}','color','${c}')"></button>`).join('')}</div><button type="button" class="icon-btn" onclick="removeHighlighterMeaning('${b.id}','${m.id}')" aria-label="Remove ${esc(m.label)}" title="Remove meaning" ${meanings.length<=1?'disabled':''}>×</button></div>`).join('')}</div></section><div class="builder-type-note">Desktop participants drag across the image. On touch devices Eve uses an explicit draw mode so people can still scroll and pinch-zoom without accidentally creating highlights.</div>`}
 if(b.type==='recording'){if(!EveCapabilities.supports('recording'))inner=`${EveCapabilities.inlineNotice('recording')}<div class="builder-type-note">Remove this Recording block or run the study from a deployment that supports browser recording.</div>`;else{const mins=Math.max(.25,Math.min(15,Number(b.recordingTimeLimitMinutes)||2));inner=`${richTextEditor(b,'prompt','Text prompt',{placeholder:'What should the participant talk about?'})}<div class="recording-builder-grid"><div class="field"><label>Recording type</label><div class="segmented recording-mode-picker"><button type="button" class="${b.recordingMode!=='video'?'active':''}" onclick="updateBlock('${b.id}','recordingMode','audio');render()">Audio</button><button type="button" class="${b.recordingMode==='video'?'active':''}" onclick="updateBlock('${b.id}','recordingMode','video');render()">Audio and video</button></div><small class="muted">${b.recordingMode==='video'?'Participant will be asked for camera and microphone permission.':'Participant will be asked for microphone permission.'}</small></div><div class="field compact-field"><label>Time limit</label><div class="recording-time-limit"><input class="input" type="number" min="0.25" max="15" step="0.25" value="${mins}" oninput="updateBlock('${b.id}','recordingTimeLimitMinutes',+this.value)"><span>minutes</span></div><small class="muted">15 seconds to 15 minutes.</small></div></div><div class="recording-builder-preview"><span class="recording-preview-icon">${b.recordingMode==='video'?'◉':'◍'}</span><div><b>${b.recordingMode==='video'?'Audio and video recording':'Audio recording'}</b><small>Participants can preview and re-record before submitting.</small></div><span>${fmtDuration(Math.round(mins*60))} max</span></div><div class="builder-type-note">Recording starts only after the participant explicitly chooses Start recording and grants browser permission. Media is encrypted before it is stored by Eve's relay.</div>`}}
 if(b.type==='cardSort')inner=`<div class="toolbar editor-toolbar"><div class="segmented"><button class="${b.mode==='open'?'active':''}" onclick="updateBlock('${b.id}','mode','open');render()">Open</button><button class="${b.mode==='closed'?'active':''}" onclick="updateBlock('${b.id}','mode','closed');render()">Closed</button><button class="${b.mode==='hybrid'?'active':''}" onclick="updateBlock('${b.id}','mode','hybrid');render()">Hybrid</button></div><button class="btn" onclick="bulkCards('${b.id}')">Bulk paste</button></div><div class="cards-grid editor-grid"><div><div class="section-label">CARDS · ${(b.cards||[]).length}</div>${(b.cards||[]).map((c,i)=>`<div class="mini-card editable sortable-subitem" data-subitem="card-${b.id}-${i}" ondragover="subItemDragOver(event)" ondragleave="event.currentTarget.classList.remove('subitem-over-before','subitem-over-after')" ondrop="dropSubItem(event,'card','${b.id}',${i})"><span class="drag mini-drag" draggable="true" ondragstart="startSubItemDrag(event,'card','${b.id}',${i})" ondragend="endSubItemDrag()" title="Drag to reorder">⋮⋮</span><span class="mini-reorder-controls"><button type="button" class="mini-reorder-btn" onclick="moveSubItem('card','${b.id}',${i},-1)" aria-label="Move card up" ${i===0?'disabled':''}>↑</button><button type="button" class="mini-reorder-btn" onclick="moveSubItem('card','${b.id}',${i},1)" aria-label="Move card down" ${i===(b.cards||[]).length-1?'disabled':''}>↓</button></span><input value="${esc(c)}" oninput="updateCard('${b.id}',${i},this.value)"/><button onclick="removeCard('${b.id}',${i})">×</button></div>`).join('')}<button class="btn subtle full" onclick="addCard('${b.id}')">+ Add card</button></div><div><div class="section-label">CATEGORIES · ${(b.categories||[]).length}</div>${(b.categories||[]).map((c,i)=>`<div class="mini-card editable sortable-subitem" data-subitem="category-${b.id}-${i}" ondragover="subItemDragOver(event)" ondragleave="event.currentTarget.classList.remove('subitem-over-before','subitem-over-after')" ondrop="dropSubItem(event,'category','${b.id}',${i})"><span class="drag mini-drag" draggable="true" ondragstart="startSubItemDrag(event,'category','${b.id}',${i})" ondragend="endSubItemDrag()" title="Drag to reorder">⋮⋮</span><span class="mini-reorder-controls"><button type="button" class="mini-reorder-btn" onclick="moveSubItem('category','${b.id}',${i},-1)" aria-label="Move category up" ${i===0?'disabled':''}>↑</button><button type="button" class="mini-reorder-btn" onclick="moveSubItem('category','${b.id}',${i},1)" aria-label="Move category down" ${i===(b.categories||[]).length-1?'disabled':''}>↓</button></span><input value="${esc(c)}" oninput="updateCategory('${b.id}',${i},this.value)"/><button onclick="removeCategory('${b.id}',${i})">×</button></div>`).join('')}${b.mode==='open'?'<div class="empty compact-empty">Participants create their own categories.</div>':`<button class="btn subtle full" onclick="addCategory('${b.id}')">+ Add category</button>`}</div></div>`;
 if(b.type==='treeTest')inner=`${richTextEditor(b,'task','Participant task',{compact:true,placeholder:'Describe what the participant should find…'})}<div class="tree-editor"><div class="tree-editor-head"><div><label>Tree structure</label><div class="muted small">Indent with two spaces. Each line becomes a navigable node.</div></div><button class="btn subtle" onclick="importTreePaths('${b.id}')">Import paths</button></div><textarea class="tree-line" spellcheck="false" oninput="updateBlock('${b.id}','tree',this.value)">${esc(b.tree||'')}</textarea><div class="tree-preview"><div class="section-label">LIVE STRUCTURE PREVIEW</div>${treeVisualPreview(b.tree||'')}</div></div><div class="field"><label>Correct destination</label><input class="input" list="tree-paths-${b.id}" value="${esc(b.target||'')}" oninput="updateBlock('${b.id}','target',this.value)"/><datalist id="tree-paths-${b.id}">${treeDestinationPaths(b.tree||'').map(path=>`<option value="${esc(path)}"></option>`).join('')}</datalist><div class="muted small">Choose an existing destination path from the tree.</div></div>`;
 if(b.type==='navigationTask'){const navModes=navigationRecordingModes(b),navRecLimit=navigationRecordingLimitSeconds(b),navCapture=EveCapabilities.supports('navigationCapture');inner=`${richTextEditor(b,'instructions','Instructions',{placeholder:'Explain what the participant should do…'})}<div class="field"><label>Start page</label><input class="input" type="url" placeholder="https://example.com/start" value="${esc(b.startPage||'')}" oninput="updateBlock('${b.id}','startPage',this.value)"/><div class="muted small">The page participants open when the task begins.</div></div><div class="field"><label>Success page</label><input class="input" type="url" placeholder="https://example.com/success" value="${esc(b.successPage||'')}" oninput="updateBlock('${b.id}','successPage',this.value)"/><div class="muted small">Stored as the expected destination for future instrumented verification.</div></div><div class="navigation-timeout-grid"><div class="toggle"><span>Timeout</span><button type="button" class="switch ${b.timeoutEnabled?'on':''}" role="switch" aria-checked="${b.timeoutEnabled?'true':'false'}" onclick="updateBlock('${b.id}','timeoutEnabled',!currentStudy().blocks.find(x=>x.id==='${b.id}').timeoutEnabled);render()"></button></div>${b.timeoutEnabled?`<div class="field compact-field"><label>Minutes</label><input class="input" type="number" min="1" max="120" value="${Number(b.timeoutMinutes)||5}" oninput="updateBlock('${b.id}','timeoutMinutes',+this.value)"/></div>`:''}</div>${navCapture?`<section class="navigation-recording-builder"><div class="navigation-recording-builder-head"><div><div class="section-label">TASK RECORDING</div><h4>Choose what Eve records during the task</h4><p>Each option is independent. Enable one or combine Audio, Video and Screen recording.</p></div><em class="navigation-recording-limit">${fmtDuration(navRecLimit)} max</em></div><div class="navigation-recording-toggle-list"><div class="navigation-recording-toggle-row"><span class="navigation-recording-kind-icon">◍</span><div><b>Audio</b><small>Participant microphone</small></div><button type="button" class="switch ${b.navigationRecordAudio?'on':''}" role="switch" aria-checked="${b.navigationRecordAudio?'true':'false'}" aria-label="Record audio" onclick="updateBlock('${b.id}','navigationRecordAudio',!currentStudy().blocks.find(x=>x.id==='${b.id}').navigationRecordAudio);render()"></button></div><div class="navigation-recording-toggle-row"><span class="navigation-recording-kind-icon">◉</span><div><b>Video</b><small>Participant camera, without microphone unless Audio is also enabled</small></div><button type="button" class="switch ${b.navigationRecordVideo?'on':''}" role="switch" aria-checked="${b.navigationRecordVideo?'true':'false'}" aria-label="Record video" onclick="updateBlock('${b.id}','navigationRecordVideo',!currentStudy().blocks.find(x=>x.id==='${b.id}').navigationRecordVideo);render()"></button></div><div class="navigation-recording-toggle-row"><span class="navigation-recording-kind-icon">${eveIcon('screen',17)}</span><div><b>Screen</b><small>Shared screen/window; participant chooses what to share</small></div><button type="button" class="switch ${b.navigationRecordScreen?'on':''}" role="switch" aria-checked="${b.navigationRecordScreen?'true':'false'}" aria-label="Record screen" onclick="updateBlock('${b.id}','navigationRecordScreen',!currentStudy().blocks.find(x=>x.id==='${b.id}').navigationRecordScreen);render()"></button></div></div>${navModes.length?`<div class="builder-type-note">${navModes.map(navigationRecordingLabel).join(' + ')} enabled. Eve saves each enabled capture separately against the same task attempt. ${b.timeoutEnabled?'The task timeout also stops all recordings.':'A 15-minute recording safety limit applies.'}</div>`:`<div class="builder-type-note">Task recording is off. Enable any option above to record this navigation task.</div>`}</section>`:EveCapabilities.inlineNotice('navigationCapture')}`}
 return `<article class="block-card block-family-${blockFamily} ${state.activeBlockId===b.id?'selected':''} ${issues.length?'has-issues':''}" data-block="${b.id}" data-block-type="${b.type}" ondragover="blockDragOver(event,'${b.id}')" ondragleave="event.currentTarget.classList.remove('drag-over-before','drag-over-after')" ondrop="dropBlock(event,'${b.id}')"><div class="block-head"><button type="button" class="canvas-block-drag-handle" draggable="true" ondragstart="startBlockDrag(event,'${b.id}')" ondragend="endStructureDrag()" aria-label="Drag ${esc(b.title||label(b.type))} to reorder" title="Drag section to reorder">${eveIcon('grip',16)}</button><div style="flex:1"><div class="block-meta-line"><div class="block-type">${label(b.type)}</div>${requirementChip}${issues.length?`<span class="block-check needs">${issues.length} check${issues.length===1?'':'s'}</span>`:`<span class="block-check ready">Ready</span>`}</div><input class="inline-title" aria-label="Section title — editable" value="${esc(b.title||label(b.type))}" oninput="updateBlock('${b.id}','title',this.value)" onfocus="state.activeBlockId='${b.id}'"/></div><div class="block-actions"><span class="section-order-controls"><button class="icon-btn section-order-btn" onclick="moveBlock('${b.id}',-1)" title="Move section up" aria-label="Move section up" ${canMoveUp?'':'disabled'}>${eveIcon('arrowUp',15)}</button><button class="icon-btn section-order-btn" onclick="moveBlock('${b.id}',1)" title="Move section down" aria-label="Move section down" ${canMoveDown?'':'disabled'}>${eveIcon('arrowDown',15)}</button></span>${study&&study.pages.length>1?`<label class="section-page-move"><span>Page</span><select aria-label="Move section to page" onchange="if(this.value!=='${b.pageId}')moveBlockToPage('${b.id}',this.value)">${study.pages.map((p,i)=>`<option value="${p.id}" ${p.id===b.pageId?'selected':''}>${i+1}</option>`).join('')}</select></label>`:''}</div>${blockOverflowMenuMarkup(b)}</div>${issues.length?`<div class="builder-issue-banner"><b>Needs attention</b>${issues.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}${inner}<button class="insert-step-between" onclick="state.activeBlockId='${b.id}';state.activePageId='${b.pageId}';state.modal='add';render()">+ Add step after this</button></article>`}
function openSectionSettings(id){const s=currentStudy();const b=s?.blocks.find(x=>x.id===id);if(!s||!b)return;state.activeBlockId=id;state.activePageId=b.pageId;state.sectionSettingsId=id;render()}
function closeSectionSettings(){state.sectionSettingsId=null;render()}
function moveSectionFromSettings(id,pageId){state.sectionSettingsId=id;moveBlockToPage(id,pageId);state.sectionSettingsId=id}
function sectionSettingsDrawer(s){const b=s.blocks.find(x=>x.id===state.sectionSettingsId);if(!b){state.sectionSettingsId=null;return''}const issues=blockIssues(b);return `<div class="section-settings-backdrop" onclick="if(event.target===this)closeSectionSettings()"><aside class="section-settings-drawer" role="dialog" aria-modal="true" aria-labelledby="section-settings-title"><div class="section-settings-head"><div><span class="section-label">SECTION SETTINGS</span><h3 id="section-settings-title">${esc(b.title||label(b.type))}</h3><p>${label(b.type)}</p></div><button class="icon-btn settings-close" onclick="closeSectionSettings()" aria-label="Close section settings">×</button></div><div class="section-settings-body"><section class="settings-group"><h4>Behaviour</h4>${b.type==='consent'?`<div class="settings-note consent-settings-note"><b>${consentConfirmations(b).length} required confirmation${consentConfirmations(b).length===1?'':'s'}</b><span>Consent confirmations are configured in the block itself. Every confirmation you add must be checked by participants.</span></div>`:b.type==='panelSignup'?`<div class="settings-note consent-settings-note"><b>Optional panel opt-in</b><span>Panel membership is always voluntary and never blocks completion of the research study.</span></div>`:`<div class="toggle settings-toggle"><span><b>Required</b><small>Participants must complete this section before continuing.</small></span><button type="button" class="switch ${b.required?'on':''}" role="switch" aria-checked="${b.required?'true':'false'}" aria-label="Required section" onclick="updateBlock('${b.id}','required',!currentStudy().blocks.find(x=>x.id==='${b.id}').required);render()"></button></div>`}<div class="field compact-field"><label>Page</label><select class="select" onchange="moveSectionFromSettings('${b.id}',this.value)">${s.pages.map((p,i)=>`<option value="${p.id}" ${p.id===b.pageId?'selected':''}>${i+1}. ${esc(p.title||`Page ${i+1}`)}</option>`).join('')}</select></div></section><section class="settings-group"><h4>Quality checks</h4>${issues.length?`<div class="properties-checks needs">${issues.map(i=>`<div><span>!</span>${esc(i)}</div>`).join('')}</div>`:`<div class="properties-checks ready"><div><span>✓</span>This section is ready to preview.</div></div>`}${['question','multiChoice','scale','screener','shortText','number','date','matrix','preference'].includes(b.type)?`<button class="ai-action" onclick="aiCheckQuestion('${b.id}')"><span>${eveIcon('sparkle',16)}</span><div><b>Check question quality</b><small>Bias, clarity and wording</small></div></button>`:''}${b.type==='treeTest'?`<button class="ai-action" onclick="aiCheckTask('${b.id}')"><span>${eveIcon('sparkle',16)}</span><div><b>Check task wording</b><small>Avoid answer leakage</small></div></button>`:''}</section></div></aside></div>`}

function sSetting(k,v){const s=currentStudy();if(!s)return;if(state.view==='builder')recordStudyHistory(`setting:${k}`);s.settings[k]=v;if(k==='anonymous'&&v===false)s.settings.collectEmail=true;if(k==='collectEmail'&&v===false){s.settings.anonymous=true;s.settings.recontact=false}if(k==='recontact'&&v===true)s.settings.collectEmail=true;s.updatedAt=Date.now();scheduleSave()}



function addPage(){const s=currentStudy();if(!s)return;recordStudyHistory('add-page',false);ensureStudyPages(s);const page={id:uid(),title:`Page ${s.pages.length+1}`};s.pages.push(page);state.activePageId=page.id;state.activeBlockId=null;s.updatedAt=Date.now();scheduleSave();render();scrollToBuilderPage(page.id);toast('New page added')}
function duplicatePage(id){const s=currentStudy();if(!s)return;recordStudyHistory(`duplicate-page:${id}`,false);ensureStudyPages(s);const i=s.pages.findIndex(p=>p.id===id);if(i<0)return;const source=s.pages[i];const page={...JSON.parse(JSON.stringify(source)),id:uid(),title:`${source.title||`Page ${i+1}`} copy`};s.pages.splice(i+1,0,page);const sourceBlocks=pageBlocks(s,id);const clones=sourceBlocks.map(b=>{const clone={...JSON.parse(JSON.stringify(b)),id:uid(),pageId:page.id,title:b.title};if(clone.type==='consent'&&Array.isArray(clone.confirmations))clone.confirmations=clone.confirmations.map(item=>({...item,id:uid()}));return clone});let insert=s.blocks.length;for(let j=s.blocks.length-1;j>=0;j--){if(s.blocks[j].pageId===id){insert=j+1;break}}s.blocks.splice(insert,0,...clones);state.activePageId=page.id;state.activeBlockId=clones[0]?.id||null;s.updatedAt=Date.now();scheduleSave();render();scrollToBuilderPage(page.id);toast('Page duplicated')}
async function removePage(id){const s=currentStudy();if(!s)return;ensureStudyPages(s);if(s.pages.length<=1)return toast('A study needs at least one page');const page=s.pages.find(p=>p.id===id);if(!page)return;if(!await miniConfirm('Delete page?',`“${page.title||'This page'}” and every step on it will be removed.`,'Delete page'))return;recordStudyHistory(`remove-page:${id}`,false);const i=s.pages.findIndex(p=>p.id===id);s.pages.splice(i,1);s.blocks=s.blocks.filter(b=>b.pageId!==id);const next=s.pages[Math.min(i,s.pages.length-1)];state.activePageId=next?.id||null;state.activeBlockId=pageBlocks(s,state.activePageId)[0]?.id||null;s.updatedAt=Date.now();scheduleSave();render()}
async function loadHighlighterImage(event,blockId){
 const file=event?.target?.files?.[0];if(!file)return;if(!/^image\/(png|jpeg|webp)$/i.test(file.type))return toast('Choose a PNG, JPG or WebP image',2600,'error');if(file.size>12*1024*1024)toast('Large image · Eve will optimise it locally',2200);
 try{const data=await optimiseHighlighterImage(file);const b=currentStudy()?.blocks.find(x=>x.id===blockId);if(!b)return;recordStudyHistory(`highlighter-image:${blockId}`,false);b.imageData=data;b.imageName=file.name;b.imageType=file.type;currentStudy().updatedAt=Date.now();scheduleSave();render();toast('Image added',1800,'success')}catch(err){console.error(err);toast('Could not prepare that image',2600,'error')}finally{if(event?.target)event.target.value=''}
}
function optimiseHighlighterImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const max=1800,scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight)),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale));if(scale===1&&file.size<2.5*1024*1024)return resolve(String(reader.result));const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(img,0,0,w,h);resolve(canvas.toDataURL(file.type==='image/png'?'image/png':'image/jpeg',.88))};img.src=String(reader.result)};reader.readAsDataURL(file)})}
function removeHighlighterImage(blockId){const b=currentStudy()?.blocks.find(x=>x.id===blockId);if(!b)return;recordStudyHistory(`highlighter-image-remove:${blockId}`,false);b.imageData='';b.imageName='';b.imageType='';b.imageAlt='';currentStudy().updatedAt=Date.now();scheduleSave();render()}
function addModal(){return `<div class="modal" onclick="state.modal=null;render()"><div class="modal-card add-step-modal" onclick="event.stopPropagation()"><div class="modal-head"><div><div class="eyebrow">ADD STEP</div><h3>What do you want participants to do?</h3><p class="muted">It will be added ${currentBlock()&&currentBlock().pageId===state.activePageId?'after the selected step':'to the end of this page'}.</p></div><button class="icon-btn modal-close-icon" type="button" aria-label="Close Add step" title="Close" onclick="state.modal=null;render()">×</button></div><div class="field add-search"><label for="add-step-search">Find a step type</label><div class="add-search-row"><input id="add-step-search" class="input" autofocus placeholder="Search questions and tasks…" oninput="filterAddSteps(this.value)"/><button type="button" class="text-btn" data-add-search-clear hidden onclick="clearAddStepSearch()">Clear</button></div><div class="add-search-meta"><span data-add-search-count>19 step types</span><span>Choose the interaction that best matches your research goal.</span></div></div><div class="add-empty-search" data-add-search-empty hidden>${eveIcon('search',22)}<b>No step types found</b><small>Try a broader search, such as “choice”, “task” or “text”.</small></div><div class="add-section"><div class="section-label">RESEARCH TASKS</div><div class="add-menu">${[['cardSort','cards','Card sort','Understand how people group information'],['treeTest','tree','Tree test','Validate findability in an information architecture'],['navigationTask','external','Navigation task','Send participants to a start page with a target destination'],['highlighter','highlighter','Highlighter task','Ask participants to mark areas of interest on an image'],['recording','mic','Recording','Capture an audio or video response in the participant’s own words'],['ranking','ranking','Ranking task','Ask participants to order items by priority or preference'],['preference','heart','Preference test','Compare concepts, labels or content choices']].map(x=>addOptionMarkup(x)).join('')}</div></div><div class="add-section"><div class="section-label">QUESTIONS</div><div class="add-menu">${[['question','radio','Single choice','Choose one response'],['multiChoice','checkSquare','Multiple choice','Choose one or more responses'],['scale','scale','Rating scale','Measure sentiment or confidence'],['matrix','cards','Matrix','Rate several statements on the same scale'],['shortText','text','Short text','Collect a concise one-line answer'],['number','hash','Number','Collect a numeric response'],['date','calendar','Date','Collect a calendar date'],['openText','text','Open text','Collect qualitative feedback']].map(x=>addOptionMarkup(x)).join('')}</div></div><div class="add-section"><div class="section-label">STUDY</div><div class="add-menu">${[['screener','filter','Screener','Qualify participants or end the study early'],['consent','check','Consent','Capture participant agreement'],['panelSignup','participants','Panel sign-up','Invite participants to join your reusable research panel'],['intro','info','Information','Explain a task or section']].map(x=>addOptionMarkup(x)).join('')}</div></div></div></div>`}
function addOptionMarkup(x){const support=EveCapabilities.blockSupport(x[0]);return `<button class="add-option ${support.supported?'':'unsupported'}" data-search="${esc(`${x[2]} ${x[3]} ${x[0]}`.toLowerCase())}" ${support.supported?`onclick="addBlock('${x[0]}')"`:'disabled'} title="${support.supported?'':esc(support.note)}"><span>${eveIcon(x[1],20)}</span><div><b>${x[2]}</b><small>${support.supported?x[3]:'Not available in this deployment'}</small></div></button>`}
function addBlock(type){const s=currentStudy();if(!s)return;const support=EveCapabilities.blockSupport(type);if(!support.supported)return toast(support.note||'This block is not available in this deployment.',5000,'error');if(type==='panelSignup'&&s.blocks.some(b=>b.type==='panelSignup'))return toast('A study can only contain one Panel sign-up block',2800,'error');recordStudyHistory(`add-block:${type}`,false);ensureStudyPages(s);let page=currentPage();if(!page){page={id:uid(),title:'Page 1'};s.pages.push(page);state.activePageId=page.id}const templates={question:{question:'Enter your question',options:['Option 1','Option 2'],required:true},multiChoice:{question:'Enter your question',options:['Option 1','Option 2','Option 3'],required:true},scale:{question:'How would you rate this?',points:5,lowLabel:'Not at all',highLabel:'Extremely',required:true},matrix:{question:'How much do you agree with each statement?',rows:['Statement 1','Statement 2','Statement 3'],points:5,lowLabel:'Strongly disagree',highLabel:'Strongly agree',required:true},shortText:{question:'Enter your question',placeholder:'Type your answer…',maxLength:120,required:true},number:{question:'Enter your question',min:'',max:'',unit:'',required:true},date:{question:'Enter your question',required:true},screener:{question:'Which of these best describes you?',options:['Eligible participant','Not eligible'],screenOut:'Not eligible',required:true},openText:{question:'Enter your question'},ranking:{question:'Put these in order from most to least important',options:['Item 1','Item 2','Item 3'],required:true},preference:{question:'Which option do you prefer?',options:['Option A','Option B'],required:true},cardSort:{mode:'open',cards:['Card 1','Card 2','Card 3'],categories:[],required:true},treeTest:{task:'Describe what the participant should find',tree:'Home\n  Section A\n    Page 1\n  Section B\n    Page 2',target:'Home > Section A > Page 1',required:true},navigationTask:{instructions:'Find the requested information using the website. Return to Eve when you are finished.',startPage:'https://example.com/',successPage:'https://example.com/success',timeoutEnabled:true,timeoutMinutes:5,navigationRecordAudio:false,navigationRecordVideo:false,navigationRecordScreen:false,required:true},highlighter:{instructions:'Highlight the parts of this image that draw your attention or seem important.',imageData:'',imageName:'',imageType:'',imageAlt:'',highlighterMeanings:[{id:uid(),label:'Good',color:'#2f9e62'},{id:uid(),label:'Problem',color:'#d14343'}],required:true},recording:{prompt:'Tell us what you are thinking.',recordingMode:'audio',recordingTimeLimitMinutes:2,required:true},consent:{body:'Please read the information above and confirm the statements below.',required:true,confirmations:[{id:uid(),text:'I agree to take part in this research.'}]},panelSignup:{panelIntro:'Join our participant panel to hear about future research opportunities.',panelTermsEnabled:true,panelTerms:'By joining the panel, you agree that the research team can contact you about future research opportunities.',panelConsentLabel:'I agree to join the research participant panel.',panelWelcomeSubject:'',panelWelcomeMessage:'',required:false},intro:{body:'Add information for participants.'}};const b={id:uid(),pageId:page.id,type,title:label(type),...templates[type]};let insert=s.blocks.length;const active=currentBlock();if(active&&active.pageId===page.id){const i=s.blocks.findIndex(x=>x.id===active.id);if(i>=0)insert=i+1}else{for(let i=s.blocks.length-1;i>=0;i--){if(s.blocks[i].pageId===page.id){insert=i+1;break}}}s.blocks.splice(insert,0,b);state.activeBlockId=b.id;state.modal=null;s.updatedAt=Date.now();scheduleSave();render();setTimeout(()=>document.querySelector(`[data-block="${b.id}"]`)?.scrollIntoView({behavior:'smooth',block:'start'}),10)}
function moveBlock(id,delta){const s=currentStudy();const b=s?.blocks.find(x=>x.id===id);if(!s||!b)return;const ids=pageBlocks(s,b.pageId).map(x=>x.id);const pos=ids.indexOf(id);const targetPos=pos+delta;if(pos<0||targetPos<0||targetPos>=ids.length)return;recordStudyHistory(`reorder-block:${id}`,false);const targetId=ids[targetPos];const i=s.blocks.findIndex(x=>x.id===id),j=s.blocks.findIndex(x=>x.id===targetId);[s.blocks[i],s.blocks[j]]=[s.blocks[j],s.blocks[i]];state.activePageId=b.pageId;state.activeBlockId=id;s.updatedAt=Date.now();scheduleSave();render();setTimeout(()=>document.querySelector(`[data-block="${id}"]`)?.scrollIntoView({behavior:'smooth',block:'nearest'}),10)}
function duplicateBlock(id){const s=currentStudy();const source=s?.blocks.find(b=>b.id===id);if(source?.type==='panelSignup')return toast('A study can only contain one Panel sign-up block',2800,'error');recordStudyHistory(`duplicate-block:${id}`,false);if(state.sectionSettingsId===id)state.sectionSettingsId=null;const i=s.blocks.findIndex(b=>b.id===id);if(i<0)return;const copy=JSON.parse(JSON.stringify(s.blocks[i]));copy.id=uid();if(copy.type==='consent'&&Array.isArray(copy.confirmations))copy.confirmations=copy.confirmations.map(item=>({...item,id:uid()}));copy.title=`${copy.title} copy`;s.blocks.splice(i+1,0,copy);state.activeBlockId=copy.id;scheduleSave();render()}
async function bulkOptions(id){const b=currentStudy()?.blocks.find(x=>x.id===id);if(!b)return;const noun=b.type==='ranking'?'ranking items':b.type==='preference'?'choices':'answer options';const raw=await miniPrompt(`Add ${noun}`,`Paste one ${b.type==='ranking'?'item':'option'} per line.`,{placeholder:'Option one\nOption two\nOption three',confirmLabel:`Add ${b.type==='ranking'?'items':'options'}`});if(!raw)return;const options=raw.split(/\n/).map(x=>x.trim()).filter(Boolean);if(options.length<2)return toast(`Add at least two ${b.type==='ranking'?'items':'options'}`);recordStudyHistory(`bulk-options:${id}`,false);b.options=options;if(b.type==='screener'&&!options.includes(b.screenOut))b.screenOut='';scheduleSave();render();toast(`${options.length} ${b.type==='ranking'?'items':'options'} added`)}
function treeVisualPreview(text=''){const nodes=parseTree(text);if(!nodes.length)return'<div class="muted small">Add nodes to see the structure.</div>';let html='',depth=-1;nodes.forEach((n,i)=>{while(depth<n.depth){html+='<ul>';depth++}while(depth>n.depth){html+='</li></ul>';depth--}if(i&&nodes[i-1].depth===n.depth)html+='</li>';html+=`<li><span>${esc(n.label)}</span>`});while(depth>=0){html+='</li></ul>';depth--}return `<div class="tree-visual">${html}</div>`}
function addOption(id){recordStudyHistory(`add-option:${id}`,false);currentStudy().blocks.find(x=>x.id===id).options.push('New option');scheduleSave();render()}
function removeOption(id,i){const b=currentStudy().blocks.find(x=>x.id===id);if(b.options.length<=2)return toast('Keep at least two options');recordStudyHistory(`remove-option:${id}`,false);const [removed]=b.options.splice(i,1);if(b.type==='screener'&&b.screenOut===removed)b.screenOut='';scheduleSave();render()}
function addCard(id){recordStudyHistory(`add-card:${id}`,false);currentStudy().blocks.find(x=>x.id===id).cards.push('New card');scheduleSave();render()}
function removeCard(id,i){recordStudyHistory(`remove-card:${id}`,false);currentStudy().blocks.find(x=>x.id===id).cards.splice(i,1);scheduleSave();render()}
function updateCard(id,i,v){recordStudyHistory(`card:${id}:${i}`);currentStudy().blocks.find(x=>x.id===id).cards[i]=v;scheduleSave()}
function addCategory(id){recordStudyHistory(`add-category:${id}`,false);currentStudy().blocks.find(x=>x.id===id).categories.push('New category');scheduleSave();render()}
function removeCategory(id,i){recordStudyHistory(`remove-category:${id}`,false);currentStudy().blocks.find(x=>x.id===id).categories.splice(i,1);scheduleSave();render()}
function updateCategory(id,i,v){recordStudyHistory(`category:${id}:${i}`);currentStudy().blocks.find(x=>x.id===id).categories[i]=v;scheduleSave()}
async function removeBlock(id){const s=currentStudy();if(!s)return;const b=s.blocks.find(x=>x.id===id);if(!b)return;if(!await miniConfirm('Delete step?',`“${b.title||label(b.type)}” will be removed from this page.`,'Delete step'))return;if(state.sectionSettingsId===id)state.sectionSettingsId=null;recordStudyHistory(`remove-block:${id}`,false);const pageId=b.pageId;const pageBefore=pageBlocks(s,pageId);const pos=pageBefore.findIndex(x=>x.id===id);s.blocks=s.blocks.filter(x=>x.id!==id);const remaining=pageBlocks(s,pageId);state.activePageId=pageId;state.activeBlockId=remaining[Math.min(pos,Math.max(0,remaining.length-1))]?.id||null;s.updatedAt=Date.now();scheduleSave();render()}
async function bulkCards(id){const raw=await miniPrompt('Add card-sort cards','Paste one card per line.',{placeholder:'Change my address\nDownload a statement\nMake a contribution',confirmLabel:'Add cards'});if(!raw)return;const cards=raw.split(/\n/).map(x=>x.trim()).filter(Boolean);if(!cards.length)return;recordStudyHistory(`bulk-cards:${id}`,false);currentStudy().blocks.find(x=>x.id===id).cards=cards;scheduleSave();render();toast(`${cards.length} cards added`)}


