function resolvedStudyStorage(s){if(globalThis.EveCloud?.resolvedStudyStorage)return globalThis.EveCloud.resolvedStudyStorage(s);const usesOrganisationDefault=s.settings.storageProvider==='organisation';const provider=usesOrganisationDefault?state.storage.provider:s.settings.storageProvider;const fallback=provider===state.storage.provider?state.storage.location:`Eve / ${s.title||'Study'}`;const location=(s.settings.storageLocation||'').trim()||fallback;const connected=usesOrganisationDefault?!!state.storage.connected:(provider===state.storage.provider&&!!state.storage.connected);return {provider,location,usesOrganisationDefault,connected}}
function toLocalDateTimeInput(iso){if(!iso)return'';const d=new Date(iso);if(!Number.isFinite(d.getTime()))return'';const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}
function setLifecycleLocal(kind,value){const s=currentStudy();if(!s)return;const key=kind==='start'?'startAtUtc':'closeAtUtc';s.settings[key]=value?new Date(value).toISOString():'';if(kind==='end')s.settings.closeAt=value?value.slice(0,10):'';s.updatedAt=Date.now();scheduleSave()}
function setStartLocal(value){setLifecycleLocal('start',value)}
function setClosingLocal(value){setLifecycleLocal('end',value)}
function studySettings(){
 const s=currentStudy();if(!s)return home();const store=resolvedStudyStorage(s);
 return shell(`${studyFlow(s,'settings')}<div class="content settings-layout"><section class="settings-hero"><div><div class="eyebrow">STUDY SETTINGS</div><h2>Configure how this study behaves.</h2><p>Keep build decisions separate from data, privacy and operational settings. These choices travel with this study.</p></div><div class="settings-summary"><span>Data destination</span><b>${esc(store.provider)}</b><small>${esc(store.location)}</small></div></section>${EveCapabilities.studyBanner(s)}<div class="settings-grid"><section class="card settings-card"><div class="settings-card-icon">${eveIcon('settings',20)}</div><div class="section-label">STUDY</div><h3>Study lifecycle</h3><p>Choose exactly when the study opens and closes. Response targets are configured per segment in Send.</p><div class="lifecycle-datetime-grid"><div class="field"><label>Start date &amp; time</label><input class="input" type="datetime-local" step="60" value="${esc(toLocalDateTimeInput(s.settings.startAtUtc||''))}" onchange="setStartLocal(this.value);render()"/><small class="muted">Leave blank to open as soon as the study goes live.</small></div><div class="field"><label>End date &amp; time</label><input class="input" type="datetime-local" step="60" value="${esc(toLocalDateTimeInput(s.settings.closeAtUtc||''))}" onchange="setClosingLocal(this.value);render()"/><small class="muted">Leave blank to keep the study open until you close it manually.</small></div></div><div class="settings-note lifecycle-note">Times use your local timezone and are stored as exact instants. Participants cannot enter before the start time or after the end time.</div><div class="field"><label>Completion message</label><textarea class="textarea compact-textarea" oninput="sSetting('completionMessage',this.value)">${esc(s.settings.completionMessage||'')}</textarea></div></section>${studyThemeSettingsMarkup(s)}<section class="card settings-card"><div class="settings-card-icon">${eveIcon('participants',20)}</div><div class="section-label">PARTICIPANT DATA</div><h3>Privacy and identity</h3><p>Decide whether this study is anonymous and whether participants can opt into future research.</p><div class="settings-toggle-list"><div class="toggle"><span><b>Anonymous responses</b><small>Do not require participant identity</small></span><button type="button" class="switch ${s.settings.anonymous?'on':''}" role="switch" aria-checked="${s.settings.anonymous?'true':'false'}" aria-label="Anonymous responses" onclick="sSetting('anonymous',!currentStudy().settings.anonymous);render()"></button></div><div class="toggle"><span><b>Collect participant email</b><small>Only when identity is genuinely needed</small></span><button type="button" class="switch ${s.settings.collectEmail?'on':''}" role="switch" aria-checked="${s.settings.collectEmail?'true':'false'}" aria-label="Collect participant email" onclick="sSetting('collectEmail',!currentStudy().settings.collectEmail);render()"></button></div><div class="toggle"><span><b>Offer recontact opt-in</b><small>${s.settings.collectEmail?'Explicit consent for future research':'Enabling this also enables email collection'}</small></span><button type="button" class="switch ${s.settings.recontact?'on':''}" role="switch" aria-checked="${s.settings.recontact?'true':'false'}" aria-label="Offer recontact opt-in" onclick="sSetting('recontact',!currentStudy().settings.recontact);render()"></button></div></div></section><section class="card settings-card wide storage-settings-card"><div class="settings-card-icon">${eveIcon('storage',20)}</div><div class="section-label">DATA STORAGE</div><h3>Choose where this study lives</h3><p>The durable research files belong in client-controlled cloud storage. Eve only keeps the minimum account and routing metadata.</p><div class="study-storage-grid"><label class="storage-choice ${s.settings.storageProvider==='organisation'?'selected':''}"><input type="radio" name="study-storage" value="organisation" ${s.settings.storageProvider==='organisation'?'checked':''} onchange="sSetting('storageProvider','organisation');render()"><span><b>Organisation default</b><small>${esc(state.storage.provider)} · ${esc(state.storage.location)}</small></span></label><label class="storage-choice ${s.settings.storageProvider==='SharePoint'?'selected':''}"><input type="radio" name="study-storage" value="SharePoint" ${s.settings.storageProvider==='SharePoint'?'checked':''} onchange="sSetting('storageProvider','SharePoint');render()"><span><b>Microsoft SharePoint</b><small>Use an approved SharePoint research location</small></span></label><label class="storage-choice ${s.settings.storageProvider==='Google Drive'?'selected':''}"><input type="radio" name="study-storage" value="Google Drive" ${s.settings.storageProvider==='Google Drive'?'checked':''} onchange="sSetting('storageProvider','Google Drive');render()"><span><b>Google Drive</b><small>Use an app-created or explicitly approved location</small></span></label></div><div class="field storage-path-field"><label>Study folder / location ${s.settings.storageProvider==='organisation'?'<span class="muted">(optional override)</span>':''}</label><input class="input" value="${esc(s.settings.storageLocation||'')}" placeholder="${esc(state.storage.location)}" oninput="sSetting('storageLocation',this.value)"/></div><div class="storage-resolution"><span class="status-dot ${store.connected?'':'warn'}"></span><div><b>Resolved destination: ${esc(store.provider)}</b><small>${esc(store.location)} · protected before sync</small></div><button class="btn" onclick="navigate('/storage')">Organisation storage</button></div></section><section class="card settings-card study-ai-card"><div class="settings-card-icon">${eveIcon('sparkle',20)}</div><div class="section-label">AI ACCESS</div><h3>Control what AI can see</h3><p>AI is optional and controlled per study.</p><div class="field"><label>AI permission</label><select class="select" onchange="sSetting('ai',this.value);render()"><option value="off" ${s.settings.ai==='off'?'selected':''}>Off — local only</option><option value="anonymous" ${s.settings.ai==='anonymous'?'selected':''}>Anonymised assistance</option><option value="full" ${s.settings.ai==='full'?'selected':''}>Full study access</option></select></div><div class="settings-note">${s.settings.ai==='off'?'No study content is sent to a cloud AI provider.':s.settings.ai==='anonymous'?'Identifiers are intended to be removed before AI analysis.':'Full study content may be made available to the configured AI provider.'}</div></section><section class="card settings-card"><div class="settings-card-icon">⌁</div><div class="section-label">VERSIONING</div><h3>Live-study safety</h3><p>Participants only ever see a versioned live snapshot. Editing a live study creates draft changes until you explicitly update the live study.</p><div class="boundary-list"><div><span>Current status</span><b>${s.status}</b></div><div><span>Live version</span><b>${latestPublishedVersion(s)?`v${s.version}`:'—'}</b></div><div><span>Changes not live</span><b>${s.hasUnpublishedChanges?'Yes':'No'}</b></div></div></section></div><section class="card study-danger-zone"><div><div class="section-label">ARCHIVE</div><h3>Archive this study</h3><p>Remove it from the active workspace while keeping the study, responses, recordings and insights recoverable for 30 days.</p></div><button type="button" class="btn danger" onclick="archiveStudy('${s.id}')">Move to Archive</button></section></div>`,'Study settings',`<span class="save-state" data-save>${state.saveState}</span><button class="btn" onclick="navigate('/study/${s.id}/build')">← Build</button><button class="btn primary" onclick="navigate('/study/${s.id}/send')">Send →</button>`)
}


function qrSvgMarkup(text,{moduleSize=5,margin=4}={}){
 if(!text)return '';
 if(!window.EveQR?.QRCode)return '<div class="qr-error">QR generator unavailable</div>';
 try{
   const qr=new window.EveQR.QRCode(-1,window.EveQR.ErrorCorrectLevel.M);
   qr.addData(String(text));qr.make();
   const count=qr.getModuleCount(),total=count+margin*2,size=total*moduleSize;
   let path='';
   for(let row=0;row<count;row++)for(let col=0;col<count;col++)if(qr.isDark(row,col))path+=`M${(col+margin)*moduleSize} ${(row+margin)*moduleSize}h${moduleSize}v${moduleSize}h-${moduleSize}z`;
   return `<svg class="share-qr-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}" role="img" aria-label="QR code for participant study link" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="#fff"/><path d="${path}" fill="#17233f"/></svg>`
 }catch(err){console.error('QR generation failed',err);return '<div class="qr-error">Could not generate QR code</div>'}
}
function qrSvgDocument(text){return `<?xml version="1.0" encoding="UTF-8"?>\n${qrSvgMarkup(text,{moduleSize:8,margin:4}).replace('class="share-qr-svg"','class="share-qr-svg" width="640" height="640"')}`}
function safeFileName(value){return String(value||'study').trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,60)||'study'}
function activeSendSegments(s){return (s?.sendSegments||[]).filter(seg=>!seg.archived)}
function sendSegmentUrl(s,segmentId='all'){return !segmentId||segmentId==='all'?publicStudyUrl(s):trackedUrl(s,'direct',segmentId,'','',s.version)}
function setSendShareMode(mode){state.sendShareMode=mode==='qr'?'qr':'link';render()}
function toggleSendSegment(id){state.sendExpandedSegmentId=state.sendExpandedSegmentId===id?'':id;render()}
function sendSegmentTarget(s,segmentId='all'){if(segmentId==='all')return Math.max(1,Math.round(Number(s?.sendDefaultTarget)||50));const seg=activeSendSegments(s).find(x=>x.id===segmentId);return Math.max(1,Math.round(Number(seg?.target)||50))}
function sendSegmentResponseCount(s,segmentId='all'){
 const rs=researchResponses(studyResponses(s.id,s.version));
 return segmentId==='all'?rs.filter(r=>!r.attributedSegmentId).length:rs.filter(r=>r.attributedSegmentId===segmentId).length
}
function sendSegmentProgress(target,count){const t=Math.max(1,Number(target)||1),responses=Math.max(0,Number(count)||0),percent=Math.min(100,Math.round(responses/t*100));return {target:t,responses,percent,reached:responses>=t,remaining:Math.max(0,t-responses)}}
function setSendSegmentTarget(studyId,segmentId,value){
 const s=state.studies.find(x=>x.id===studyId);if(!s)return;const target=Math.max(1,Math.round(Number(value)||1));
 if(segmentId==='all')s.sendDefaultTarget=target;else{const seg=s.sendSegments?.find(x=>x.id===segmentId&&!x.archived);if(!seg)return;seg.target=target}
 s.updatedAt=Date.now();scheduleSave();render()
}
function studyLinkShareability(s){
 const v=latestPublishedVersion(s);if(!v)return {available:false,reason:'Go live to activate participant access.'};
 if(s.status!=='live')return {available:false,reason:'This study is currently turned off. Go live to reactivate participant access.'};
 const snap=publishedStudy(s,v),close=closingInstant(snap);if(close&&Date.now()>=close)return {available:false,reason:'This study has ended. Update the end time before going live again.'};
 return {available:true,reason:''}
}
async function createStudySendSegment(studyId){
 const s=state.studies.find(x=>x.id===studyId);if(!s)return;
 const name=(await miniPrompt('Create segment','Give this audience a short name. Eve will create a unique participant link and response target for it.',{placeholder:'e.g. Existing customers',confirmLabel:'Create segment'}))?.trim();if(!name)return;
 s.sendSegments=s.sendSegments||[];
 if(name.toLowerCase()==='all users'||name.toLowerCase()==='all')return toast('All users is the permanent default segment');
 if(s.sendSegments.some(x=>!x.archived&&x.name.toLowerCase()===name.toLowerCase()))return toast('A segment with that name already exists');
 const seg={id:uid(),name,target:50,createdAt:Date.now(),archived:false};s.sendSegments.push(seg);state.sendExpandedSegmentId=seg.id;
 await persistWorkspace(false);render();toast(`${name} created`,2200,'success')
}
async function removeStudySendSegment(studyId,segmentId){
 const s=state.studies.find(x=>x.id===studyId),seg=s?.sendSegments?.find(x=>x.id===segmentId);if(!s||!seg)return;
 if(!await miniConfirm('Delete segment?',`“${seg.name}” and its sharing link will be removed. Existing responses keep their segment attribution.`,'Delete segment'))return;
 seg.archived=true;seg.archivedAt=Date.now();if(state.sendExpandedSegmentId===segmentId)state.sendExpandedSegmentId='all';
 await persistWorkspace(false);render();toast('Segment deleted')
}
async function copySendLink(studyId,segmentId='all'){const s=state.studies.find(x=>x.id===studyId);if(!s)return;const share=studyLinkShareability(s);if(!share.available)return toast(share.reason);const url=sendSegmentUrl(s,segmentId);try{await navigator.clipboard.writeText(url);toast('Participant link copied',2200,'success')}catch{await miniCopy('Copy participant link',url)}}
function openSendLink(studyId,segmentId='all'){const s=state.studies.find(x=>x.id===studyId);if(!s)return;const share=studyLinkShareability(s);if(!share.available)return toast(share.reason);window.open(sendSegmentUrl(s,segmentId),'_blank','noopener,noreferrer')}
function downloadSendQr(studyId,segmentId='all'){const s=state.studies.find(x=>x.id===studyId);if(!s)return;const share=studyLinkShareability(s);if(!share.available)return toast(share.reason);try{const seg=segmentId==='all'?null:activeSendSegments(s).find(x=>x.id===segmentId),svg=qrSvgDocument(sendSegmentUrl(s,segmentId)),blob=new Blob([svg],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${safeFileName(s.title)}-${safeFileName(seg?.name||'all-users')}-qr.svg`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200);toast('QR code downloaded',2200,'success')}catch(err){console.error(err);toast('Could not download the QR code',2600,'error')}}
function sendSegmentCardMarkup(s,seg=null){
 const segmentId=seg?.id||'all',isAll=segmentId==='all',expanded=state.sendExpandedSegmentId===segmentId,name=seg?.name||'All users',count=sendSegmentResponseCount(s,segmentId),target=sendSegmentTarget(s,segmentId),progress=sendSegmentProgress(target,count),share=studyLinkShareability(s),shareReady=share.available,url=shareReady?sendSegmentUrl(s,segmentId):'',qrMode=state.sendShareMode==='qr';
 const summaryStatus=progress.reached?'Target reached':`${progress.remaining} remaining`;
 return `<section class="send-segment-card ${expanded?'expanded':''} ${isAll?'default':''}">
   <div class="send-segment-card-head">
     <button class="send-segment-summary" type="button" onclick="toggleSendSegment('${segmentId}')" aria-expanded="${expanded?'true':'false'}">
       <span class="send-segment-summary-icon">${eveIcon(isAll?'target':'participants',16)}</span>
       <span class="send-segment-summary-copy">
         <span class="send-segment-title-line"><b>${esc(name)}</b>${isAll?'<span class="send-default-pill">Default</span>':'<span class="send-custom-pill">Custom</span>'}</span>
         <small>${count} response${count===1?'':'s'} · target ${target} · ${summaryStatus}</small>
       </span>
       <span class="send-segment-mini-progress" aria-hidden="true"><span style="width:${progress.percent}%"></span></span>
       <span class="send-segment-chevron" aria-hidden="true">${expanded?'⌃':'⌄'}</span>
     </button>
     ${isAll?'':`<button class="send-segment-card-delete" type="button" onclick="removeStudySendSegment('${s.id}','${segmentId}')" aria-label="Delete ${esc(name)} segment" title="Delete segment">×</button>`}
   </div>
   ${expanded?`<div class="send-segment-card-body">
     <div class="send-segment-settings-heading"><span>SEGMENT SETTINGS</span><small>These settings apply only to ${esc(name)}.</small></div>
     <div class="send-segment-settings-grid">
       <section class="send-segment-setting-panel target-panel">
         <div class="send-segment-setting-title"><span class="setting-icon">${eveIcon('target',16)}</span><div><b>Response target</b><small>Set the recruitment goal for this segment.</small></div></div>
         <div class="send-segment-target-layout">
           <div class="field send-target-field"><label>Target responses</label><input class="input" type="number" min="1" step="1" value="${target}" onchange="setSendSegmentTarget('${s.id}','${segmentId}',this.value)"/><small>${progress.reached?'Target reached':`${progress.remaining} response${progress.remaining===1?'':'s'} remaining`}</small></div>
           <div class="segment-progress-detail"><div><span>Progress</span><b>${count} / ${target}</b></div><div class="target-progress-track" role="progressbar" aria-label="${esc(name)} response target" aria-valuemin="0" aria-valuemax="${target}" aria-valuenow="${Math.min(count,target)}"><span style="width:${progress.percent}%"></span></div></div>
         </div>
       </section>
       <section class="send-segment-setting-panel share-panel ${shareReady?'':'access-off'}">
         <div class="send-segment-setting-title share-title"><span class="setting-icon">↗</span><div><b>Participant access</b><small>${shareReady?(isAll?'Permanent general-purpose participant access.':'Responses using this access are attributed to this segment.'):'Configure this now; the participant access becomes available when the study is live.'}</small></div>${shareReady?`<div class="share-mode-toggle" aria-label="Share format"><span class="${!qrMode?'active':''}">Link</span><button type="button" class="switch ${qrMode?'on':''}" role="switch" aria-checked="${qrMode?'true':'false'}" aria-label="Show QR code instead of link" onclick="setSendShareMode('${qrMode?'link':'qr'}')"></button><span class="${qrMode?'active':''}">QR</span></div>`:''}</div>
         ${!shareReady?`<div class="send-access-offline"><span class="send-access-lock">○</span><div><b>Participant access is off</b><p>${esc(share.reason)}</p><small>Your segment name and response target are saved now. Nothing is lost when the study is turned off.</small></div></div>`:qrMode?`<div class="send-qr-view segment-qr-view"><div class="share-qr-frame">${qrSvgMarkup(url,{moduleSize:6,margin:4})}</div><div class="send-qr-copy"><h3>${esc(name)}</h3><p>Scan to open this segment's participant study.</p><div class="toolbar"><button class="btn primary" onclick="downloadSendQr('${s.id}','${segmentId}')">Download QR</button><button class="btn" onclick="openSendLink('${s.id}','${segmentId}')">Open ↗</button></div></div></div>`:`<div class="send-link-view segment-link-view"><label class="share-link-label" for="send-share-link-${segmentId}">Participant link</label><div class="share-link-field"><input id="send-share-link-${segmentId}" class="input" value="${esc(url)}" readonly/><button class="btn primary" onclick="copySendLink('${s.id}','${segmentId}')">Copy link</button></div><button class="text-btn send-open-link" onclick="openSendLink('${s.id}','${segmentId}')">Open participant link ↗</button></div>`}
       </section>
     </div>
   </div>`:''}
 </section>`
}
function directSharePanel(s,shareReady){
 const segments=activeSendSegments(s),currentVersion=latestPublishedVersion(s);
 if(state.sendExpandedSegmentId&&state.sendExpandedSegmentId!=='all'&&!segments.some(x=>x.id===state.sendExpandedSegmentId))state.sendExpandedSegmentId='all';
 const stateLabel=shareReady?`Live · v${s.version}`:s.status==='live'&&s.hasUnpublishedChanges?`Live · v${s.version} · changes pending`:currentVersion?`Off · v${s.version}`:'Draft';
 return `<section class="send-share-stack"><div class="send-share-heading standalone"><div><div class="eyebrow">AUDIENCES</div><h2>Segments</h2><p>Set up audiences, targets and sharing structure before or after the study goes live.</p></div><div class="send-segment-heading-actions"><span class="share-version-pill ${shareReady?'live':''}">${stateLabel}</span><button class="btn" onclick="createStudySendSegment('${s.id}')">+ New segment</button></div></div><div class="send-segment-card-list all-segment-cards">${sendSegmentCardMarkup(s,null)}${segments.map(seg=>sendSegmentCardMarkup(s,seg)).join('')}</div>${segments.length?'':`<div class="send-segments-hint"><span>＋</span><div><b>Add another audience when you need it</b><small>Configure custom audience targets now; participant links activate when the study goes live.</small></div></div>`}</section>`
}

function sendReadinessItems(s,{mailLoaded=true,mailConfigured=true}={}){
 const buildIssues=studyBuildIssues(s),settingsIssues=validateStudySettings(s),storage=resolvedStudyStorage(s),panel=panelSignupBlock(s),target=sendSegmentTarget(s,'all'),segments=activeSendSegments(s);
 const items=[
  {key:'build',label:'Study content',state:buildIssues.length?'attention':'ready',blocking:true,detail:buildIssues.length?`${buildIssues.length} Build issue${buildIssues.length===1?'':'s'}`:`${s.pages?.length||0} pages · ${s.blocks?.length||0} sections`,action:'build'},
  {key:'settings',label:'Study settings',state:settingsIssues.length?'attention':'ready',blocking:true,detail:settingsIssues.length?`${settingsIssues.length} setting${settingsIssues.length===1?'':'s'} need attention`:'Privacy, dates and storage selected',action:'settings'},
  {key:'audience',label:'Audience',state:target>0?'ready':'attention',blocking:true,detail:`All users target ${target}${segments.length?` · ${segments.length} custom segment${segments.length===1?'':'s'}`:''}`,action:'send'},
  {key:'storage',label:'Customer storage',state:storage.connected?'ready':'attention',blocking:false,detail:storage.connected?`${storage.provider} connected`:`${storage.provider} selected · connector not connected`,action:'storage'}
 ];
 if(panel)items.push({key:'email',label:'Panel email',state:mailLoaded?(mailConfigured?'ready':'attention'):'checking',blocking:true,detail:mailLoaded?(mailConfigured?'Microsoft 365 email ready':'Email setup required for Panel sign-up'):'Checking Microsoft 365 email…',action:'settings'});
 return items
}
function sendLaunchReadinessMarkup(s,{mailLoaded=true,mailConfigured=true,shareReady=false}={}){
 const items=sendReadinessItems(s,{mailLoaded,mailConfigured}),blockers=items.filter(i=>i.blocking&&i.state!=='ready'),ready=!blockers.length;
 const stateLabel=shareReady?'Live now':ready?'Ready to go live':`${blockers.length} blocker${blockers.length===1?'':'s'}`;
 const actionFor=item=>item.action==='build'?`navigate('/study/${s.id}/build')`:item.action==='settings'?`navigate('/study/${s.id}/settings')`:item.action==='storage'?`navigate('/storage')`:`void 0`;
 return `<section class="card launch-readiness ${shareReady?'live':ready?'ready':'needs'}"><div class="launch-readiness-head"><div><div class="eyebrow">LAUNCH READINESS</div><h3>${stateLabel}</h3><p>${shareReady?'Participant access is active. These checks show the current study setup.':ready?'Core checks are complete. Review the audience below, then go live when you are ready.':'Resolve the blocking checks before trying to go live.'}</p></div><span class="launch-readiness-score">${items.filter(i=>i.state==='ready').length}/${items.length}</span></div><div class="launch-readiness-grid">${items.map(item=>`<button type="button" class="launch-check ${item.state}" onclick="${actionFor(item)}"><span class="launch-check-mark">${item.state==='ready'?'✓':item.state==='checking'?'…':'!'}</span><div><b>${esc(item.label)}</b><small>${esc(item.detail)}</small></div>${item.action!=='send'?'<em>Open →</em>':''}</button>`).join('')}</div></section>`
}

function sendStudy(){
 const s=currentStudy();if(!s)return home();refreshDirty(s);if(!Array.isArray(s.sendSegments))s.sendSegments=[];
 const panel=panelSignupBlock(s);if(panel&&!globalEmailStatus.loaded&&!globalEmailStatus.loading)setTimeout(()=>loadGlobalEmailStatus(),0);
 const currentVersion=latestPublishedVersion(s),rs=researchResponses(currentVersion?studyResponses(s.id,currentVersion):[]),shareability=studyLinkShareability(s),shareReady=shareability.available,buildIssues=studyBuildIssues(s),settingsIssues=validateStudySettings(s),published=currentVersion?publishedStudy(s,currentVersion):null,start=startingInstant(published),close=closingInstant(published),now=Date.now(),isLive=s.status==='live';
 const scheduled=!!(shareReady&&start&&now<start),statusLabel=shareReady?(scheduled?'Scheduled':'Live'):isLive&&close&&now>=close?'Ended':currentVersion?'Off':'Draft';
 const scheduleSummary=shareReady?(scheduled?`Participant access opens ${formatScheduleInstant(start)}`:close?`Accepting responses · ends ${formatScheduleInstant(close)}`:`${rs.length} response${rs.length===1?'':'s'}`):currentVersion?'Participant access is turned off':'Audience setup is available now. Go live when the study is ready.';
 const liveActions=isLive?`${s.hasUnpublishedChanges?`<button class="btn primary" onclick="goLiveStudy('${s.id}')">Update live study</button>`:''}<button class="btn danger-outline" onclick="turnOffStudy('${s.id}')">Turn off</button>`:`<button class="btn primary" onclick="goLiveStudy('${s.id}')">Go live</button>`;
 return shell(`${studyFlow(s,'send')}<div class="content send-layout simplified-send"><section class="send-hero simplified"><div><div class="eyebrow">SEND</div><h2>Set up audiences and control when the study is live.</h2><p>Segments are independent of live status. Configure them first, then activate or turn off participant access whenever you need to.</p></div><div class="send-live-control"><div class="send-status ${shareReady?'live':currentVersion?'closed':''}"><span>${statusLabel}</span><b>${currentVersion?`Version ${s.version}`:'Not live yet'}</b><small>${scheduleSummary}</small></div><div class="send-live-actions">${liveActions}</div></div></section>${sendLaunchReadinessMarkup(s,{mailLoaded:!panel||globalEmailStatus.loaded,mailConfigured:!panel||globalEmailStatus.configured,shareReady})}${directSharePanel(s,shareReady)}</div>`,'Send study',`<button class="btn" onclick="navigate('/study/${s.id}/settings')">← Settings</button><button class="btn" onclick="navigate('/study/${s.id}/review')">Review →</button>`)
}


function participantIdentityRuntime(s){
 if(!s?.settings?.collectEmail)return'';
 return `<section class="participant-section participant-identity"><h3>About you</h3><label class="field"><span>Email ${s.settings.anonymous?'(optional)':''}</span><input class="input" type="email" name="participant_email" ${s.settings.anonymous?'':'required'} placeholder="you@example.com"></label>${s.settings.recontact?`<label class="choice consent-choice"><input type="checkbox" name="recontact_consent" value="yes"> I’m happy to be contacted about future research</label>`:''}</section>`
}
function previewCompletionMarkup(s,screenedOut=false){
 const title=screenedOut?'Participant screened out':'Preview complete';
 const message=screenedOut?`This participant would stop here and submit a screening response.`:(s.settings?.completionMessage||'Thanks for taking part. Your response has been recorded.');
 return `<section class="preview-completion-state" data-preview-completion ${screenedOut?'data-screenout-completion':''} hidden><div class="preview-completion-mark" aria-hidden="true">✓</div><div class="eyebrow">${screenedOut?'SCREEN-OUT':'END OF STUDY'}</div><h2>${esc(title)}</h2><p>${esc(message)}</p><button class="btn primary" type="button" data-preview-restart>Restart preview</button></section>`
}
function previewModal(s){
 s=previewStudySource(s);ensureStudyPages(s);const draftPage=currentPage();const active=s.pages.find(p=>p.id===draftPage?.id)||s.pages[0],full=state.previewScope==='study',pages=full?studyPages(s):[active].filter(Boolean),device=state.previewDevice==='mobile'?'mobile':'desktop';
 const pageMarkup=pages.map((p,localIndex)=>{
   const studyIndex=s.pages.findIndex(x=>x.id===p.id),isFirstStudyPage=studyIndex===0;
   const identity=isFirstStudyPage?participantIdentityRuntime(s):'';
   const nav=full?`<div class="participant-page-nav preview-page-nav">${localIndex?'<button class="btn" type="button" data-preview-back>← Back</button>':'<span></span>'}<span class="participant-page-count">${localIndex+1} / ${pages.length}</span>${localIndex<pages.length-1?'<button class="btn primary" type="button" data-preview-next>Continue →</button>':'<button class="btn primary" type="button" data-preview-complete>Complete study</button>'}</div>`:`<div class="participant-page-nav preview-page-nav preview-page-check"><span>Current page only</span><button class="btn primary" type="button" data-preview-check>Check page</button></div>`;
   return `<section class="participant-page-panel preview-study-page" ${full?`data-preview-page data-page-index="${localIndex}" ${localIndex?'hidden':''}`:''}><div class="participant-page-heading"><span>Page ${studyIndex+1} of ${s.pages.length}</span><h2>${esc(p.title||`Page ${studyIndex+1}`)}</h2></div>${identity}${pageBlocks(s,p.id).map(b=>participantBlockPreview(b)).join('')}${full?`<div class="preview-screenout-end" data-preview-screenout-end hidden><div><b>This participant would be screened out here.</b><span>The remaining study would not be shown.</span></div><button class="btn" type="button" data-preview-screenout-finish>Finish preview</button></div>`:''}${nav}</section>`
 }).join('');
 const progress=full&&pages.length>1?`<div class="participant-progress-meta preview-progress-meta"><span data-preview-page-label>Page 1 of ${pages.length}</span><span>Progress is shown exactly as participants see it</span></div><div class="participant-progress preview-progress" role="progressbar" aria-label="Preview progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(100/pages.length)}"><span data-preview-progress style="width:${Math.round(100/pages.length)}%"></span></div>`:'';
 const completion=full?`${previewCompletionMarkup(s,false)}${previewCompletionMarkup(s,true)}`:'';
 return `<div class="preview-wrap"><div class="preview preview-single"><button class="preview-close-button" type="button" aria-label="Close preview" title="Close preview" onclick="state.preview=false;render()">×</button><div class="preview-main"><div class="toolbar preview-header"><div><div class="eyebrow">PARTICIPANT PREVIEW</div><b>${esc(s.title)}</b><small class="preview-version-label">${state.previewVersion==='draft'?'Current draft':`Version ${state.previewVersion}`}</small></div><div class="preview-controls"><div class="segmented" aria-label="Preview scope"><button class="${state.previewScope==='page'?'active':''}" onclick="state.previewScope='page';render()">Current page</button><button class="${state.previewScope==='study'?'active':''}" onclick="state.previewScope='study';render()">Full study</button></div><div class="segmented preview-device-control" aria-label="Preview viewport"><button class="${device==='desktop'?'active':''}" onclick="state.previewDevice='desktop';render()">Desktop</button><button class="${device==='mobile'?'active':''}" onclick="state.previewDevice='mobile';render()">Mobile</button></div></div></div><div class="preview-mode-banner"><span>Preview mode</span><b>Interactions work normally</b><small>Responses and recordings are not submitted.</small></div><div class="participant-shell preview-participant-shell ${studyThemeClass(s)} ${device==='mobile'?'mobile-preview':''}"><header class="participant-top"><div class="brand participant-brand"><div class="brand-mark">E</div>Eve</div><div class="privacy-badge">Private research study · preview</div></header><main class="participant-runtime"><div class="participant-card">${progress}<div class="participant-study-title"><div class="eyebrow">RESEARCH STUDY</div><h1>${esc(s.title)}</h1></div>${pageMarkup}${completion}</div></main></div></div></div></div>`
}
function participantBlockPreview(b){return participantInteractive(b)}




async function relayHealth(){if(!/^https?:$/.test(location.protocol))return false;try{const r=await EveDeployment.relayFetch(RELAY_HEALTH,{cache:'no-store'},6000);return r.ok}catch{return false}}
async function refreshRelayStatus(showToast=true){const online=await relayHealth();state.relayOnline=online;render();if(showToast)toast(online?'Participant collection is available.':'Participant collection is temporarily unavailable.',2600,online?'success':'error');return online}
function relayVersionKey(s,version,create=false){const v=String(Number(version||s?.version||latestPublishedVersion(s)||1));if(!s)return null;s.relayVersionKeys=s.relayVersionKeys||{};if(!s.relayVersionKeys[v]&&create)s.relayVersionKeys[v]=newRelayKey();return s.relayVersionKeys[v]||((Number(v)===Number(s.version)&&s.relayKey)?s.relayKey:null)}
function prepareRelayCredentials(s,version){if(!s)return false;const key=relayVersionKey(s,version,true);s.relayKey=key;if(!s.relayAdminToken)s.relayAdminToken=newRelayKey();return !!(key&&s.relayAdminToken)}
function publicStudyUrl(s,params={}){const version=Number(params.v||s.version||latestPublishedVersion(s)||1),q=new URLSearchParams();q.set('k',relayVersionKey(s,version,false)||'');q.set('v',String(version));for(const [k,v] of Object.entries(params))if(v&&k!=='v')q.set(k,v);const base=EveDeployment.participantBaseUrl(state)||EveSetup.participantBaseUrl(state)||location.href.split('#')[0];return `${base.replace(/\/+$/,'')}#/s/${s.slug}?${q.toString()}`}
async function relayPublishStudy(s,snapshot){try{prepareRelayCredentials(s,snapshot.version);const versionKey=relayVersionKey(s,snapshot.version,true);if(!await relayHealth()){s.relayPublished=false;return false}const envelope=await encryptWithKey(snapshot.data,versionKey),participantHash=await capabilityProof(versionKey);const r=await EveDeployment.relayFetch(`/api/studies/${encodeURIComponent(s.slug)}`,{method:'PUT',headers:EveSetup.ownerHeaders(state,{'Content-Type':'application/json','X-ResearchOS-Admin':s.relayAdminToken||''}),body:JSON.stringify({envelope,adminToken:s.relayAdminToken,metadata:{studyId:s.id,version:snapshot.version,status:s.status,closeAtUtc:snapshot.data?.settings?.closeAtUtc||'',publishedAt:snapshot.publishedAt,participantHash}})});s.relayPublished=r.ok;return r.ok}catch(err){console.error('Relay publish failed',err);s.relayPublished=false;return false}}

async function relayUpdateLifecycle(s){if(!s?.relayPublished||!await relayHealth())return false;try{const r=await EveDeployment.relayFetch(`/api/studies/${encodeURIComponent(s.slug)}`,{method:'PATCH',headers:EveSetup.ownerHeaders(state,{'Content-Type':'application/json','X-ResearchOS-Admin':s.relayAdminToken||''}),body:JSON.stringify({status:s.status,closeAtUtc:publishedStudy(s,s.version)?.settings?.closeAtUtc||'',version:s.version})});return r.ok}catch{return false}}
async function relayStudyStatus(s){if(!s?.slug||!s?.relayAdminToken||!/^https?:$/.test(location.protocol))return null;try{const r=await EveDeployment.relayFetch(`/api/studies/${encodeURIComponent(s.slug)}/status`,{cache:'no-store',headers:EveSetup.ownerHeaders(state,{'X-ResearchOS-Admin':s.relayAdminToken||''})},7000);if(!r.ok)return null;return r.json().catch(()=>null)}catch{return null}}
async function hydrateParticipantFromRelay(){state.remoteParticipantStudy=null;state.remoteParticipantBase=null;state.remoteParticipantError='';const local=state.studies.find(x=>x.slug===state.participantSlug);if(state.participantRelayKey&&/^https?:$/.test(location.protocol)){try{const proof=await capabilityProof(state.participantRelayKey),r=await EveDeployment.relayFetch(`/api/studies/${encodeURIComponent(state.participantSlug)}${state.participantRouteVersion?`?version=${encodeURIComponent(state.participantRouteVersion)}`:''}`,{cache:'no-store',headers:{'X-Eve-Participant':proof}});if(r.status===404){state.remoteParticipantError='This study could not be found.';return}if(r.status===410){const data=await r.json().catch(()=>({}));state.remoteParticipantError=data.reason||'This study is closed.';return}if(!r.ok)throw new Error(`Relay returned ${r.status}`);const payload=await r.json();const data=await decryptWithKey(payload.envelope,state.participantRelayKey);const snap={version:Number(payload.metadata?.version||data.version||1),publishedAt:Number(payload.metadata?.publishedAt||Date.now()),data};state.remoteParticipantStudy=data;state.remoteParticipantBase={id:data.id,slug:state.participantSlug,status:payload.metadata?.status||'live',version:snap.version,publishedSnapshot:snap,publishedVersions:{[String(snap.version)]:snap},relayKey:state.participantRelayKey,relayVersionKeys:{[String(snap.version)]:state.participantRelayKey},relayPublished:true};return}catch(err){console.error('Could not load remote study',err);if(!local){state.remoteParticipantError=err?.code==='EVE_TIMEOUT'?'Eve could not reach the study service. Check your connection and try again.':'This study could not be loaded. Check that the participant link is complete.';return}}}if(local&&publishedStudy(local)){state.remoteParticipantBase=local;return}state.remoteParticipantError=state.participantRelayKey?'This study could not be loaded. Please check the participant link and try again.':'This participant link is incomplete.'}

const EveParticipantDelivery=typeof module!=='undefined'&&module.exports?require('./eve-participant-delivery.js'):globalThis.EveParticipantDelivery;
async function participantRelayPost(path,payload,timeout=20000,participantKey=''){const proof=participantKey?await capabilityProof(participantKey):'',headers={'Content-Type':'application/json'};if(proof)headers['X-Eve-Participant']=proof;const r=await EveDeployment.relayFetch(path,{method:'POST',headers,body:JSON.stringify(payload)},timeout),data=await r.json().catch(()=>({}));if(!r.ok){const err=Object.assign(new Error(data.reason||data.message||`Participant delivery failed (${r.status})`),{status:r.status,retryable:r.status===408||r.status===425||r.status===429||r.status>=500});throw err}return data}
const participantDelivery=EveParticipantDelivery.create({getRelayKey:(base,response)=>state.participantRelayKey||relayVersionKey(base,response?.studyVersion,false)||base?.relayKey,getInviteToken:()=>state.participantInviteToken||null,encryptResponse:encryptWithKey,encryptRecording:encryptRecordingBlobWithKey,postResponse:(base,payload)=>participantRelayPost(`/api/studies/${encodeURIComponent(base.slug)}/responses`,payload,20000,state.participantRelayKey||base?.relayKey||''),postRecording:(base,payload)=>participantRelayPost(`/api/studies/${encodeURIComponent(base.slug)}/recordings`,payload,120000,state.participantRelayKey||base?.relayKey||''),saveLocalRecording,saveResponseRecord,localStudyExists:id=>state.studies.some(x=>x.id===id),notifyPanel:notifyPanelAfterCompletion,sessionGet:safeSessionGet,sessionSet:safeSessionSet,sessionRemove:safeSessionRemove,uid});
async function fetchRelayRecording(study,response,recordingId){const r=await EveDeployment.relayFetch(`/api/studies/${encodeURIComponent(study.slug)}/recordings/${encodeURIComponent(recordingId)}`,{cache:'no-store',headers:EveSetup.ownerHeaders(state,{'X-ResearchOS-Admin':study.relayAdminToken||''})},120000);if(!r.ok){const x=await r.json().catch(()=>({}));throw new Error(x.reason||'Recording could not be loaded.');}const payload=await r.json(),key=relayVersionKey(study,response.studyVersion,false)||study.relayKey;if(!key)throw new Error('The local key for this study version is unavailable.');return decryptRecordingBlobWithKey(payload.envelope,key)}
async function syncRelayResponsesForStudy(s,quiet=false){if(!s?.relayPublished||!s?.relayAdminToken||!await relayHealth())return false;if(s._relaySyncing)return false;s._relaySyncing=true;try{let added=0,offset=0,pages=0,hasMore=true;while(hasMore&&pages<100){const r=await EveDeployment.relayFetch(`/api/studies/${encodeURIComponent(s.slug)}/responses?offset=${offset}&limit=250`,{cache:'no-store',headers:EveSetup.ownerHeaders(state,{'X-ResearchOS-Admin':s.relayAdminToken||''})});if(!r.ok)return false;const payload=await r.json();for(const item of payload.responses||[]){if(state.responses.some(x=>x.id===item.id))continue;try{const version=Number(item.routing?.version||0)||null,key=relayVersionKey(s,version,false)||s.relayKey;if(!key)throw new Error(`Missing local key for published version ${version||'unknown'}`);const response=await decryptWithKey(item.envelope,key);response.serverReceivedAt=response.serverReceivedAt||item.receivedAt;response.submittedAt=item.receivedAt||response.submittedAt;await saveResponseRecord(response);added++}catch(e){console.warn('Unreadable relay response',item.id,e)}}offset=Number(payload.nextOffset||offset+(payload.responses||[]).length);hasMore=!!payload.hasMore;pages++}if(added&&!quiet){toast(`${added} new response${added===1?'':'s'} synced`);render()}return true}finally{s._relaySyncing=false}}

async function registerCampaignInvitations(s,c,people){if(!s?.relayPublished||!people?.length||!await relayHealth())return [];const invitations=people.map(p=>({token:newRelayKey(),campaignId:c.id,segmentId:c.segmentId,email:p.email}));const wire=[];for(const inv of invitations){const digest=await crypto.subtle.digest('SHA-256',encoder.encode(inv.email.toLowerCase()));wire.push({token:inv.token,campaignId:inv.campaignId,segmentId:inv.segmentId,version:Number(c.studyVersion||s.version),emailHash:bytesToB64Url(new Uint8Array(digest))})}const r=await EveDeployment.relayFetch(`/api/studies/${encodeURIComponent(s.slug)}/invitations`,{method:'POST',headers:EveSetup.ownerHeaders(state,{'Content-Type':'application/json','X-ResearchOS-Admin':s.relayAdminToken||''}),body:JSON.stringify({invitations:wire})});if(!r.ok)throw new Error('Could not register participant invitations');return invitations}


function panelSignupBlock(s){return (s?.blocks||[]).find(b=>b.type==='panelSignup')||null}
async function preparePanelStudyRegistration(s,version){
 const signup=panelSignupBlock(s),payload={studyId:s.id,studyTitle:s.title,studyVersion:version,panelSignup:signup?{blockId:signup.id,termsEnabled:!!signup.panelTermsEnabled,terms:signup.panelTermsEnabled?richPlainText(signup.panelTerms||''):'',consentLabel:signup.panelConsentLabel||'',welcomeSubject:signup.panelWelcomeSubject||'',welcomeMessage:signup.panelWelcomeMessage||''}:null};
 try{
   const r=await eveFetch('/api/panel/register-study',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)},12000),data=await r.json().catch(()=>({}));
   if(!r.ok)throw Object.assign(new Error(data.message||data.error||`Panel registration HTTP ${r.status}`),{status:r.status,data});
   s.panelStudyToken=String(data.completionToken||'');return data
 }catch(err){
   s.panelStudyToken='';
   if(signup)throw err;
   console.warn('Panel participation registration unavailable for this study',err);return null
 }
}
async function notifyPanelAfterCompletion(base,s,response){
 if(response?.screenedOut||!s?.panelStudyToken)return null;
 const signup=(s.blocks||[]).find(b=>b.type==='panelSignup'),answer=signup?response.answers?.[signup.id]?.value:null,joined=!!answer?.joined,panelEmail=String(answer?.email||response.participant?.email||'').trim().toLowerCase();
 if(joined){
   try{
     const r=await eveFetch('/api/panel/join',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:s.panelStudyToken,email:panelEmail,responseId:response.id,completedAt:response.submittedAt})},15000),data=await r.json().catch(()=>({}));
     if(!r.ok)throw new Error(data.message||data.error||`Panel join HTTP ${r.status}`);
     return data.alreadyMember?{joined:true,notice:'You are already a member of the research panel. This study has been added to your panel participation history.'}:{joined:true,notice:'You have joined the research panel. Check your email for confirmation and a link you can use to leave at any time.'}
   }catch(err){console.error('Panel sign-up failed after response submission',err);return {joined:false,error:true,notice:'Your study response was saved, but we could not complete your panel sign-up. Please contact the research team if you still want to join.'}}
 }
 if(panelEmail){
   try{await eveFetch('/api/panel/participation',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:s.panelStudyToken,email:panelEmail,responseId:response.id,completedAt:response.submittedAt})},10000)}catch(err){console.warn('Panel participation history update failed',err)}
 }
 return null
}

const EveLifecycle=typeof module!=='undefined'&&module.exports?require('./eve-study-lifecycle.js'):globalThis.EveStudyLifecycle;
