function safeSessionSet(key,value){try{sessionStorage.setItem(key,value);return true}catch{return false}}
function safeSessionRemove(key){try{sessionStorage.removeItem(key)}catch{}}
function participantSessionSuffix(base,s){const invite=state.participantInviteToken||'open';return `${base?.slug||base?.id||'study'}:${Number(s?.version||base?.version||1)}:${state.participantCampaignId||'direct'}:${invite}`}
