function participantRouteCompletionReceipt(){if(!state.participantSlug)return null;const base={slug:state.participantSlug,version:state.participantRouteVersion||1},s={version:state.participantRouteVersion||1};return participantCompletionReceipt(base,s)}
function participantCompletionContent(s,relayMode,receipt=null){return `<div class="completion"><div class="completion-icon">✓</div><div class="eyebrow">RESPONSE RECORDED</div><h1>Thank you</h1><p>${esc(receipt?.message||s.settings.completionMessage||'Your response has been recorded.')}</p>${receipt?.panelNotice?`<div class="panel-completion-notice ${receipt.panelError?'warning':''}">${esc(receipt.panelNotice)}</div>`:''}<div class="privacy-card"><span aria-hidden="true">${eveIcon('checkSquare',18)}</span><span>Your response has been securely recorded and is only available to the research team.</span></div>${receipt?.completedAt?`<small class="muted">Completed ${new Date(receipt.completedAt).toLocaleString()}</small>`:''}</div>`}
function participantCompletionMarkup(s,relayMode,receipt=null){return `<div class="participant-shell ${studyThemeClass(s,receipt)}"><header class="participant-top"><div class="brand participant-brand"><div class="brand-mark">E</div>Eve</div><div class="privacy-badge">Private research study · v${s.version}</div></header><main class="participant-runtime">${participantCompletionContent(s,relayMode,receipt)}</main></div>`}
function collectParticipantDraft(form){if(!form)return null;const fd=new FormData(form),names=[...new Set([...form.elements].map(el=>el.name).filter(Boolean))],values={};for(const name of names)values[name]=fd.getAll(name).map(v=>String(v));const pages=[...form.querySelectorAll('[data-participant-page]')],pageIndex=Math.max(0,pages.findIndex(p=>!p.hidden));return {savedAt:Date.now(),started:Number(form.dataset.started)||Date.now(),elapsedMs:Number(form.dataset.elapsedBefore||0)+Math.max(0,performance.now()-Number(form.dataset.startedPerf||performance.now())),pageIndex,values,screenedOut:form.dataset.screenedOut==='true',responseId:String(form.dataset.responseId||'')}}
function setParticipantSessionStatus(stateName='saved',label='Saved in this tab',detail='Your progress stays on this device while this tab is open.'){const el=document.getElementById('p-session-status');if(!el)return;el.dataset.state=stateName;const labelEl=el.querySelector('[data-session-label]'),detailEl=el.querySelector('[data-session-detail]');if(labelEl)labelEl.textContent=label;if(detailEl)detailEl.textContent=detail}
function saveParticipantDraftNow(form=document.getElementById('participant-form')){if(!form?.dataset.sessionKey)return;const draft=collectParticipantDraft(form);if(!draft)return;const stored=safeSessionSet(form.dataset.sessionKey,JSON.stringify(draft));if(stored)setParticipantSessionStatus('saved','Saved in this tab',`Saved ${new Date(draft.savedAt).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`);else setParticipantSessionStatus('error','Progress could not be saved','Keep this tab open and avoid refreshing until you complete the study.')}
function scheduleParticipantDraftSave(form=document.getElementById('participant-form')){clearTimeout(participantDraftTimer);setParticipantSessionStatus('saving','Saving…','Keeping your progress in this tab');participantDraftTimer=setTimeout(()=>{participantDraftTimer=null;saveParticipantDraftNow(form)},120)}
function flushParticipantDraft(){if(participantDraftTimer){clearTimeout(participantDraftTimer);participantDraftTimer=null}saveParticipantDraftNow()}
function restoreParticipantDraftValues(form){if(!form?.dataset.sessionKey)return null;const raw=safeSessionGet(form.dataset.sessionKey);if(!raw)return null;let draft;try{draft=JSON.parse(raw)}catch{return null}for(const el of form.elements){if(!el.name)continue;const values=draft.values?.[el.name]||[];if(el.type==='radio'||el.type==='checkbox')el.checked=values.includes(String(el.value));else if(values.length)el.value=values[0]}form.dataset.screenedOut=draft.screenedOut?'true':'false';form.dataset.responseId=String(draft.responseId||'');form.dataset.started=String(Number(draft.started)||Date.now());form.dataset.elapsedBefore=String(Math.max(0,Number(draft.elapsedMs)||0));form.dataset.startedPerf=String(performance.now());return draft}
function clearParticipantSession(base,s){const draftKey=participantDraftKey(base,s);safeSessionRemove(draftKey);clearTimeout(participantDraftTimer)}

function participantRuntime(){
 const base=state.studies.find(x=>x.slug===state.participantSlug)||state.remoteParticipantBase,routeReceipt=participantRouteCompletionReceipt();
 if(routeReceipt&&!base)return participantCompletionMarkup({version:state.participantRouteVersion||1,settings:{completionMessage:routeReceipt.message||'Your response has been recorded.'}},!!state.participantRelayKey,routeReceipt);
 if(!base&&state.remoteParticipantError)return `<div class="participant-shell"><div class="participant-runtime"><div class="brand participant-brand"><div class="brand-mark">E</div>Eve</div><div class="card not-found"><h2>Study unavailable</h2><p>${esc(state.remoteParticipantError)}</p></div></div></div>`;
 const availability=studyAvailability(base),receiptBeforeAvailability=routeReceipt||participantCompletionReceipt(base,{version:base.version});if(receiptBeforeAvailability&&!availability.available)return participantCompletionMarkup({version:base.version||state.participantRouteVersion||1,settings:{completionMessage:receiptBeforeAvailability.message||'Your response has been recorded.'}},!!state.participantRelayKey,receiptBeforeAvailability);if(!availability.available)return `<div class="participant-shell"><div class="participant-runtime"><div class="brand participant-brand"><div class="brand-mark">E</div>Eve</div><div class="card not-found"><h2>Study unavailable</h2><p>${esc(availability.reason)}</p></div></div></div>`;
 const s=publishedStudy(base,base.version);if(!s)return `<div class="participant-shell"><div class="participant-runtime"><div class="card not-found"><h2>Study unavailable</h2><p>The live study definition is unavailable.</p></div></div></div>`;const deploymentIssues=EveCapabilities.studyIssues(s);if(deploymentIssues.length)return `<div class="participant-shell ${studyThemeClass(s)}"><div class="participant-runtime"><div class="card not-found"><h2>Study unavailable</h2><p>This study uses a capability that is not available in the current Eve deployment.</p><small>${esc(deploymentIssues[0])}</small></div></div></div>`;
 const pages=studyPages(s),relay=!!(state.participantRelayKey&&base.relayPublished),receipt=participantCompletionReceipt(base,s);if(receipt)return participantCompletionMarkup(s,relay,receipt);
 const sessionKey=participantDraftKey(base,s);
 return `<div class="participant-shell ${studyThemeClass(s)}"><header class="participant-top"><div class="brand participant-brand"><div class="brand-mark">E</div>Eve</div><div class="privacy-badge">Private research study · v${s.version}</div></header><main class="participant-runtime"><div class="participant-session-status" id="p-session-status" data-state="saved"><span class="participant-session-dot" aria-hidden="true"></span><div><b data-session-label>Saved in this tab</b><small data-session-detail>Your progress stays on this device while this tab is open.</small></div></div><div class="participant-progress-meta"><span id="p-progress-label">Page 1 of ${pages.length}</span><span>Complete the study when you are ready</span></div><div class="participant-progress" role="progressbar" aria-label="Study progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pages.length?Math.round(100/pages.length):0}"><span id="p-progress" style="width:${pages.length?Math.round(100/pages.length):0}%"></span></div><form id="participant-form" novalidate data-session-key="${esc(sessionKey)}" data-started="${Date.now()}" data-started-perf="${performance.now()}" data-elapsed-before="0" onsubmit="submitParticipant(event,'${base.id}')"><div class="participant-study-title"><div class="eyebrow">RESEARCH STUDY</div><h1>${esc(s.title)}</h1></div>${pages.map((page,i)=>participantPageRuntime(s,page,i,pages.length)).join('')}</form></main></div>`}

function participantPageRuntime(s,page,index,total){const blocks=pageBlocks(s,page.id);const about=index===0?participantIdentityRuntime(s):'';return `<section class="participant-page-panel" data-participant-page data-page-index="${index}" ${index?'hidden':''}><div class="participant-page-heading"><span>Page ${index+1} of ${total}</span><h2>${esc(page.title||`Page ${index+1}`)}</h2></div>${about}${blocks.map(participantInteractive).join('')}<div class="participant-page-nav">${index?'<button class="btn" type="button" data-page-back>← Back</button>':'<span></span>'}<span class="participant-page-count">${index+1} / ${total}</span>${index<total-1?'<button class="btn primary" type="button" data-page-next>Continue →</button>':'<button class="btn primary participant-submit" type="submit">Complete study</button>'}<button class="btn primary screenout-submit" type="submit" data-screenout-submit hidden>Submit screening response</button></div>${index===total-1?'<p class="participant-privacy">Your response is kept private and is only available to the research team.</p>':''}</section>`}

function participantInteractive(b){
 if(b.type==='intro')return `<section class="participant-section"><h2>${esc(b.title)}</h2>${richParticipantText(b,'body',b.body||'','participant-copy')}</section>`;
 if(b.type==='consent'){const confirmations=consentConfirmations(b);return `<section class="participant-section consent-runtime" data-consent-block="${b.id}"><h2>${esc(b.title)}</h2>${richParticipantText(b,'body',b.body||'','participant-copy')}${confirmations.length?`<fieldset class="consent-confirmation-list"><legend class="sr-only">Required consent confirmations</legend>${confirmations.map(item=>`<label class="choice consent-choice"><input required type="checkbox" name="${b.id}" value="${esc(item.id)}"><span>${esc(item.text)} <span class="required" aria-hidden="true">*</span></span></label>`).join('')}<small class="consent-required-hint">All confirmations are required to continue.</small></fieldset>`:''}</section>`}
 if(b.type==='panelSignup')return `<section class="participant-section panel-signup-runtime" data-panel-signup="${b.id}"><div class="panel-signup-runtime-head"><span aria-hidden="true">${eveIcon('participants',20)}</span><div><h3>${esc(b.title||'Join our research panel')}</h3>${richParticipantText(b,'panelIntro',b.panelIntro||'Join our participant panel to hear about future research opportunities.','participant-copy')}</div></div><label class="field"><span>Email address</span><input class="input" type="email" inputmode="email" autocomplete="email" name="${b.id}__panel_email" placeholder="you@example.com"><small class="field-hint">We only use this for panel membership and future research contact.</small></label>${b.panelTermsEnabled?`<div class="panel-signup-terms"><div class="section-label">PANEL TERMS</div>${richParticipantText(b,'panelTerms',b.panelTerms||'','participant-copy')}</div>`:''}<label class="choice consent-choice panel-signup-consent"><input type="checkbox" name="${b.id}" value="yes"><span>${esc(b.panelConsentLabel||'I agree to join the research participant panel.')}</span></label><small class="muted">Joining is optional. You can leave the panel at any time using the link in your welcome email.</small></section>`;
 if(b.type==='question')return `<section class="participant-section choice-runtime">${richParticipantText(b,'question',b.question||'','participant-question',b.required)}${(b.options||[]).map(o=>`<label class="choice"><input ${b.required?'required':''} type="radio" name="${b.id}" value="${esc(o)}"> ${esc(o)}</label>`).join('')}</section>`;
 if(b.type==='preference')return `<section class="participant-section preference-runtime">${richParticipantText(b,'question',b.question||'','participant-question',b.required)}<div class="preference-options">${(b.options||[]).map(o=>`<label class="preference-card"><input ${b.required?'required':''} type="radio" name="${b.id}" value="${esc(o)}"><span>${esc(o)}</span><i>Choose</i></label>`).join('')}</div></section>`;
 if(b.type==='screener')return `<section class="participant-section screener-runtime" data-screener data-screenout="${esc(b.screenOut||'')}">${richParticipantText(b,'question',b.question||'','participant-question',b.required)}${(b.options||[]).map(o=>`<label class="choice"><input ${b.required?'required':''} type="radio" name="${b.id}" value="${esc(o)}"> ${esc(o)}</label>`).join('')}<div class="screenout-note" hidden>Thanks — you don't need to complete the rest of this study.</div></section>`;
 if(b.type==='multiChoice')return `<section class="participant-section multi-choice-runtime" data-multi-choice data-required="${b.required?'true':'false'}">${richParticipantText(b,'question',b.question||'','participant-question',b.required)}${(b.options||[]).map(o=>`<label class="choice"><input type="checkbox" name="${b.id}" value="${esc(o)}"> ${esc(o)}</label>`).join('')}</section>`;
 if(b.type==='scale')return ratingScaleRuntime(b);
 if(b.type==='matrix')return matrixRuntime(b);
 if(b.type==='shortText'){const max=Math.max(0,Number(b.maxLength)||0);return `<section class="participant-section short-text-runtime">${richParticipantText(b,'question',b.question||'','participant-question',b.required)}<input class="input participant-short-text" type="text" name="${b.id}" ${b.required?'required':''} ${max?`maxlength="${max}" data-short-text-max="${max}"`:''} placeholder="${esc(b.placeholder||'Type your answer…')}">${max?`<small class="field-hint participant-char-count" data-char-count>0 / ${max} characters</small>`:''}</section>`}
 if(b.type==='number'){const min=String(b.min??'').trim(),max=String(b.max??'').trim();return `<section class="participant-section number-runtime">${richParticipantText(b,'question',b.question||'','participant-question',b.required)}<div class="number-response-wrap"><input class="input participant-number" type="number" step="any" name="${b.id}" ${b.required?'required':''} ${min!==''?`min="${esc(min)}"`:''} ${max!==''?`max="${esc(max)}"`:''} inputmode="decimal">${b.unit?`<span>${esc(b.unit)}</span>`:''}</div></section>`}
 if(b.type==='date')return `<section class="participant-section date-runtime">${richParticipantText(b,'question',b.question||'','participant-question',b.required)}<input class="input participant-date" type="date" name="${b.id}" ${b.required?'required':''}></section>`;
 if(b.type==='openText')return `<section class="participant-section open-text-runtime">${richParticipantText(b,'question',b.question||'','participant-question',b.required)}<textarea class="textarea" name="${b.id}" ${b.required?'required':''} placeholder="Type your answer…"></textarea></section>`;
 if(b.type==='ranking')return rankingRuntime(b);
 if(b.type==='cardSort')return cardSortRuntime(b);
 if(b.type==='treeTest')return treeRuntime(b);
 if(b.type==='highlighter')return highlighterRuntime(b);
 if(b.type==='recording')return recordingRuntime(b);
 if(b.type==='navigationTask')return navigationTaskRuntime(b);
 return'';
}
function recordingRuntime(b){const mode=b.recordingMode==='video'?'video':'audio',mins=Math.max(.25,Math.min(15,Number(b.recordingTimeLimitMinutes)||2)),seconds=Math.round(mins*60);return `<section class="participant-section recording-runtime" data-recording="${b.id}" data-recording-mode="${mode}" data-recording-limit="${seconds}" data-required="${b.required?'true':'false'}">${richParticipantText(b,'prompt',b.prompt||'Tell us what you are thinking.','participant-question',b.required)}<div class="recording-permission-note"><span aria-hidden="true">${mode==='video'?'◉':'◍'}</span><div><b>${mode==='video'?'Camera and microphone':'Microphone'} permission</b><small>Eve only starts recording after you press Start recording. You can preview and re-record before submitting.</small></div></div><div class="recording-live-shell" data-recording-live-shell ${mode==='video'?'':'data-audio-only="true"'}><video data-recording-live muted playsinline hidden></video><div class="recording-audio-visual" data-recording-audio-visual><span></span><span></span><span></span><span></span><span></span></div><div class="recording-timer"><strong data-recording-time>0:00</strong><span>/ ${fmtDuration(seconds)} max</span></div></div><div class="recording-controls"><button type="button" class="btn primary" data-recording-start>Start recording</button><button type="button" class="btn danger-outline" data-recording-stop disabled>Stop</button><button type="button" class="btn subtle" data-recording-reset hidden>Re-record</button></div><div class="recording-status" data-recording-status aria-live="polite">Not recorded yet.</div><div class="recording-playback" data-recording-playback hidden></div><small class="muted recording-refresh-note">If you refresh this page before submitting, you will need to record this answer again.</small><input type="hidden" name="${b.id}" data-recording-value></section>`}
function highlighterRuntime(b){const meanings=highlighterMeanings(b),first=meanings[0];return `<section class="participant-section highlighter-runtime" data-highlighter="${b.id}" data-required="${b.required?'true':'false'}"><div class="highlighter-task-head"><div><h3>${esc(b.title||'Highlighter task')} ${b.required?'<span class="required">*</span>':''}</h3>${richParticipantText(b,'instructions',b.instructions||'Highlight the areas that stand out to you.','participant-copy')}</div><span class="highlighter-count" data-highlighter-count>0 highlights</span></div>${b.imageData?`<div class="highlighter-participant-tools"><div class="highlighter-meaning-picker" role="radiogroup" aria-label="Choose what your highlight means">${meanings.map((meaning,i)=>`<button type="button" class="highlighter-meaning-choice ${i===0?'active':''}" role="radio" aria-checked="${i===0?'true':'false'}" data-highlighter-meaning="${esc(meaning.id)}" data-highlighter-label="${esc(meaning.label)}" data-highlighter-color="${esc(meaning.color)}" style="--meaning-color:${meaning.color}"><span class="highlighter-meaning-swatch"></span><b>${esc(meaning.label)}</b></button>`).join('')}</div><button type="button" class="highlighter-touch-mode" data-highlighter-touch-mode aria-pressed="false"><span aria-hidden="true">✎</span><b>Highlight image</b><small>Tap to draw</small></button></div><div class="highlighter-stage" data-highlighter-stage aria-label="Interactive image highlighter" style="--active-highlight:${first.color};--active-highlight-fill:${highlighterAlpha(first.color,'34')}"><img src="${esc(b.imageData)}" alt="${esc(b.imageAlt||b.title||'Research image')}" draggable="false"><div class="highlighter-marks" data-highlighter-marks></div><div class="highlighter-first-hint" data-highlighter-hint><span data-highlighter-hint-text>Drag to highlight</span></div></div><div class="highlighter-toolbar"><span data-highlighter-help>Draw a box around each area you want to mark.</span><div><button type="button" class="btn subtle" data-highlighter-undo disabled>Undo</button><button type="button" class="btn subtle" data-highlighter-clear disabled>Clear all</button></div></div>`:'<div class="highlighter-missing">Image unavailable for this task.</div>'}<input type="hidden" name="${b.id}" data-highlighter-value></section>`}
function navigationTaskRuntime(b){
 const timeout=Math.max(0,Number(b.timeoutMinutes)||0),recordingModes=navigationRecordingModes(b),recordingEnabled=recordingModes.length>0,recordingLimit=navigationRecordingLimitSeconds(b);
 const recordingPanel=recordingEnabled?`<div class="navigation-recording-runtime" data-nav-recording-panel><div class="recording-permission-note"><span aria-hidden="true">${eveIcon('mic',16)}</span><div><b>${esc(recordingModes.map(navigationRecordingLabel).join(' + '))}</b><small>Select Start recording. Eve will request ${esc(navigationRecordingPermissionsLabel(recordingModes).toLowerCase())} access and start every enabled capture before Open task becomes available.</small></div></div><div class="navigation-recording-selected">${recordingModes.map(mode=>`<span>${eveIcon(mode==='audio'?'mic':mode==='video'?'video':'screen',14)} ${esc(navigationRecordingLabel(mode))}</span>`).join('')}</div><div class="navigation-recording-setup"><button type="button" class="btn primary-soft" data-nav-recording-prepare>Start recording</button><div data-nav-recording-status aria-live="polite">Recording not started yet.</div></div><div class="navigation-recording-live" data-nav-recording-live hidden></div><div class="navigation-recording-playback" data-nav-recording-playback hidden></div><small class="muted">All enabled recordings stop with task completion${b.timeoutEnabled?' or timeout':''}. ${!b.timeoutEnabled?'A 15-minute recording safety limit applies.':''}</small></div>`:'';
 return `<section class="participant-section navigation-task-runtime" data-navigation-task="${b.id}" data-required="${b.required?'true':'false'}" data-start-page="${esc(b.startPage||'')}" data-success-page="${esc(b.successPage||'')}" data-instructions="${esc(b.instructions||'Open the task and return here when you are finished.')}" data-timeout-seconds="${b.timeoutEnabled?timeout*60:0}" data-nav-recording-modes="${esc(recordingModes.join(','))}" data-nav-recording-limit="${recordingLimit}"><div class="navigation-task-heading"><span class="navigation-task-icon" aria-hidden="true">↗</span><div><h3>${esc(b.title||'Navigation task')} ${b.required?'<span class="required">*</span>':''}</h3>${richParticipantText(b,'instructions',b.instructions||'Open the task and return here when you are finished.','participant-copy')}</div></div>${recordingPanel}<div class="navigation-task-actions"><button type="button" class="btn primary" data-nav-start ${recordingEnabled?'disabled':''}>${recordingEnabled?'Open task ↗':'Open start page ↗'}</button><button type="button" class="btn" data-nav-complete disabled>I reached the destination</button></div><div class="navigation-task-status" data-nav-status>${b.timeoutEnabled?`You will have ${timeout} minute${timeout===1?'':'s'} once you start.`:'No time limit.'}</div><div class="navigation-extension-state" data-nav-extension-state>${state.navExtensionAvailable?'Eve browser overlay connected':'Browser overlay not detected · manual completion remains available'}</div><input type="hidden" name="${b.id}" data-nav-value><input type="hidden" name="${b.id}__recording" data-nav-recording-value></section>`
}
function ratingScaleRuntime(b){
 const points=Math.max(2,Number(b.points)||5),low=b.lowLabel||'Not at all',high=b.highLabel||'Extremely';
 return `<section class="participant-section rating-scale-runtime" data-rating-scale="${b.id}" data-required="${b.required?'true':'false'}">${richParticipantText(b,'question',b.question||'','participant-question',b.required)}<div class="rating-scale-scroll"><div class="rating-scale" style="--scale-points:${points}" role="radiogroup" aria-label="${esc(b.question)}">${Array.from({length:points},(_,i)=>`<button type="button" class="rating-scale-choice" role="radio" aria-checked="false" tabindex="${i===0?'0':'-1'}" data-scale-value="${i+1}" aria-label="${i+1} of ${points}"><span>${i+1}</span></button>`).join('')}</div></div><div class="scale-labels"><span>${esc(low)}</span><span>${esc(high)}</span></div><input type="hidden" name="${b.id}" data-scale-input></section>`
}

function matrixRuntime(b){const points=Math.max(2,Number(b.points)||5),rows=(b.rows||[]);return `<section class="participant-section matrix-runtime" data-matrix="${b.id}" data-required="${b.required?'true':'false'}" data-row-count="${rows.length}">${richParticipantText(b,'question',b.question||'','participant-question',b.required)}<div class="matrix-scale-labels"><span>${esc(b.lowLabel||'Strongly disagree')}</span><span>${esc(b.highLabel||'Strongly agree')}</span></div><div class="matrix-grid">${rows.map((row,ri)=>`<fieldset class="matrix-row"><legend>${esc(row)}</legend><div class="matrix-points" style="--matrix-points:${points}">${Array.from({length:points},(_,i)=>`<label><input type="radio" name="${b.id}__${ri}" value="${i+1}"><span>${i+1}</span></label>`).join('')}</div></fieldset>`).join('')}</div><input type="hidden" name="${b.id}" data-matrix-value></section>`}
function rankingRuntime(b){return `<section class="participant-section ranking-runtime" data-ranking="${b.id}" data-required="${b.required?'true':'false'}">${richParticipantText(b,'question',b.question||'','participant-question',b.required)}<p class="muted">Drag items into order, or use the arrow buttons, then confirm your ranking.</p><div class="ranking-list" data-ranking-list>${(b.options||[]).map((o,i)=>`<div class="ranking-item" draggable="true" data-ranking-item data-value="${esc(o)}"><span class="ranking-grip" aria-hidden="true">⋮⋮</span><b class="ranking-position">${i+1}</b><span class="ranking-label">${esc(o)}</span><span class="ranking-controls"><button type="button" class="mini-reorder-btn" data-ranking-up aria-label="Move ${esc(o)} up">↑</button><button type="button" class="mini-reorder-btn" data-ranking-down aria-label="Move ${esc(o)} down">↓</button></span></div>`).join('')}</div><div class="ranking-footer"><button class="btn primary-soft" type="button" data-ranking-confirm>Confirm ranking</button><span data-ranking-status>Not confirmed yet</span></div><input type="hidden" name="${b.id}" data-ranking-value></section>`}
function cardSortRuntime(b){
 const canAdd=b.mode==='open'||b.mode==='hybrid';const cats=b.mode==='open'?['Group 1','Group 2','Group 3']:(b.categories?.length?b.categories:['Category 1','Category 2']);const total=(b.cards||[]).length;
 const groups=cats.map(c=>sortGroupMarkup(c,b.mode==='open',b.mode==='open')).join('');
 return `<section class="participant-section card-sort-runtime" data-card-sort="${b.id}" data-required="${b.required?'true':'false'}" data-card-count="${total}" data-open="${canAdd?'true':'false'}"><div class="sort-title-row"><div><h3>${esc(b.title)}</h3><p class="muted">Drag cards into the group that makes most sense, or tap a card and then a group.${b.mode==='open'?' Rename or add groups if you want.':b.mode==='hybrid'?' You can add your own groups, while the predefined groups stay fixed.':''}</p></div><div class="sort-progress-chip"><b data-sort-placed>0</b><span>/ ${total} placed</span></div></div><div class="sort-bank-shell"><div class="sort-zone-head"><div><b>Unsorted</b><span>Pick up a card and place it below</span></div><span class="sort-count" data-bank-count>${total}</span></div><div class="sort-bank" data-sort-bank aria-label="Unsorted cards">${b.cards.map((c,i)=>`<button type="button" draggable="true" class="sort-card" data-card-key="${b.id}:${i}" data-card="${esc(c)}" aria-pressed="false"><span class="sort-card-grip" aria-hidden="true">⋮⋮</span><span>${esc(c)}</span></button>`).join('')}</div></div><div class="sort-columns" data-sort-columns>${groups}</div>${canAdd?'<button type="button" class="btn subtle add-sort-group" data-add-sort-group>+ Add group</button>':''}<div class="sort-live" data-sort-live aria-live="polite"></div><input type="hidden" name="${b.id}" data-sort-value></section>`
}
function sortGroupMarkup(c,editable=false,participantCreated=false){return `<div class="sort-group" data-group="${esc(c)}" data-participant-created="${participantCreated?'true':'false'}"><div class="sort-group-head">${editable?`<input class="sort-group-input" data-group-input value="${esc(c)}" aria-label="Group name">`:`<div class="sort-group-title">${esc(c)}</div>`}<div class="sort-group-meta"><span class="sort-count" data-group-count>0</span>${participantCreated?'<button type="button" class="sort-group-remove" data-remove-sort-group aria-label="Remove group" title="Remove group">×</button>':''}</div></div><div class="drop-zone" data-drop><div class="sort-empty-hint">Drop cards here</div></div></div>`}

function treeRuntime(b){return `<section class="participant-section tree-runtime" data-tree-test="${b.id}" data-required="${b.required?'true':'false'}" data-tree="${encodeURIComponent(b.tree)}">${richParticipantText(b,'task',b.task||'','participant-question',b.required)}<p class="muted">Choose where you would go, then explicitly select that location.</p><div class="tree-breadcrumb" data-breadcrumb>Start</div><div class="tree-options" data-tree-options>${treeTopNodes(b.tree).map(n=>`<button type="button" class="tree-choice" data-node="${esc(n)}">${esc(n)} <span>›</span></button>`).join('')}</div><div class="tree-actions"><button type="button" class="btn" data-tree-back disabled>← Back</button><button type="button" class="btn primary" data-tree-select disabled>Select this location</button></div><input type="hidden" name="${b.id}" data-tree-value><input type="hidden" name="${b.id}__journey" data-tree-journey></section>`}
function treeTopNodes(text){return parseTree(text).filter(n=>n.depth===0).map(n=>n.label)}
function parseTreeDetailed(text=''){
 const nodes=[],issues=[],siblingKeys=new Set();let prevDepth=0,lineNo=0;
 for(const raw of text.split(/\n/)){lineNo++;if(!raw.trim())continue;if(/^\s*\t/.test(raw)||raw.includes('\t'))issues.push(`Line ${lineNo}: use spaces, not tabs.`);const spaces=(raw.match(/^ */)||[''])[0].length;if(spaces%2)issues.push(`Line ${lineNo}: indentation must use two-space steps.`);const depth=Math.floor(spaces/2),label=raw.trim();if(!nodes.length&&depth!==0)issues.push('The first tree item must be at the top level.');if(nodes.length&&depth>prevDepth+1)issues.push(`Line ${lineNo}: indentation jumps over a level.`);const parentPath=[];for(let i=nodes.length-1;i>=0;i--){if(nodes[i].depth<depth&&parentPath[nodes[i].depth]===undefined)parentPath[nodes[i].depth]=nodes[i].label;if(nodes[i].depth===0)break}const parent=parentPath.filter(Boolean).join(' > ');const siblingKey=`${parent}::${label.toLowerCase()}`;if(siblingKeys.has(siblingKey))issues.push(`Line ${lineNo}: duplicate item “${label}” under the same parent.`);siblingKeys.add(siblingKey);nodes.push({label,depth,lineNo});prevDepth=depth}
 return {nodes,issues:[...new Set(issues)]}
}
function parseTree(text=''){return parseTreeDetailed(text).nodes}
function treeStructureIssues(text=''){return parseTreeDetailed(text).issues}

function childrenFor(text,path){const nodes=parseTree(text);if(!path.length)return nodes.filter(n=>n.depth===0).map(n=>n.label);let parentIndex=-1,parentDepth=-1;const wanted=path[path.length-1];let seenPath=[];for(let i=0;i<nodes.length;i++){const n=nodes[i];seenPath=seenPath.slice(0,n.depth);seenPath[n.depth]=n.label;if(seenPath.join(' > ')===path.join(' > ')){parentIndex=i;parentDepth=n.depth;break}}if(parentIndex<0)return[];const out=[];for(let i=parentIndex+1;i<nodes.length;i++){if(nodes[i].depth<=parentDepth)break;if(nodes[i].depth===parentDepth+1)out.push(nodes[i].label)}return out}


function bindRatingScaleInteractions(scope=document){
 scope.querySelectorAll('[data-rating-scale]').forEach(root=>{
   if(root.dataset.ratingScaleBound==='true'){syncRatingScale(root);return}
   root.dataset.ratingScaleBound='true';
   const buttons=[...root.querySelectorAll('[data-scale-value]')],field=root.querySelector('[data-scale-input]');
   function choose(button,{focus=true}={}){
     if(!button||!field)return;
     field.value=button.dataset.scaleValue||'';
     buttons.forEach(btn=>{const selected=btn===button;btn.classList.toggle('selected',selected);btn.setAttribute('aria-checked',selected?'true':'false');btn.tabIndex=selected?0:-1});
     if(focus)button.focus();
     updateProgress();
     if(root.closest('#participant-form'))scheduleParticipantDraftSave();
   }
   buttons.forEach((button,index)=>{
     button.addEventListener('click',()=>choose(button,{focus:false}));
     button.addEventListener('keydown',e=>{
       let next=index;
       if(['ArrowRight','ArrowUp'].includes(e.key))next=Math.min(buttons.length-1,index+1);
       else if(['ArrowLeft','ArrowDown'].includes(e.key))next=Math.max(0,index-1);
       else if(e.key==='Home')next=0;
       else if(e.key==='End')next=buttons.length-1;
       else if([' ','Enter'].includes(e.key)){e.preventDefault();choose(button);return}
       else return;
       e.preventDefault();choose(buttons[next]);
     })
   });
   syncRatingScale(root);
 })
}
function syncRatingScale(root){
 const field=root?.querySelector?.('[data-scale-input]'),value=String(field?.value||'');
 const buttons=[...(root?.querySelectorAll?.('[data-scale-value]')||[])];let focusSet=false;
 buttons.forEach(button=>{const selected=String(button.dataset.scaleValue)===value;button.classList.toggle('selected',selected);button.setAttribute('aria-checked',selected?'true':'false');if(selected){button.tabIndex=0;focusSet=true}else button.tabIndex=-1});
 if(!focusSet&&buttons[0])buttons[0].tabIndex=0;
}

