   const draw=()=>{const arr=items();arr.forEach((item,i)=>{const pos=item.querySelector('.ranking-position');if(pos)pos.textContent=i+1;const up=item.querySelector('[data-ranking-up]'),down=item.querySelector('[data-ranking-down]');if(up)up.disabled=i===0;if(down)down.disabled=i===arr.length-1});if(field.value){try{const saved=JSON.parse(field.value);if(JSON.stringify(saved)!==JSON.stringify(arr.map(x=>x.dataset.value)))field.value=''}catch{field.value=''}}if(status)status.textContent=field.value?'Ranking confirmed ✓':'Not confirmed yet';confirm?.classList.toggle('success',!!field.value);updateProgress()};
