function updateNavigationExtensionIndicators(){document.querySelectorAll('[data-nav-extension-state]').forEach(el=>{el.textContent=state.navExtensionAvailable?'Eve browser overlay connected':'Browser overlay not detected · manual completion remains available';el.dataset.connected=state.navExtensionAvailable?'true':'false'})}
function setupEveNavigationExtensionBridge(){
 if(window.__eveNavigationBridgeBound)return;window.__eveNavigationBridgeBound=true;
 window.addEventListener('message',event=>{
   if(event.source!==window||!event.data||event.data.source!=='eve-navigation-companion')return;
   const data=event.data;
   if(data.type==='EVE_NAV_EXTENSION_READY'){
     state.navExtensionAvailable=true;state.navExtensionVersion=data.version||null;updateNavigationExtensionIndicators();return
   }
   if(data.type==='EVE_NAV_TASK_STARTED'){
     document.querySelectorAll(`[data-navigation-task="${CSS.escape(String(data.taskId||''))}"] [data-nav-extension-state]`).forEach(el=>{el.textContent='Eve overlay opened on the task website';el.dataset.connected='true'});return
   }
   if(data.type==='EVE_NAV_TASK_ERROR'){
     toast(data.error||'The Eve browser overlay could not start. Use the manual completion controls instead.',3200,'error');return
   }
   if(data.type==='EVE_NAV_TASK_RESULT'&&data.result?.taskId){
     state.navExtensionResults[data.result.taskId]=data.result;
     document.querySelectorAll(`[data-navigation-task="${CSS.escape(String(data.result.taskId))}"]`).forEach(root=>root.__eveNavFinish?.(data.result.status,data.result));
     if(data.result.status==='completed'&&data.result.source==='eve-navigation-extension-auto')toast('Navigation task completed successfully.',3600,'success');
   }
 });
 window.postMessage({source:'eve-web',type:'EVE_NAV_EXTENSION_PING'},'*');
}
function startNavigationTaskWithExtension(root,startedAt){
 if(!state.navExtensionAvailable)return false;
 window.postMessage({source:'eve-web',type:'EVE_NAV_TASK_START',task:{taskId:root.dataset.navigationTask,instructions:root.dataset.instructions||'Complete the navigation task.',startPage:root.dataset.startPage||'',successPage:root.dataset.successPage||'',timeoutSeconds:Number(root.dataset.timeoutSeconds||0),startedAt,sourceUrl:location.href}},'*');
 return true
}
