function requiredControlIssue(container){
 for(const el of container.querySelectorAll('[required]:not(:disabled)')){
   let invalid=false,msg='Please complete this required field.';
   if(el.type==='radio'){const group=container.querySelectorAll(`input[type="radio"][name="${CSS.escape(el.name)}"]`);invalid=![...group].some(x=>x.checked);msg='Choose an answer before continuing.'}
   else if(el.type==='checkbox'){invalid=!el.checked;msg='Please confirm this before continuing.'}
   else if(el.type==='email'){invalid=!el.value.trim()||!el.checkValidity();msg='Enter a valid email address before continuing.'}
   else if(el.type==='number'){invalid=!String(el.value||'').trim()||!el.checkValidity();msg=el.validity?.rangeUnderflow||el.validity?.rangeOverflow?'Enter a number within the allowed range.':'Enter a valid number before continuing.'}
   else{invalid=!String(el.value||'').trim();msg='Please complete this required field before continuing.'}
   if(invalid)return {el,msg};
 }
 return null;
}
